package com.amtrollin.xtremetasker.ui.tasks;

import com.amtrollin.xtremetasker.enums.TaskSource;
import com.amtrollin.xtremetasker.enums.TaskTier;
import com.amtrollin.xtremetasker.models.XtremeTask;
import org.junit.Test;

import java.lang.reflect.Method;

import static org.junit.Assert.assertEquals;

public class TaskDetailsPopupTest
{
    @Test
    public void syncMismatchCopyKeepsCollectionLogSpecificMessage()
    {
        XtremeTask task = task(TaskSource.COLLECTION_LOG);

        assertEquals("You do not have enough CLOGs", TaskDetailsPopup.syncMismatchTitle(task));
        assertEquals("Open your Collection Log or mark task incomplete",
                TaskDetailsPopup.syncMismatchAction(task));
    }

    @Test
    public void syncMismatchCopyUsesGenericMessageForCombatAchievementsAndDiaries()
    {
        XtremeTask combatAchievement = task(TaskSource.COMBAT_ACHIEVEMENT);
        XtremeTask diary = task(TaskSource.DIARY_ACHIEVEMENT);

        assertEquals("Task not completed in-game", TaskDetailsPopup.syncMismatchTitle(combatAchievement));
        assertEquals("Mark task incomplete to keep task tracking accurate", TaskDetailsPopup.syncMismatchAction(combatAchievement));
        assertEquals("Task not completed in-game", TaskDetailsPopup.syncMismatchTitle(diary));
        assertEquals("Mark task incomplete to keep task tracking accurate", TaskDetailsPopup.syncMismatchAction(diary));
    }

    @Test
    public void taskDescriptionTimeNeverConvertsHoursToDays() throws Exception
    {
        Method method = TaskDetailsPopup.class.getDeclaredMethod("formatDuration", long.class);
        method.setAccessible(true);

        assertEquals("24h", method.invoke(null, 24L * 60L * 60L));
        assertEquals("54h 23m", method.invoke(null, (54L * 60L + 23L) * 60L));
    }

    private static XtremeTask task(TaskSource source)
    {
        return new XtremeTask(
                "test_" + source.name().toLowerCase(),
                "Test task",
                source,
                TaskTier.EASY,
                null,
                null,
                null,
                null,
                null,
                null,
                null
        );
    }
}

package com.amtrollin.xtremetasker.ui.rules;

import org.junit.Test;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;

import static org.junit.Assert.assertTrue;

public class RulesTabRendererTest
{
    @Test
    public void syncTabStillLaysOutFoundCompletionReviewAction()
    {
        BufferedImage image = new BufferedImage(700, 460, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try
        {
            FontMetrics fm = g.getFontMetrics();
            RulesTabRenderer renderer = new RulesTabRenderer(
                    690,
                    12,
                    16,
                    2,
                    new Color(221, 178, 85),
                    new Color(190, 190, 190)
            );

            RulesTabLayout layout = renderer.render(
                    g,
                    fm,
                    0,
                    40,
                    new Rectangle(0, 0, 690, 460),
                    RulesTabLayout.SubTab.DATA_SYNCS,
                    "CA/AD sync done! 1 new completed task(s) found.",
                    "Jun 26, 2026 1:23 PM",
                    1,
                    0
            );

            assertTrue(layout.syncCaFoundReviewButtonBounds.width > 0);
            assertTrue(layout.syncCaFoundReviewButtonBounds.height > 0);
        }
        finally
        {
            g.dispose();
        }
    }
}

package com.amtrollin.xtremetasker.ui.tasklist;

import org.junit.Test;

import java.lang.reflect.Method;

import static org.junit.Assert.assertEquals;

public class TaskRowsRendererTest
{
    @Test
    public void timeSpentKeepsMinutesForHourDurations() throws Exception
    {
        assertEquals("7m", formatDuration(7 * 60));
        assertEquals("59m", formatDuration(59 * 60 + 59));
        assertEquals("1h", formatDuration(60 * 60));
        assertEquals("1h 24m", formatDuration(84 * 60));
        assertEquals("3h 5m", formatDuration(185 * 60));
    }

    @Test
    public void timeSpentNeverConvertsHoursToDays() throws Exception
    {
        assertEquals("24h", formatDuration(24 * 60 * 60));
        assertEquals("48h", formatDuration(48 * 60 * 60));
        assertEquals("54h 23m", formatDuration((54 * 60 + 23) * 60));
    }

    private static String formatDuration(long seconds) throws Exception
    {
        Method method = TaskRowsRenderer.class.getDeclaredMethod("formatDuration", long.class);
        method.setAccessible(true);
        return (String) method.invoke(null, seconds);
    }
}

package com.amtrollin.xtremetasker.ui.text;

import org.junit.Test;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class TextUtilsTest
{
    @Test
    public void wrapTextKeepsParentheticalPhraseTogether()
    {
        FontMetrics fm = fontMetrics();
        String prefix = "Get reward from Tempor Tantrum";
        String suffix = "(Stormy key)";
        int maxWidth = Math.max(fm.stringWidth(prefix), fm.stringWidth(suffix));

        List<String> lines = TextUtils.wrapText(prefix + " " + suffix, fm, maxWidth);

        assertEquals(2, lines.size());
        assertEquals(prefix, lines.get(0));
        assertEquals(suffix, lines.get(1));
    }

    @Test
    public void wrapTextSplitsBetweenFullWords()
    {
        FontMetrics fm = fontMetrics();
        int maxWidth = fm.stringWidth("Get 1") + 1;

        List<String> lines = TextUtils.wrapText("Get 1 unique from boss", fm, maxWidth);

        assertTrue(lines.contains("unique"));
        for (String line : lines)
        {
            assertTrue("Line should not contain a partial unique split: " + line,
                    !line.contains("uni") || line.equals("unique"));
        }
    }

    private static FontMetrics fontMetrics()
    {
        BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setFont(new Font("Dialog", Font.PLAIN, 12));
        return graphics.getFontMetrics();
    }
}

package com.amtrollin.xtremetasker.verification;

import net.runelite.api.Client;
import net.runelite.api.events.ScriptPostFired;
import org.junit.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertEquals;

public class CollectionLogWidgetMonitorTest
{
    @Test
    public void collectionLogSetupRunsFullScanBeforeCallbackReturns() throws Exception
    {
        AtomicInteger scannedScript = new AtomicInteger(-1);
        Client client = (Client) Proxy.newProxyInstance(
                Client.class.getClassLoader(),
                new Class<?>[]{Client.class},
                (proxy, method, args) -> {
                    if ("getTickCount".equals(method.getName()))
                    {
                        return 100;
                    }
                    if ("runScript".equals(method.getName()))
                    {
                        Object[] scriptArgs = (Object[]) args[0];
                        scannedScript.set((Integer) scriptArgs[0]);
                        return null;
                    }
                    return primitiveDefault(method.getReturnType());
                });

        CollectionLogWidgetMonitor monitor = new CollectionLogWidgetMonitor();
        setField(monitor, "client", client);
        setField(monitor, "collectionLogService", new CollectionLogService());

        monitor.onScriptPostFired(new ScriptPostFired(7797));

        assertEquals("Full CLOG scan must run while setup/render context is active", 2240, scannedScript.get());
    }

    private static void setField(Object target, String name, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Object primitiveDefault(Class<?> type)
    {
        if (!type.isPrimitive() || type == void.class)
        {
            return null;
        }
        if (type == boolean.class)
        {
            return false;
        }
        if (type == char.class)
        {
            return '\0';
        }
        if (type == byte.class)
        {
            return (byte) 0;
        }
        if (type == short.class)
        {
            return (short) 0;
        }
        if (type == int.class)
        {
            return 0;
        }
        if (type == long.class)
        {
            return 0L;
        }
        if (type == float.class)
        {
            return 0F;
        }
        return 0D;
    }
}

package com.amtrollin.xtremetasker.verification;

import com.amtrollin.xtremetasker.models.PrerequisiteStatus;
import net.runelite.api.Varbits;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PrerequisiteTrackerServiceTest
{
    @Test
    public void barbarianFiremakingPartOneUsesBrutFireVarbit()
    {
        PrerequisiteTrackerService incompleteService = serviceWithBrutFireValue(0);
        List<PrerequisiteStatus> incomplete = incompleteService.evaluate("Part 1 of Barbarian Firemaking");
        assertFalse(incomplete.get(0).isCompleted());

        PrerequisiteTrackerService completeService = serviceWithBrutFireValue(1);
        List<PrerequisiteStatus> complete = completeService.evaluate("Part 1 of Barbarian Firemaking");
        assertTrue(complete.get(0).isCompleted());
    }

    @Test
    public void karamjaDiaryPrerequisiteUsesCompletionThreshold()
    {
        PrerequisiteTrackerService partialService = serviceWithVarbitValue(VarbitID.KARAMJA_EASY_COUNT, 1);
        List<PrerequisiteStatus> partial = partialService.evaluate("Complete the Karamja easy diary");
        assertFalse("Karamja diary varbit increments by task and should not complete at 1/10",
                partial.get(0).isCompleted());

        PrerequisiteTrackerService completeService = serviceWithVarbitValue(VarbitID.KARAMJA_EASY_COUNT, 10);
        List<PrerequisiteStatus> complete = completeService.evaluate("Complete the Karamja easy diary");
        assertTrue(complete.get(0).isCompleted());
    }

    @Test
    public void nonKaramjaDiaryPrerequisiteUsesPositiveVarbit()
    {
        PrerequisiteTrackerService service = serviceWithVarbitValue(Varbits.DIARY_ARDOUGNE_EASY, 1);
        List<PrerequisiteStatus> statuses = service.evaluate("Complete the Ardougne easy diary");
        assertTrue(statuses.get(0).isCompleted());
    }

    @Test
    public void shortDiaryPrerequisiteUsesVarbitAndDiaryIcon()
    {
        PrerequisiteTrackerService service = serviceWithVarbitValue(Varbits.DIARY_WILDERNESS_MEDIUM, 1);
        List<PrerequisiteStatus> statuses = service.evaluate("Wilderness Medium Diary");

        assertTrue(statuses.get(0).isCompleted());
        assertTrue(statuses.get(0).getMarkerIcons().contains(
                PrerequisiteStatus.MarkerIcon.ACHIEVEMENT_DIARY));
    }

    private static PrerequisiteTrackerService serviceWithBrutFireValue(int brutFireValue)
    {
        return serviceWithVarbitValue(VarbitID.BRUT_FIRE, brutFireValue);
    }

    private static PrerequisiteTrackerService serviceWithVarbitValue(int varbitId, int varbitValue)
    {
        return new PrerequisiteTrackerService(id -> id == varbitId ? varbitValue : 0);
    }
}

package com.amtrollin.xtremetasker;

import com.amtrollin.xtremetasker.enums.TaskSource;
import com.amtrollin.xtremetasker.enums.TaskTier;
import com.amtrollin.xtremetasker.models.XtremeTask;
import com.amtrollin.xtremetasker.models.persistence.PersistedState;
import com.amtrollin.xtremetasker.models.verification.TaskVerification;
import com.amtrollin.xtremetasker.ui.XtremeTaskerOverlay;
import com.amtrollin.xtremetasker.verification.CollectionLogService;
import com.amtrollin.xtremetasker.verification.CombatAchievementService;
import com.amtrollin.xtremetasker.verification.PrerequisiteTrackerService;
import com.google.gson.Gson;
import org.junit.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Collections;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class CollectionLogMismatchTest
{
    @Test
    public void collectionLogRequirementNotFoundBySyncIsMarkedAsMismatch() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        CollectionLogService collectionLogService = new CollectionLogService();
        plugin.setCollectionLogServiceForTesting(collectionLogService);

        TaskVerification verification = new Gson().fromJson(
                "{\"method\":\"collection-log\",\"itemIds\":[10878],\"count\":1}",
                TaskVerification.class
        );

        XtremeTask task = new XtremeTask(
                "collection_log_easy_get-a-green-satchel_001_test",
                "Get a Green satchel",
                TaskSource.COLLECTION_LOG,
                TaskTier.EASY,
                null,
                null,
                null,
                null,
                null,
                verification,
                null
        );

        List<XtremeTask> tasks = plugin.tasksForTesting();
        tasks.clear();
        tasks.add(task);

        Set<String> syncedCompletedTaskIds = plugin.syncedCompletedTaskIdsForTesting();
        syncedCompletedTaskIds.clear();
        syncedCompletedTaskIds.add(task.getId());

        collectionLogService.storeSeenItem(10878);
        collectionLogService.markSyncSeen();
        List<XtremeTask> mismatchesWhenNotFound = plugin.findCollectionLogSyncMismatches(true);
        assertEquals("Completed CLOG requirement not found by sync should mismatch", 1, mismatchesWhenNotFound.size());
        assertEquals(task.getId(), mismatchesWhenNotFound.get(0).getId());

        collectionLogService.storeItem(10878);
        List<XtremeTask> mismatchesWhenObtained = plugin.findCollectionLogSyncMismatches(true);
        assertTrue("Obtained requirement should no longer mismatch", mismatchesWhenObtained.isEmpty());
    }

    @Test
    public void manuallyCompletedCollectionLogTaskIsNotMarkedMismatchBeforeSyncEvidence() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        plugin.setCollectionLogServiceForTesting(new CollectionLogService());

        XtremeTask task = collectionLogTask(
                "collection_log_easy_get-a-green-satchel_001_manual_no_sync_test",
                "Get a Green satchel",
                TaskTier.EASY,
                new int[]{10878},
                1
        );

        List<XtremeTask> tasks = plugin.tasksForTesting();
        tasks.clear();
        tasks.add(task);

        Set<String> manualCompletedTaskIds = plugin.manualCompletedTaskIdsForTesting();
        manualCompletedTaskIds.clear();
        manualCompletedTaskIds.add(task.getId());

        List<XtremeTask> mismatches = plugin.findCollectionLogSyncMismatches(true);
        assertTrue("Manual CLOG completion should not mismatch until a sync has seen the relevant log slot",
                mismatches.isEmpty());
    }

    @Test
    public void quietCollectionLogOpenStoresMismatchForCompletedMissingClog() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        CollectionLogService collectionLogService = new CollectionLogService();
        plugin.setCollectionLogServiceForTesting(collectionLogService);

        XtremeTask task = collectionLogTask(
                "collection_log_easy_get-a-green-satchel_001_quiet_sync_test",
                "Get a Green satchel",
                TaskTier.EASY,
                new int[]{10878},
                1
        );

        plugin.tasksForTesting().clear();
        plugin.tasksForTesting().add(task);
        plugin.manualCompletedTaskIdsForTesting().clear();
        plugin.manualCompletedTaskIdsForTesting().add(task.getId());

        assertTrue("Completing manually alone should not show the CLOG mismatch helper",
                !plugin.isCollectionLogTaskSyncMismatch(task));

        collectionLogService.storeSeenItem(10878);
        collectionLogService.markSyncSeen();

        assertTrue("Opening CLOG and seeing the missing slot should show the CLOG mismatch helper",
                plugin.isCollectionLogTaskSyncMismatch(task));
        assertEquals(List.of(task.getId()), plugin.syncMismatchTaskIdsForTesting());
    }

    @Test
    public void fullCollectionLogSyncStoresMismatchWithoutOpeningSpecificPage() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        CollectionLogService collectionLogService = new CollectionLogService();
        plugin.setCollectionLogServiceForTesting(collectionLogService);

        XtremeTask task = collectionLogTask(
                "collection_log_easy_get-a-green-satchel_001_full_sync_test",
                "Get a Green satchel",
                TaskTier.EASY,
                new int[]{10878},
                1
        );

        plugin.tasksForTesting().clear();
        plugin.tasksForTesting().add(task);
        plugin.manualCompletedTaskIdsForTesting().clear();
        plugin.manualCompletedTaskIdsForTesting().add(task.getId());

        assertTrue("Completing manually alone should not show the CLOG mismatch helper",
                !plugin.isCollectionLogTaskSyncMismatch(task));

        collectionLogService.markFullSyncSeen();

        assertTrue("A full CLOG sync should prove a manually completed missing CLOG is mismatched",
                plugin.isCollectionLogTaskSyncMismatch(task));
        assertEquals(List.of(task.getId()), plugin.syncMismatchTaskIdsForTesting());
    }

    @Test
    public void oldCollectionLogSyncDoesNotMismatchTaskCompletedAfterSync() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        CollectionLogService collectionLogService = new CollectionLogService();
        plugin.setCollectionLogServiceForTesting(collectionLogService);

        XtremeTask task = collectionLogTask(
                "collection_log_easy_get-a-green-satchel_001_old_sync_test",
                "Get a Green satchel",
                TaskTier.EASY,
                new int[]{10878},
                1
        );

        plugin.tasksForTesting().clear();
        plugin.tasksForTesting().add(task);

        collectionLogService.markFullSyncSeen();
        Thread.sleep(5L);
        plugin.manualCompletedTaskIdsForTesting().add(task.getId());
        plugin.manualCompletionTimestampsForTesting().put(task.getId(), System.currentTimeMillis());

        assertTrue("A sync that happened before manual completion should not show the CLOG mismatch helper",
                plugin.findCollectionLogSyncMismatches(true).isEmpty());
        assertTrue("Task details should not inherit stale pre-completion CLOG sync evidence",
                !plugin.isCollectionLogTaskSyncMismatch(task));

        Thread.sleep(5L);
        collectionLogService.markFullSyncSeen();

        assertTrue("A new CLOG sync after manual completion should show the CLOG mismatch helper",
                plugin.isCollectionLogTaskSyncMismatch(task));
        assertEquals(List.of(task.getId()), plugin.syncMismatchTaskIdsForTesting());
    }

    @Test
    public void collectionLogCompletionCandidateSurvivesCaAdSyncRefresh() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        CollectionLogService collectionLogService = new CollectionLogService();
        plugin.setCollectionLogServiceForTesting(collectionLogService);

        XtremeTask task = collectionLogTask(
                "collection_log_easy_get-a-green-satchel_001_candidate_preserve_test",
                "Get a Green satchel",
                TaskTier.EASY,
                new int[]{10878},
                1
        );

        plugin.tasksForTesting().clear();
        plugin.tasksForTesting().add(task);

        collectionLogService.storeItem(10878);
        assertEquals("Opening CLOG should populate CLOG completion candidates",
                List.of(task.getId()),
                taskIds(plugin.getSyncCompletionCandidateTasks(TaskSource.COLLECTION_LOG)));

        invokeRefreshCollectionLogNonItemSyncState(plugin);

        assertEquals("CA/AD sync refresh should not clear CLOG candidates captured from opening CLOG",
                List.of(task.getId()),
                taskIds(plugin.getSyncCompletionCandidateTasks(TaskSource.COLLECTION_LOG)));
    }

    @Test
    public void diaryAchievementCompletionCandidateIsStoredForReview() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        plugin.setCollectionLogServiceForTesting(new CollectionLogService());
        plugin.setPrerequisiteTrackerServiceForTesting(new StubPrerequisiteTrackerService(true));

        XtremeTask task = diaryAchievementTask(
                "achievement_diary_easy_complete-the-ardougne-easy-diary_sync_review_test",
                "Complete the Ardougne easy diary"
        );

        plugin.tasksForTesting().clear();
        plugin.tasksForTesting().add(task);

        assertEquals("Completed AD should be included in the reported sync count",
                1, invokeRefreshCollectionLogNonItemSyncState(plugin));
        assertEquals("Completed AD should remain available to the completion review",
                List.of(task.getId()),
                taskIds(plugin.getSyncCompletionCandidateTasks(TaskSource.COLLECTION_LOG)));
    }

    @Test
    public void collectionLogMismatchSyncEvidencePersistsAcrossSessions() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        CollectionLogService collectionLogService = new CollectionLogService();
        plugin.setCollectionLogServiceForTesting(collectionLogService);

        XtremeTask task = collectionLogTask(
                "collection_log_easy_get-a-green-satchel_001_persisted_sync_test",
                "Get a Green satchel",
                TaskTier.EASY,
                new int[]{10878},
                1
        );

        plugin.tasksForTesting().clear();
        plugin.tasksForTesting().add(task);
        plugin.manualCompletedTaskIdsForTesting().add(task.getId());
        plugin.manualCompletionTimestampsForTesting().put(task.getId(), System.currentTimeMillis() - 1_000L);
        collectionLogService.markFullSyncSeen();
        assertTrue(plugin.isCollectionLogTaskSyncMismatch(task));

        Method buildState = XtremeTaskerPlugin.class.getDeclaredMethod("buildPersistedState");
        buildState.setAccessible(true);
        PersistedState state = (PersistedState) buildState.invoke(plugin);

        XtremeTaskerPlugin restoredPlugin = new XtremeTaskerPlugin();
        CollectionLogService restoredCollectionLogService = new CollectionLogService();
        restoredPlugin.setCollectionLogServiceForTesting(restoredCollectionLogService);
        restoredPlugin.tasksForTesting().clear();
        restoredPlugin.tasksForTesting().add(task);

        Method applyState = XtremeTaskerPlugin.class.getDeclaredMethod("applyPersistedState", PersistedState.class);
        applyState.setAccessible(true);
        applyState.invoke(restoredPlugin, state);

        assertTrue("Persisted CLOG sync evidence should keep the mismatch helper visible after login",
                restoredPlugin.isCollectionLogTaskSyncMismatch(task));
        assertEquals(List.of(task.getId()), restoredPlugin.syncMismatchTaskIdsForTesting());
    }

    @Test
    public void pendingAmbiguousCollectionLogDropCountsPersistUntilFullSync() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        CollectionLogService collectionLogService = new CollectionLogService();
        plugin.setCollectionLogServiceForTesting(collectionLogService);
        collectionLogService.restorePendingDropCounts(2, 1);

        Method buildState = XtremeTaskerPlugin.class.getDeclaredMethod("buildPersistedState");
        buildState.setAccessible(true);
        PersistedState state = (PersistedState) buildState.invoke(plugin);

        XtremeTaskerPlugin restoredPlugin = new XtremeTaskerPlugin();
        CollectionLogService restoredCollectionLogService = new CollectionLogService();
        restoredPlugin.setCollectionLogServiceForTesting(restoredCollectionLogService);

        Method applyState = XtremeTaskerPlugin.class.getDeclaredMethod("applyPersistedState", PersistedState.class);
        applyState.setAccessible(true);
        applyState.invoke(restoredPlugin, state);

        assertEquals("Pending Ancient page drops should survive restore until CLOG sync",
                2,
                restoredPlugin.getPendingAncientPageDropCountSinceLastSync());
        assertEquals("Pending Medallion fragment drops should survive restore until CLOG sync",
                1,
                restoredPlugin.getPendingMedallionFragmentDropCountSinceLastSync());

        restoredCollectionLogService.markFullSyncSeen();

        assertEquals("Full CLOG sync should clear restored pending Ancient page drops",
                0,
                restoredPlugin.getPendingAncientPageDropCountSinceLastSync());
        assertEquals("Full CLOG sync should clear restored pending Medallion fragment drops",
                0,
                restoredPlugin.getPendingMedallionFragmentDropCountSinceLastSync());
    }

    @Test
    public void combatAchievementMismatchRequiresSyncAfterCompletion() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        plugin.setCollectionLogServiceForTesting(new CollectionLogService());
        plugin.setCombatAchievementServiceForTesting(new StubCombatAchievementService(false));

        XtremeTask task = combatAchievementTask(
                "combat_achievement_easy_missing_after_sync_test",
                "Missing CA after sync",
                7
        );

        plugin.tasksForTesting().clear();
        plugin.tasksForTesting().add(task);

        invokeRefreshCombatAchievementSyncState(plugin);
        Thread.sleep(5L);
        plugin.manualCompletedTaskIdsForTesting().add(task.getId());
        plugin.manualCompletionTimestampsForTesting().put(task.getId(), System.currentTimeMillis());

        assertTrue("A CA sync before completion should not prove the completed task is mismatched",
                plugin.syncMismatchTaskIdsForTesting().isEmpty());
        assertTrue("Old CA sync evidence should be ignored on task details",
                !plugin.isTaskSyncMismatch(task));

        Thread.sleep(5L);
        invokeRefreshCombatAchievementSyncState(plugin);

        assertEquals("A CA sync after completion should show the mismatch helper when the CA is not complete in-game",
                List.of(task.getId()), plugin.syncMismatchTaskIdsForTesting());
        assertTrue(plugin.isTaskSyncMismatch(task));
    }

    @Test
    public void combatAchievementMismatchSyncEvidencePersistsAcrossSessions() throws Exception
    {
        XtremeTaskerPlugin plugin = new XtremeTaskerPlugin();
        plugin.setCollectionLogServiceForTesting(new CollectionLogService());
        plugin.setCombatAchievementServiceForTesting(new StubCombatAchievementService(false));

        XtremeTask task = combatAchievementTask(
                "combat_achievement_easy_persisted_mismatch_test",
                "Persisted CA mismatch",
                8
        );

        plugin.tasksForTesting().clear();
        plugin.tasksForTesting().add(task);
        plugin.manualCompletedTaskIdsForTesting().add(task.getId());
        plugin.manualCompletionTimestampsForTesting().put(task.getId(), System.currentTimeMillis() - 1_000L);

        invokeRefreshCombatAchievementSyncState(plugin);
        assertEquals(List.of(task.getId()), plugin.syncMismatchTaskIdsForTesting());

        Method buildState = XtremeTaskerPlugin.class.getDeclaredMethod("buildPersistedState");
        buildState.setAccessible(true);
        PersistedState state = (PersistedState) buildState.invoke(plugin);

