    @Override
    public List<XtremeTask> getSyncMismatchTasks()
    {
        int capturedItemCount = collectionLogService == null ? -1 : collectionLogService.getCapturedItemCount();
        int idsHash = syncMismatchTaskIds.hashCode();
        int manualHash = manualCompletedTaskIds.hashCode();
        int syncedHash = syncedCompletedTaskIds.hashCode();
        int taskCount = tasks.size();
        if (syncMismatchTasksCacheValid
                && idsHash == syncMismatchTasksCacheIdsHash
                && manualHash == syncMismatchTasksCacheManualHash
                && syncedHash == syncMismatchTasksCacheSyncedHash
                && taskCount == syncMismatchTasksCacheTaskCount
                && capturedItemCount == syncMismatchTasksCacheCapturedItemCount)
        {
            return syncMismatchTasksCache;
        }

        pruneResolvedSyncMismatches();
        if (syncMismatchTaskIds.isEmpty())
        {
            updateSyncMismatchTasksCache(Collections.emptyList(), capturedItemCount);
            return syncMismatchTasksCache;
        }

        Map<String, XtremeTask> byId = tasksById();
        List<XtremeTask> out = new ArrayList<>();
        for (String id : syncMismatchTaskIds)
        {
            XtremeTask task = byId.get(id);
            if (task != null && isTaskCompleted(task))
            {
                out.add(decorateCurrentSequenceTask(task));
            }
        }
        updateSyncMismatchTasksCache(out, capturedItemCount);
        return syncMismatchTasksCache;
    }

    private void updateSyncMismatchTasksCache(List<XtremeTask> tasks, int capturedItemCount)
    {
        syncMismatchTasksCache = Collections.unmodifiableList(new ArrayList<>(tasks));
        syncMismatchTasksCacheValid = true;
        syncMismatchTasksCacheIdsHash = syncMismatchTaskIds.hashCode();
        syncMismatchTasksCacheManualHash = manualCompletedTaskIds.hashCode();
        syncMismatchTasksCacheSyncedHash = syncedCompletedTaskIds.hashCode();
        syncMismatchTasksCacheTaskCount = this.tasks.size();
        syncMismatchTasksCacheCapturedItemCount = capturedItemCount;
    }

    private void pruneResolvedSyncMismatches()
    {
        boolean changed = pruneResolvedCollectionLogSyncMismatches();
        changed |= pruneInvalidCombatAchievementSyncMismatches();
        if (changed)
        {
            markDirtyAndPersist();
        }
    }

    private boolean pruneResolvedCollectionLogSyncMismatches()
    {
        if (syncMismatchTaskIds.isEmpty()
                || collectionLogService == null)
        {
            return false;
        }

        Map<String, XtremeTask> byId = tasksById();

        boolean hasCollectionLogItemMismatch = false;
        for (String id : syncMismatchTaskIds)
        {
            XtremeTask task = byId.get(id);
            TaskVerification verification = task == null ? null : task.getVerification();
            if (task != null
                    && task.getSource() == TaskSource.COLLECTION_LOG
                    && verification != null
                    && verification.getType() == TaskVerification.VerificationType.COLLECTION_LOG)
            {
                hasCollectionLogItemMismatch = true;
                break;
            }
        }
        if (!hasCollectionLogItemMismatch)
        {
            return false;
        }

        Set<String> currentCollectionLogMismatchIds = findCollectionLogItemSyncMismatchIds();

        boolean changed = syncMismatchTaskIds.removeIf(id -> {
            XtremeTask task = byId.get(id);
            TaskVerification verification = task == null ? null : task.getVerification();
            return task != null
                    && task.getSource() == TaskSource.COLLECTION_LOG
                    && verification != null
                    && verification.getType() == TaskVerification.VerificationType.COLLECTION_LOG
                    && !currentCollectionLogMismatchIds.contains(id);
        });

        if (changed)
        {
            if (syncMismatchTaskIds.isEmpty())
            {
                updateSyncMismatchTitle();
            }
        }
        return changed;
    }

    private boolean pruneInvalidCombatAchievementSyncMismatches()
    {
        if (syncMismatchTaskIds.isEmpty())
        {
            return false;
        }

        Map<String, XtremeTask> byId = tasksById();
        boolean changed = syncMismatchTaskIds.removeIf(id -> {
            XtremeTask task = byId.get(id);
            if (task == null || task.getSource() != TaskSource.COMBAT_ACHIEVEMENT)
            {
                return false;
            }
            if (!isTaskCompleted(task) || !hasCombatAchievementSyncAfterCompletion(task))
            {
                return true;
            }

            Integer taskId = resolveCombatAchievementTaskId(task);
            return taskId != null && combatAchievementService.isTaskComplete(taskId);
        });
        if (changed && syncMismatchTaskIds.isEmpty())
        {
            updateSyncMismatchTitle();
        }
        return changed;
    }

    private Set<String> findCollectionLogItemSyncMismatchIds()
    {
        Set<String> mismatchIds = new HashSet<>();
        Set<String> processedCountedGroups = new HashSet<>();

        for (XtremeTask task : tasks)
        {
            if (task == null || task.getSource() != TaskSource.COLLECTION_LOG || !isTaskCompleted(task))
            {
                continue;
            }

            TaskVerification verification = task.getVerification();
            if (verification == null || verification.getType() != TaskVerification.VerificationType.COLLECTION_LOG)
            {
                continue;
            }

            if (isCountedCollectionLogSync(verification))
            {
                if (!hasCollectionLogSyncEvidence(task, verification))
                {
                    continue;
                }

                String groupKey = countedCollectionLogGroupKey(task, verification);
                if (groupKey == null || !processedCountedGroups.add(groupKey))
                {
                    continue;
                }

                int observedCount = observedCollectionLogSyncCount(task, verification);
                List<XtremeTask> group = countedCollectionLogGroupFor(task, verification);
                if (observedCount < 0)
                {
                    addCompletedTaskIdsFromGroup(mismatchIds, group);
                    continue;
                }

                int desiredCompleted = desiredCompletedForCountedGroup(group, observedCount);
                List<XtremeTask> completedGroup = completedTasksFromGroupInGroupOrder(group);
                for (int i = desiredCompleted; i < completedGroup.size(); i++)
                {
                    XtremeTask mismatchedTask = completedGroup.get(i);
                    if (mismatchedTask != null && mismatchedTask.getId() != null)
                    {
                        mismatchIds.add(mismatchedTask.getId());
                    }
                }
                continue;
            }

            boolean completeInGame;
            if (!hasCollectionLogSyncEvidence(task, verification))
            {
                continue;
            }

            if (hasCollectionLogCompletionItem(verification))
            {
                completeInGame = isCollectionLogItemObtained(verification.getCompletionItemId());
            }
            else
            {
                ItemRequirement requirement = resolveCollectionLogRequirement(task);
                completeInGame = requirement != null
                        && countObtainedCollectionLogItems(requirement.itemIds) >= requirement.requiredCount;
            }

            if (!completeInGame)
            {
                mismatchIds.add(task.getId());
            }
        }

        return mismatchIds;
    }

    private void addCompletedTaskIdsFromGroup(Set<String> mismatchIds, List<XtremeTask> group)
    {
        if (mismatchIds == null || group == null || group.isEmpty())
        {
            return;
        }

        for (XtremeTask groupedTask : completedTasksFromGroupInGroupOrder(group))
        {
            if (groupedTask != null && groupedTask.getId() != null)
            {
                mismatchIds.add(groupedTask.getId());
            }
        }
    }

    @Override
    public List<XtremeTask> getSyncMismatchTasks(TaskSource source)
    {
        if (source == null)
        {
            return getSyncMismatchTasks();
        }

        return getSyncMismatchTasks().stream()
                .filter(task -> matchesSyncMismatchSource(task, source))
                .collect(Collectors.toList());
    }

    @Override
    public void refreshTaskSyncMismatchForTask(XtremeTask task)
    {
        if (task == null)
        {
            return;
        }

        Runnable refresh = () -> refreshTaskSyncMismatchForTaskOnClientThread(task);
        if (clientThread == null)
        {
            refresh.run();
            return;
        }
        clientThread.invokeLater(refresh);
    }

    private void refreshTaskSyncMismatchForTaskOnClientThread(XtremeTask task)
    {
        if (task == null || !hasTaskPackLoaded())
        {
            return;
        }
        if (client != null && client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        List<XtremeTask> candidates = getTaskGroupInstances(task);
        if (candidates == null || candidates.isEmpty())
        {
            candidates = Collections.singletonList(task);
        }

        boolean changed = false;
        for (XtremeTask candidate : candidates)
        {
            if (candidate == null
                    || candidate.getId() == null
                    || !isTaskCompleted(candidate)
                    || !isPassiveSyncMismatchSource(candidate))
            {
                continue;
            }

            Boolean completeInGame = passiveSyncGameCompletion(candidate);
            if (completeInGame == null)
            {
                continue;
            }

            if (completeInGame)
            {
                changed |= syncMismatchTaskIds.remove(candidate.getId());
            }
            else if (candidate.getSource() == TaskSource.COMBAT_ACHIEVEMENT
                    && !hasCombatAchievementSyncAfterCompletion(candidate))
            {
                continue;
            }
            else if (!syncMismatchTaskIds.contains(candidate.getId()))
            {
                syncMismatchTaskIds.add(candidate.getId());
                changed = true;
            }
        }

        if (!changed)
        {
            return;
        }

        updateSyncMismatchTitle();
        syncMismatchTasksCacheValid = false;
        markDirtyAndPersist();
    }

    private static boolean isPassiveSyncMismatchSource(XtremeTask task)
    {
        TaskSource source = task == null ? null : task.getSource();
        return source == TaskSource.DIARY_ACHIEVEMENT
                || source == TaskSource.COMBAT_ACHIEVEMENT;
    }

    private Boolean passiveSyncGameCompletion(XtremeTask task)
    {
        if (task == null)
        {
            return null;
        }

        TaskSource source = task.getSource();
        TaskVerification verification = task.getVerification();
        if (source == TaskSource.DIARY_ACHIEVEMENT)
        {
            if (verification == null
                    || verification.getRegion() == null
                    || verification.getDifficulty() == null)
            {
                return null;
            }
            return prerequisiteTrackerService.isDiaryComplete(verification.getRegion(), verification.getDifficulty());
        }

        if (source == TaskSource.COMBAT_ACHIEVEMENT)
        {
            if (caTaskIdsByName.isEmpty())
            {
                loadCombatAchievementMappings();
            }

            Integer taskId = resolveCombatAchievementTaskId(task);
            if (taskId == null)
            {
                return null;
            }
            return combatAchievementService.isTaskComplete(taskId);
        }

        return null;
    }

    private void markCombatAchievementSyncSeen()
    {
        combatAchievementLastSyncSeenAtMillis = System.currentTimeMillis();
    }

    private boolean hasCombatAchievementSyncAfterCompletion(XtremeTask task)
    {
        if (task == null)
        {
            return false;
        }

        CompletionInfo completionInfo = getCompletionInfo(task);
        long completedAt = completionInfo == null ? 0L : Math.max(0L, completionInfo.timestamp);
        return combatAchievementLastSyncSeenAtMillis > 0L
                && combatAchievementLastSyncSeenAtMillis > completedAt;
    }

    @Override
    public boolean isTaskSyncMismatch(XtremeTask task)
    {
        TaskSource source = syncMismatchSourceForTask(task);
        if (task == null || task.getId() == null || source == null)
        {
            return false;
        }

        Set<String> relevantIds = taskAndGroupIds(task);
        for (XtremeTask mismatch : getSyncMismatchTasks(source))
        {
            if (mismatch != null && relevantIds.contains(mismatch.getId()))
            {
                return true;
            }
        }
        return false;
    }

    @Override
    public boolean isCollectionLogTaskSyncMismatch(XtremeTask task)
    {
        return task != null
                && isCollectionLogSyncSource(task.getSource())
                && isTaskSyncMismatch(task);
    }

    @Override
    public void dismissTaskSyncMismatchAndPersist(XtremeTask task)
    {
        if (task == null)
        {
            return;
        }

        Set<String> relevantIds = taskAndGroupIds(task);
        if (relevantIds.isEmpty())
        {
            return;
        }

        boolean changed = syncMismatchTaskIds.removeIf(relevantIds::contains);
        if (!changed)
        {
            return;
        }

        updateSyncMismatchTitle();
        syncMismatchTasksCacheValid = false;
        markDirtyAndPersist();
    }

    @Override
    public void dismissCollectionLogTaskSyncMismatchAndPersist(XtremeTask task)
    {
        if (task != null && isCollectionLogSyncSource(task.getSource()))
        {
            dismissTaskSyncMismatchAndPersist(task);
        }
    }

    private static TaskSource syncMismatchSourceForTask(XtremeTask task)
    {
        if (task == null)
        {
            return null;
        }

        TaskSource source = task.getSource();
        if (isCollectionLogSyncSource(source))
        {
            return TaskSource.COLLECTION_LOG;
        }
        if (source == TaskSource.COMBAT_ACHIEVEMENT)
        {
            return TaskSource.COMBAT_ACHIEVEMENT;
        }
        return null;
    }

    private Set<String> taskAndGroupIds(XtremeTask task)
    {
        if (task == null || task.getId() == null)
        {
            return Collections.emptySet();
        }

        Set<String> ids = new HashSet<>();
        List<XtremeTask> group = getTaskGroupInstances(task);
        if (group != null)
        {
            for (XtremeTask groupedTask : group)
            {
                if (groupedTask != null && groupedTask.getId() != null)
                {
                    ids.add(groupedTask.getId());
                }
            }
        }
        ids.add(task.getId());
        return ids;
    }

    private static boolean matchesSyncMismatchSource(XtremeTask task, TaskSource source)
    {
        if (task == null || source == null)
        {
            return false;
        }

        if (source == TaskSource.COLLECTION_LOG)
        {
            return isCollectionLogSyncSource(task.getSource());
        }

        return task.getSource() == source;
    }

    @Override
    public List<XtremeTask> getSyncCompletionCandidateTasks(TaskSource source)
    {
        if (syncCompletionCandidateTaskIds.isEmpty())
        {
            return Collections.emptyList();
        }

        Map<String, XtremeTask> byId = tasksById();

        List<XtremeTask> out = new ArrayList<>();
        boolean changed = false;
        for (String id : syncCompletionCandidateTaskIds)
        {
            XtremeTask task = byId.get(id);
            if (task == null || isTaskCompleted(task) || isCurrentTaskId(id))
            {
                changed = true;
                continue;
            }

            if (source == null || matchesSyncMismatchSource(task, source))
            {
                out.add(decorateCurrentSequenceTask(task));
            }
        }

        if (changed)
        {
            syncCompletionCandidateTaskIds.removeIf(id -> {
                XtremeTask task = byId.get(id);
                return task == null || isTaskCompleted(task) || isCurrentTaskId(id);
            });
            markDirtyAndPersist();
        }

        return out;
    }

    @Override
    public void dismissSyncCompletionCandidateReview(TaskSource source)
    {
        if (source == null)
        {
            syncCompletionCandidateTaskIds.clear();
        }
        else
        {
            Map<String, XtremeTask> byId = tasksById();
            removeSyncIdsForSource(syncCompletionCandidateTaskIds, source, byId);
        }

        markDirtyAndPersist();
    }

    @Override
    public void markSyncCompletionCandidateTasksCompleteAndPersist(List<XtremeTask> tasksToMark)
    {
        if (tasksToMark == null || tasksToMark.isEmpty())
        {
            return;
        }

        Set<String> ids = tasksToMark.stream()
                .filter(Objects::nonNull)
                .map(XtremeTask::getId)
                .filter(id -> id != null && !id.trim().isEmpty())
                .filter(id -> !isCurrentTaskId(id))
                .collect(Collectors.toSet());
        if (ids.isEmpty())
        {
            return;
        }

        long now = System.currentTimeMillis();
        for (String id : ids)
        {
            XtremeTask task = findTaskById(id);
            if (task == null || isTaskCompleted(task))
            {
                continue;
            }

            syncedCompletedTaskIds.add(id);
            syncedCompletionTimestamps.putIfAbsent(id, now);
            recordCompletedTaskTime(id);
        }

        syncCompletionCandidateTaskIds.removeAll(ids);
        rebuildTierCounts();
        markDirtyAndPersist();
    }

