package com.amtrollin.xtremetasker.ui.input;

import com.amtrollin.xtremetasker.ui.XtremeTaskerOverlay;
import com.amtrollin.xtremetasker.models.XtremeTask;
import java.awt.*;
import java.awt.event.MouseWheelEvent;
import java.util.List;
import lombok.RequiredArgsConstructor;
import net.runelite.client.input.MouseWheelListener;

@RequiredArgsConstructor
public final class OverlayWheelHandler implements MouseWheelListener
{
    private final XtremeTaskerOverlay a;

    @Override
    public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
    {
        if (!a.plugin().isOverlayEnabled() || !a.isPanelOpen())
        {
            return e;
        }

        e.consume();
        Point p = e.getPoint();

        double precise = e.getPreciseWheelRotation();
        if (precise == 0.0)
        {
            return e;
        }

        if (a.isSyncMismatchReviewOpen() && a.syncMismatchReviewBounds().contains(p))
        {
            int taskCount = a.syncMismatchVisibleTaskCount();
            a.syncMismatchScroll().onWheel(
                    precise,
                    a.syncMismatchViewportBounds().height,
                    a.syncMismatchRowBlock(),
                    taskCount <= 0 ? 1 : taskCount,
                    null
            );
            a.client().getCanvas().repaint();
            return e;
        }

        // ------------------------------------------
        // DETAILS POPUP scroll (highest priority)
        // ------------------------------------------
        if (a.isTaskDetailsOpen() && a.taskDetailsViewportBounds().contains(p))
        {
            if (a.taskDetailsViewportBounds().height <= 0)
            {
                return e;
            }

            int total = a.taskDetailsTotalContentRows();
            a.taskDetailsScroll().onWheel(
                    precise,
                    a.taskDetailsViewportBounds().height,
                    a.taskDetailsRowBlock(),
                    total <= 0 ? 1 : total,
                    null
            );
            return e;
        }


        // TASKS scroll
        if (a.activeTab() == XtremeTaskerOverlay.MainTab.TASKS && a.taskListViewportBounds().contains(p))
        {
            Rectangle vp = a.taskListViewportBounds();
            if (vp.height <= 0)
            {
                return e;
            }

            List<XtremeTask> tasks = a.getSortedTasksForTier(a.activeTier());
            int total = tasks.size();

            a.taskListView().onWheel(
                    precise,
                    vp.height,
                    a.tasksRowBlock(),
                    total
            );

            return e;
        }

        // CURRENT scroll
        if (a.activeTab() == XtremeTaskerOverlay.MainTab.CURRENT && a.currentViewportBounds().contains(p))
        {
            Rectangle cvp = a.currentViewportBounds();
            if (cvp.height <= 0) return e;
            int logicalRowBlock = com.amtrollin.xtremetasker.ui.style.UiConstants.ROW_HEIGHT;
            int totalRows = (a.currentLayout().totalContentPx + logicalRowBlock - 1) / logicalRowBlock;
            a.currentScroll().onWheel(precise, cvp.height, a.currentRowBlock(), totalRows <= 0 ? 1 : totalRows, null);
            return e;
        }

        return e;
    }
}

package com.amtrollin.xtremetasker.ui.input;

import com.amtrollin.xtremetasker.ui.XtremeTaskerOverlay;
import com.amtrollin.xtremetasker.ui.text.UiText;
import java.awt.event.KeyEvent;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public final class CurrentTabKeyHandler
{
    private final XtremeTaskerOverlay a;

    private static final long MSG_COOLDOWN_MS = 900;
    private long lastMsgAtMs = 0;
    private String lastMsg = null;

    public boolean handleKeyPressed(KeyEvent e)
    {
        int code = e.getKeyCode();
        boolean handledOrBlocked = false;

        if (code == KeyEvent.VK_R)
        {
            var cur = a.plugin().getCurrentTask();
            boolean curDone = (cur != null) && a.plugin().isTaskCompleted(cur);
            boolean rollEnabled = (cur == null) || curDone;

            if (!rollEnabled)
            {
                notifyUser(UiText.get("input.roll_blocked"));
                return true;
            }

            handledOrBlocked = true;
        }

        if (code == KeyEvent.VK_C)
        {
            var cur = a.plugin().getCurrentTask();
            if (cur == null)
            {
                notifyUser("No current task to complete.");
                return true;
            }

            handledOrBlocked = true;
        }

        if (a.handleCurrentKey(e))
        {
            return true;
        }

        return handledOrBlocked;
    }

    private void notifyUser(String msg)
    {
        if (msg == null || msg.trim().isEmpty())
        {
            return;
        }

        long now = System.currentTimeMillis();

        if (msg.equals(lastMsg) && (now - lastMsgAtMs) < MSG_COOLDOWN_MS)
        {
            return;
        }

        lastMsgAtMs = now;
        lastMsg = msg;

        a.plugin().pushGameMessage(msg);
    }
}

