    private void drawTooltip(Graphics2D g, FontMetrics fm, String text, int anchorX, int anchorY, boolean alignLeft)
    {
        if (text == null || text.trim().isEmpty()) return;

        final int padX = 8;
        final int padY = 6;

        int maxTextW = Math.max(40, bounds.width - 24 - (padX * 2));
        List<String> lines = TextUtils.wrapText(text, fm, maxTextW);
        if (lines.isEmpty()) return;

        int tw = 0;
        for (String line : lines)
        {
            tw = Math.max(tw, fm.stringWidth(line));
        }
        int w = tw + padX * 2;
        int h = (fm.getHeight() * lines.size()) + padY * 2;

        int x = alignLeft ? anchorX - padX : anchorX - w / 2;
        int y = anchorY - h + 2;

        x = Math.max(bounds.x + 6,
                Math.min(x, bounds.x + bounds.width - w - 6));
        y = Math.max(bounds.y + 6, y);

        Rectangle r = new Rectangle(x, y, w, h);

        Shape oldClip = g.getClip();
        g.setClip(bounds);

        g.setColor(palette.UI_TEXT_DIM);
        int lineY = r.y + padY + fm.getAscent();
        for (String line : lines)
        {
            g.drawString(line, r.x + padX, lineY);
            lineY += fm.getHeight();
        }

        g.setClip(oldClip);
    }

    private static boolean isAchievementDiaryTask(XtremeTask task)
    {
        TaskVerification verification = task == null ? null : task.getVerification();
        return verification != null && verification.getType() == TaskVerification.VerificationType.ACHIEVEMENT_DIARY;
    }

    private static String achievementDiaryDescription(XtremeTask task)
    {
        TaskVerification verification = task == null ? null : task.getVerification();
        if (verification == null)
        {
            return ACHIEVEMENT_DIARY_NOTE;
        }

        String region = titleCase(verification.getRegion());
        String difficulty = titleCase(verification.getDifficulty());
        if (region == null && difficulty == null)
        {
            return ACHIEVEMENT_DIARY_NOTE;
        }

        String detail = region == null ? difficulty : difficulty == null ? region : region + " - " + difficulty;
        return "Achievement Diary: " + detail + ". " + ACHIEVEMENT_DIARY_NOTE;
    }

    private static String diaryTaskDescription(XtremeTask task)
    {
        String description = task == null ? null : task.getDescription();
        if (description != null && !description.trim().isEmpty())
        {
            return description.trim();
        }

        return achievementDiaryDescription(task);
    }

    private static String buildCompletionLine(CompletionInfo info)
    {
        if (info == null) return null;
        if (info.timestamp <= 0) return "Date unknown";
        return COMPLETION_DATE_TIME_FORMAT.format(Instant.ofEpochMilli(info.timestamp));
    }

    private static List<InstanceHistoryLine> buildInstanceHistoryLines(
            List<XtremeTask> instances,
            Function<XtremeTask, Boolean> isCompleted,
            Function<XtremeTask, CompletionInfo> completionInfoProvider,
            Function<XtremeTask, Long> taskTicksProvider,
            Function<XtremeTask, String> collectionLogSequenceLabelProvider
    )
    {
        if (instances == null || instances.isEmpty())
        {
            return List.of();
        }

        java.util.ArrayList<CompletedInstance> completedInstances = new java.util.ArrayList<>(instances.size());
        for (int i = 0; i < instances.size(); i++)
        {
            XtremeTask instance = instances.get(i);
            boolean done = isCompleted != null && Boolean.TRUE.equals(isCompleted.apply(instance));
            if (!done)
            {
                continue;
            }

            CompletionInfo info = completionInfoProvider == null ? null : completionInfoProvider.apply(instance);
            Long ticks = taskTicksProvider == null ? null : taskTicksProvider.apply(instance);

            completedInstances.add(new CompletedInstance(instance, info, ticks, i));
        }

        completedInstances.sort((a, b) -> {
            int byTimestamp = Long.compare(instanceSortTimestamp(a.info), instanceSortTimestamp(b.info));
            return byTimestamp != 0 ? byTimestamp : Integer.compare(a.originalIndex, b.originalIndex);
        });

        java.util.ArrayList<InstanceHistoryLine> lines = new java.util.ArrayList<>(completedInstances.size());
        for (int i = 0; i < completedInstances.size(); i++)
        {
            CompletedInstance completed = completedInstances.get(i);
            String prefix = instanceHistoryPrefix(completed.task, i, collectionLogSequenceLabelProvider);
            String dateText = instanceCompletionDateText(completed.info);
            String timeText = instanceTimeSpentText(completed.info, completed.ticks);

            lines.add(new InstanceHistoryLine(
                    completed.task,
                    prefix + dateText + " | " + timeText));
        }
        return lines;
    }

    private static String instanceHistoryPrefix(
            XtremeTask task,
            int index,
            Function<XtremeTask, String> collectionLogSequenceLabelProvider)
    {
        String sequenceLabel = collectionLogSequenceLabelProvider == null ? "" : safe(collectionLogSequenceLabelProvider.apply(task)).trim();
        if (!sequenceLabel.isEmpty())
        {
            return titleCaseSequenceLabel(sequenceLabel) + ": ";
        }
        return (index + 1) + ". ";
    }

    private static String titleCaseSequenceLabel(String label)
    {
        if (label == null || label.isEmpty())
        {
            return "";
        }
        return label.substring(0, 1).toUpperCase(java.util.Locale.ROOT)
                + label.substring(1).toLowerCase(java.util.Locale.ROOT);
    }

    private static long instanceSortTimestamp(CompletionInfo info)
    {
        return info != null && info.timestamp > 0 ? info.timestamp : Long.MAX_VALUE;
    }

    private static String buildTimeSpentLine(CompletionInfo info, Long ticks)
    {
        if (ticks != null && ticks < 0)
        {
            return UiText.get("current.time_spent_completed_before_roll");
        }

        if (ticks != null && ticks > 0)
        {
            return "Time spent: " + formatDuration(Math.round(ticks * 0.6));
        }

        if (info != null && info.source == CompletionInfo.Source.MANUAL)
        {
            return "Time spent: unknown (marked)";
        }
        if (info != null && info.source == CompletionInfo.Source.SYNCED)
        {
            return UiText.get("current.time_spent_synced");
        }
        return "Time spent: unknown";
    }

    private static final class InstanceHistoryLine
    {
        private final XtremeTask task;
        private final String text;

        private InstanceHistoryLine(XtremeTask task, String text)
        {
            this.task = task;
            this.text = text;
        }
    }

    private static final class CompletedInstance
    {
        private final XtremeTask task;
        private final CompletionInfo info;
        private final Long ticks;
        private final int originalIndex;

        private CompletedInstance(XtremeTask task, CompletionInfo info, Long ticks, int originalIndex)
        {
            this.task = task;
            this.info = info;
            this.ticks = ticks;
            this.originalIndex = originalIndex;
        }
    }

    private static String instanceCompletionDateText(CompletionInfo info)
    {
        if (info == null)
        {
            return "Date unknown";
        }

        if (info.timestamp <= 0)
        {
            return "Date unknown";
        }
        return COMPLETION_DATE_FORMAT.format(Instant.ofEpochMilli(info.timestamp));
    }

    private static String instanceTimeSpentText(CompletionInfo info, Long ticks)
    {
        if (ticks != null && ticks < 0)
        {
            return "N/A (Completed before rolled)";
        }

        if (ticks != null && ticks > 0)
        {
            return formatDuration(Math.round(ticks * 0.6));
        }

        if (info != null && info.source == CompletionInfo.Source.MANUAL)
        {
            return "unknown (marked)";
        }
        if (info != null && info.source == CompletionInfo.Source.SYNCED)
        {
            return "N/A (synced)";
        }
        return "unknown";
    }

    private static String formatDuration(long seconds)
    {
        if (seconds < 60)
        {
            return seconds + "s";
        }
        long minutes = seconds / 60;
        long remSeconds = seconds % 60;
        if (minutes < 60)
        {
            return remSeconds > 0
                    ? minutes + "m " + remSeconds + "s"
                    : minutes + "m";
        }
        long hours = minutes / 60;
        long remMinutes = minutes % 60;
        return remMinutes > 0
                ? hours + "h " + remMinutes + "m"
                : hours + "h";
    }
}

package com.amtrollin.xtremetasker.ui.tasks;

import com.amtrollin.xtremetasker.ui.tasks.models.CollectionLogRequirementItem;
import com.amtrollin.xtremetasker.ui.text.TextUtils;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.Function;
import org.slf4j.*;
import static com.amtrollin.xtremetasker.ui.style.UiPalette.withAlpha;

public final class CollectionLogIconGridRenderer
{
    private static final Logger log = LoggerFactory.getLogger(CollectionLogIconGridRenderer.class);
    private static final int ICONS_PER_ROW = 8;
    private static final int MAX_ICON_SIZE = 36;
    private static final int MIN_ICON_SIZE = 20;
    private static final int ICON_GAP = 3;
    private static final int ROW_GAP = 6;
    private static final long SLOW_RENDER_LOG_THRESHOLD_NANOS = 8_000_000L;
    private static final long SLOW_RENDER_LOG_INTERVAL_MS = 2_000L;
    private static long lastSlowRenderLogMs = 0L;

    private CollectionLogIconGridRenderer()
    {
    }

    public static int measureHeight(int itemCount, int maxWidth)
    {
        return measureHeight(itemCount, maxWidth, ICONS_PER_ROW);
    }

    public static int measureHeight(int itemCount, int maxWidth, int iconsPerRow)
    {
        if (itemCount <= 0)
        {
            return 0;
        }

        int columns = normalizeColumns(iconsPerRow);
        int rows = (itemCount + columns - 1) / columns;
        int iconSize = iconSize(maxWidth, columns);
        return rows * iconSize + Math.max(0, rows - 1) * ROW_GAP;
    }

    public static int render(
            Graphics2D g,
            FontMetrics fm,
            int x,
            int yBaseline,
            int maxWidth,
            List<CollectionLogRequirementItem> items,
            Function<Integer, BufferedImage> imageProvider,
            Point mousePoint,
            Rectangle tooltipBounds,
            Color textColor,
            Color dimTextColor,
            Color edgeLight,
            Color edgeDark
    )
    {
        return render(g, fm, x, yBaseline, maxWidth, items, imageProvider, mousePoint, tooltipBounds,
                textColor, dimTextColor, edgeLight, edgeDark, ICONS_PER_ROW);
    }

    public static int render(
            Graphics2D g,
            FontMetrics fm,
            int x,
            int yBaseline,
            int maxWidth,
            List<CollectionLogRequirementItem> items,
            Function<Integer, BufferedImage> imageProvider,
            Point mousePoint,
            Rectangle tooltipBounds,
            Color textColor,
            Color dimTextColor,
            Color edgeLight,
            Color edgeDark,
            int iconsPerRow
    )
    {
        if (items == null || items.isEmpty())
        {
            return yBaseline;
        }

        long renderStartNanos = items.size() >= 16 ? System.nanoTime() : 0L;
        int columns = normalizeColumns(iconsPerRow);
        int iconSize = iconSize(maxWidth, columns);
        int top = yBaseline - fm.getAscent();
        CollectionLogRequirementItem hoveredItem = null;
        Rectangle hoveredBounds = null;
        Rectangle clipBounds = g.getClipBounds();

        Object oldAA = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        for (int i = 0; i < items.size(); i++)
        {
            CollectionLogRequirementItem item = items.get(i);
            if (item == null)
            {
                continue;
            }

            int col = i % columns;
            int row = i / columns;
            int iconX = x + col * (iconSize + ICON_GAP);
            int iconY = top + row * (iconSize + ROW_GAP);
            Rectangle iconBounds = new Rectangle(iconX, iconY, iconSize, iconSize);
            boolean hovered = mousePoint != null && iconBounds.contains(mousePoint);

            if (clipBounds == null || iconBounds.intersects(clipBounds) || hovered)
            {
                drawItemImage(g, iconBounds, item, imageProvider, dimTextColor);

                if (item.isObtained())
                {
                    drawObtainedCheck(g, iconBounds);
                }
            }

            if (hovered)
            {
                hoveredItem = item;
                hoveredBounds = iconBounds;
            }
        }

        if (hoveredItem != null && hoveredBounds != null)
        {
            drawTooltip(g, fm, hoveredItem.getName(), hoveredBounds, tooltipBounds, textColor, edgeLight, edgeDark);
        }

        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAA != null ? oldAA : RenderingHints.VALUE_ANTIALIAS_DEFAULT);
        logSlowRender(renderStartNanos, items.size(), columns, maxWidth);
        return yBaseline + measureHeight(items.size(), maxWidth, columns);
    }

    private static int iconSize(int maxWidth)
    {
        return iconSize(maxWidth, ICONS_PER_ROW);
    }

    private static int iconSize(int maxWidth, int iconsPerRow)
    {
        int columns = normalizeColumns(iconsPerRow);
        int available = Math.max(MIN_ICON_SIZE * columns, maxWidth - (columns - 1) * ICON_GAP);
        int maxIconSize = columns < ICONS_PER_ROW ? 56 : MAX_ICON_SIZE;
        return Math.max(MIN_ICON_SIZE, Math.min(maxIconSize, available / columns));
    }

    private static int normalizeColumns(int iconsPerRow)
    {
        return Math.max(1, iconsPerRow);
    }

    private static void drawItemImage(
            Graphics2D g,
            Rectangle bounds,
            CollectionLogRequirementItem item,
            Function<Integer, BufferedImage> imageProvider,
            Color dimTextColor
    )
    {
        BufferedImage image = null;
        if (imageProvider != null && item.getItemId() > 0)
        {
            image = imageProvider.apply(item.getItemId());
        }

        if (image == null)
        {
            g.setColor(dimTextColor);
            String fallback = "?";
            FontMetrics fm = g.getFontMetrics();
            g.drawString(fallback,
                    bounds.x + (bounds.width - fm.stringWidth(fallback)) / 2,
                    bounds.y + ((bounds.height - fm.getHeight()) / 2) + fm.getAscent());
            return;
        }

        int drawSize = Math.max(1, Math.min(bounds.width, bounds.height));
        int drawX = bounds.x + (bounds.width - drawSize) / 2;
        int drawY = bounds.y + (bounds.height - drawSize) / 2;
        if (item.getStatus() == CollectionLogRequirementItem.Status.MISSING && item.isDimWhenMissing())
        {
            Composite oldComposite = g.getComposite();
            g.setComposite(AlphaComposite.SrcOver.derive(0.45f));
            g.drawImage(image, drawX, drawY, drawSize, drawSize, null);
            g.setComposite(oldComposite);
            return;
        }

        g.drawImage(image, drawX, drawY, drawSize, drawSize, null);
    }

    private static void logSlowRender(long renderStartNanos, int itemCount, int columns, int maxWidth)
    {
        if (renderStartNanos <= 0L)
        {
            return;
        }

        long elapsedNanos = System.nanoTime() - renderStartNanos;
        if (elapsedNanos < SLOW_RENDER_LOG_THRESHOLD_NANOS)
        {
            return;
        }

        long nowMs = System.currentTimeMillis();
        if (nowMs - lastSlowRenderLogMs < SLOW_RENDER_LOG_INTERVAL_MS)
        {
            return;
        }

        lastSlowRenderLogMs = nowMs;
        log.debug("Slow collection-log icon grid render: {} icons, {} columns, maxWidth={}, elapsed={}ms",
                itemCount, columns, maxWidth, elapsedNanos / 1_000_000L);
    }

    private static void drawObtainedCheck(Graphics2D g, Rectangle bounds)
    {
        int size = Math.max(12, bounds.width / 2);
        int x = bounds.x + (bounds.width - size) / 2;
        int y = bounds.y + (bounds.height - size) / 2 + Math.max(2, bounds.height / 10);
        int x1 = x + Math.max(3, size / 4);
        int y1 = y + size / 2;
        int x2 = x + size / 2 - 1;
        int y2 = y + size - Math.max(3, size / 4);
        int x3 = x + size - Math.max(3, size / 5);
        int y3 = y + Math.max(3, size / 4);

        Stroke oldStroke = g.getStroke();
        g.setStroke(new BasicStroke(Math.max(3f, bounds.width / 10f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(10, 20, 10, 230));
        g.drawLine(x1, y1, x2, y2);
        g.drawLine(x2, y2, x3, y3);

        g.setStroke(new BasicStroke(Math.max(1.7f, bounds.width / 15f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(92, 230, 112, 250));
        g.drawLine(x1, y1, x2, y2);
        g.drawLine(x2, y2, x3, y3);
        g.setStroke(oldStroke);
    }

    private static void drawTooltip(
            Graphics2D g,
            FontMetrics fm,
            String text,
            Rectangle anchor,
            Rectangle bounds,
            Color textColor,
            Color edgeLight,
            Color edgeDark
    )
    {
        if (text == null || text.trim().isEmpty())
        {
            return;
        }

        Rectangle clamp = bounds != null && bounds.width > 0 && bounds.height > 0
                ? bounds
                : g.getClipBounds();
        if (clamp == null)
        {
            return;
        }

        int padX = 7;
        int padY = 5;
        int maxTextW = Math.max(40, Math.min(180, clamp.width - 12 - padX * 2));
        List<String> lines = TextUtils.wrapText(text, fm, maxTextW);
        if (lines.isEmpty())
        {
            return;
        }

        int textW = 0;
        for (String line : lines)
        {
            textW = Math.max(textW, fm.stringWidth(line));
        }

        int w = textW + padX * 2;
        int h = fm.getHeight() * lines.size() + padY * 2;
        int x = anchor.x + anchor.width / 2 - w / 2;
        int y = anchor.y + anchor.height - 6;
        if (y + h > clamp.y + clamp.height - 4)
        {
            y = anchor.y - h + 3;
        }

        x = Math.max(clamp.x + 4, Math.min(x, clamp.x + clamp.width - w - 4));
        y = Math.max(clamp.y + 4, Math.min(y, clamp.y + clamp.height - h - 4));

        g.setColor(new Color(25, 18, 10, 245));
        g.fillRect(x, y, w, h);
        g.setColor(withAlpha(edgeLight, 100));
        g.drawRect(x, y, w - 1, h - 1);
        g.setColor(withAlpha(edgeDark, 180));
        g.drawLine(x + 1, y + h - 1, x + w - 1, y + h - 1);

        g.setColor(textColor);
        int lineY = y + padY + fm.getAscent();
        for (String line : lines)
        {
            g.drawString(line, x + padX, lineY);
            lineY += fm.getHeight();
        }
    }
}

package com.amtrollin.xtremetasker.ui.tasks;

import com.amtrollin.xtremetasker.ui.style.UiPalette;
import com.amtrollin.xtremetasker.ui.tasks.models.CollectionLogRequirementPreview;
import com.amtrollin.xtremetasker.ui.text.UiText;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.Function;
import static com.amtrollin.xtremetasker.ui.text.TaskLabelFormatter.tierLabel;
import static com.amtrollin.xtremetasker.ui.text.TextUtils.*;

public final class CollectionLogRequirementRenderer
{
    private static final String MEDALLION_ASSEMBLY_TITLE_PREFIX = "Need all ";
    private static final int SECONDARY_SECTION_GAP = 6;
    private static final int MEDALLION_ASSEMBLY_SECTION_GAP = 12;
    private static final int TIER_SECTION_ICON_GAP = 5;
    private static final int TIER_SECTION_LABEL_TOP_GAP = 4;
    private static final int OTHER_SEQUENCE_LABEL_TOP_GAP = 5;
    private static final String OTHER_SEQUENCE_CLOGS_LABEL = UiText.get("current.other_sequence_clogs");

    private final int rowHeight;
    private final int tierLabelMaxWidth;
    private final Color uiGold;
    private final Color uiText;
    private final Color uiTextDim;
    private final Color edgeLight;
    private final Color edgeDark;

    public CollectionLogRequirementRenderer(
            int rowHeight,
            int tierLabelMaxWidth,
            Color uiGold,
            Color uiText,
            Color uiTextDim,
            Color edgeLight,
            Color edgeDark)
    {
        this.rowHeight = rowHeight;
        this.tierLabelMaxWidth = tierLabelMaxWidth;
        this.uiGold = uiGold;
        this.uiText = uiText;
        this.uiTextDim = uiTextDim;
        this.edgeLight = edgeLight;
        this.edgeDark = edgeDark;
    }

    public int measure(CollectionLogRequirementPreview preview, FontMetrics fm, int maxWidth)
    {
        if (preview == null || !preview.hasItems())
        {
            return 0;
        }

        int total = rowHeight;
        if (preview.showSummaryText())
        {
            total += rowHeight * summaryTextLineCount(preview.summaryText());
        }
        if (preview.showTierSections())
        {
            total += measureTierSections(preview, fm, maxWidth);
        }
        else if (preview.showItemList())
        {
            total += CollectionLogIconGridRenderer.measureHeight(preview.getItems().size(), maxWidth, preview.iconColumns());
        }
        if (preview.showSecondaryItemList())
        {
            total += secondarySectionGap(preview) + rowHeight;
            total += CollectionLogIconGridRenderer.measureHeight(preview.secondaryItems().size(), maxWidth, preview.secondaryIconColumns());
        }
        return total;
    }

    public int render(
            Graphics2D g,
            FontMetrics fm,
            int x,
            int y,
            int maxWidth,
            CollectionLogRequirementPreview preview,
            Function<Integer, BufferedImage> imageProvider,
            Point mousePoint,
            Rectangle tooltipBounds)
    {
        g.setColor(uiGold);
        g.drawString(title(preview), x, y);
        y += rowHeight;

        if (preview.showSummaryText())
        {
            y = drawSummaryText(g, fm, preview.summaryText(), x, y, maxWidth);
            if (preview.showTierSections())
            {
                y += TIER_SECTION_ICON_GAP;
            }
        }

        if (preview.showTierSections())
        {
            y = drawTierSections(g, fm, preview, x, y, maxWidth, imageProvider, mousePoint, tooltipBounds);
        }
        else if (preview.showItemList())
        {
            y = CollectionLogIconGridRenderer.render(g, fm, x, y, maxWidth, preview.getItems(),
                    imageProvider, mousePoint, tooltipBounds, uiText, uiTextDim, edgeLight, edgeDark, preview.iconColumns());
        }

        if (preview.showSecondaryItemList())
        {
            y += secondarySectionGap(preview);
            g.setColor(uiGold);
            g.drawString(truncateToWidth(preview.secondaryTitleText(), fm, maxWidth), x, y);
            y += rowHeight;
            y = CollectionLogIconGridRenderer.render(g, fm, x, y, maxWidth, preview.secondaryItems(),
                    imageProvider, mousePoint, tooltipBounds, uiText, uiTextDim, edgeLight, edgeDark, preview.secondaryIconColumns());
        }

        return y;
    }

    private int measureTierSections(CollectionLogRequirementPreview preview, FontMetrics fm, int maxWidth)
    {
        int total = 0;
        CollectionLogRequirementPreview.TierSection current = preview.currentTierSection();
        if (current != null)
        {
            total += CollectionLogIconGridRenderer.measureHeight(current.items().size(), maxWidth, current.iconColumns());
        }

        List<CollectionLogRequirementPreview.TierSection> otherSections = preview.otherTierSectionsHardestFirst();
        if (!otherSections.isEmpty())
        {
            total += SECONDARY_SECTION_GAP + rowHeight + OTHER_SEQUENCE_LABEL_TOP_GAP;
            total += rowHeight * wrapText(OTHER_SEQUENCE_CLOGS_LABEL, fm, maxWidth).size();
        }
        for (int i = 0; i < otherSections.size(); i++)
        {
            CollectionLogRequirementPreview.TierSection section = otherSections.get(i);
            if (i > 0)
            {
                total += SECONDARY_SECTION_GAP;
            }
            total += TIER_SECTION_LABEL_TOP_GAP + rowHeight + TIER_SECTION_ICON_GAP;
            total += CollectionLogIconGridRenderer.measureHeight(section.items().size(), maxWidth, section.iconColumns());
        }
        return total;
    }

    private int drawTierSections(
            Graphics2D g,
            FontMetrics fm,
            CollectionLogRequirementPreview preview,
            int x,
            int y,
            int maxWidth,
            Function<Integer, BufferedImage> imageProvider,
            Point mousePoint,
            Rectangle tooltipBounds)
    {
        CollectionLogRequirementPreview.TierSection current = preview.currentTierSection();
        if (current != null)
        {
            y = CollectionLogIconGridRenderer.render(g, fm, x, y, maxWidth, current.items(),
                    imageProvider, mousePoint, tooltipBounds, uiText, uiTextDim, edgeLight, edgeDark, current.iconColumns());
        }

        List<CollectionLogRequirementPreview.TierSection> sections = preview.otherTierSectionsHardestFirst();
        if (!sections.isEmpty())
        {
            y += SECONDARY_SECTION_GAP + rowHeight + OTHER_SEQUENCE_LABEL_TOP_GAP;
            g.setColor(uiTextDim);
            for (String line : wrapText(OTHER_SEQUENCE_CLOGS_LABEL, fm, maxWidth))
            {
                g.drawString(truncateToWidth(line, fm, maxWidth), x, y);
                y += rowHeight;
            }
        }
        for (int i = 0; i < sections.size(); i++)
        {
            CollectionLogRequirementPreview.TierSection section = sections.get(i);
            if (i > 0)
            {
                y += SECONDARY_SECTION_GAP;
            }
            y += TIER_SECTION_LABEL_TOP_GAP;
            drawTierLabel(g, fm, section, x, y);
            y += rowHeight + TIER_SECTION_ICON_GAP;

            Composite oldComposite = g.getComposite();
            if (!section.currentTier())
            {
                g.setComposite(AlphaComposite.SrcOver.derive(0.45f));
            }
            y = CollectionLogIconGridRenderer.render(g, fm, x, y, maxWidth, section.items(),
                    imageProvider, mousePoint, tooltipBounds, uiText, uiTextDim, edgeLight, edgeDark, section.iconColumns());
            g.setComposite(oldComposite);
        }
        return y;
    }

    private void drawTierLabel(Graphics2D g, FontMetrics fm, CollectionLogRequirementPreview.TierSection section, int x, int baseline)
    {
        String text = section.tier() == null ? "TIER" : tierLabel(section.tier()).toUpperCase();
        g.setColor(uiTextDim);
        g.drawString(truncateToWidth(text, fm, Math.max(0, tierLabelMaxWidth)), x, baseline);
    }

    private int drawSummaryText(Graphics2D g, FontMetrics fm, String summaryText, int x, int y, int maxWidth)
    {
        for (String line : summaryTextLines(summaryText))
        {
            drawSummaryLine(g, fm, line, x, y, maxWidth);
            y += rowHeight;
        }
        return y;
    }

    private void drawSummaryLine(Graphics2D g, FontMetrics fm, String text, int x, int y, int maxWidth)
    {
        if (isPendingOpenClogSummaryLine(text))
        {
            g.setColor(UiPalette.TIER_COMPLETE_GLOW);
            g.drawString(truncateToWidth(text, fm, maxWidth), x, y);
            return;
        }

        String separator = " | ";
        int separatorIndex = text.indexOf(separator);
        if (separatorIndex < 0)
        {
            g.setColor(uiTextDim);
            g.drawString(truncateToWidth(text, fm, maxWidth), x, y);
            return;
        }

        String prefix = text.substring(0, separatorIndex + separator.length());
        String suffix = text.substring(separatorIndex + separator.length());
        int prefixWidth = fm.stringWidth(prefix);
        if (prefixWidth >= maxWidth)
        {
            g.setColor(uiTextDim);
            g.drawString(truncateToWidth(text, fm, maxWidth), x, y);
            return;
        }

        g.setColor(uiTextDim);
        g.drawString(prefix, x, y);
        drawSummarySuffix(g, fm, suffix, x + prefixWidth, y, maxWidth - prefixWidth);
    }

    private void drawSummarySuffix(Graphics2D g, FontMetrics fm, String suffix, int x, int y, int maxWidth)
    {
        String currentTaskPrefix = "current task: ";
        if (!suffix.startsWith(currentTaskPrefix))
        {
            g.setColor(uiTextDim);
            g.drawString(truncateToWidth(suffix, fm, maxWidth), x, y);
            return;
        }

        int prefixWidth = fm.stringWidth(currentTaskPrefix);
        if (prefixWidth >= maxWidth)
        {
            g.setColor(uiTextDim);
            g.drawString(truncateToWidth(suffix, fm, maxWidth), x, y);
            return;
        }

        String progress = suffix.substring(currentTaskPrefix.length());
        g.setColor(uiTextDim);
        g.drawString(currentTaskPrefix, x, y);
        g.setColor(isProgressComplete(progress) ? UiPalette.TIER_COMPLETE_GLOW : uiTextDim);
        g.drawString(truncateToWidth(progress, fm, maxWidth - prefixWidth), x + prefixWidth, y);
    }

    private static int secondarySectionGap(CollectionLogRequirementPreview preview)
    {
        String title = preview == null ? "" : safe(preview.secondaryTitleText()).trim();
        return title.startsWith(MEDALLION_ASSEMBLY_TITLE_PREFIX)
                && title.toLowerCase().contains("fragments to assemble")
                ? MEDALLION_ASSEMBLY_SECTION_GAP
                : SECONDARY_SECTION_GAP;
    }

    private static int summaryTextLineCount(String summaryText)
    {
        return summaryTextLines(summaryText).size();
    }

    private static List<String> summaryTextLines(String summaryText)
    {
        String text = safe(summaryText);
        return text.isEmpty() ? List.of() : List.of(text.split("\\R"));
    }

    private static boolean isPendingOpenClogSummaryLine(String text)
    {
        return text != null && text.matches(UiText.get("clog.pending_summary.regex"));
    }

    private static boolean isProgressComplete(String progress)
    {
        if (progress == null)
        {
            return false;
        }

        String[] parts = progress.trim().split("/");
        if (parts.length != 2)
        {
            return false;
        }

        try
        {
            int current = Integer.parseInt(parts[0].trim());
            int required = Integer.parseInt(parts[1].trim());
            return required > 0 && current >= required;
        }
        catch (NumberFormatException e)
        {
            return false;
        }
    }

    private static String title(CollectionLogRequirementPreview preview)
    {
        if (preview != null && preview.titleText() != null && !preview.titleText().trim().isEmpty())
        {
            return preview.titleText();
        }
        return preview != null && preview.showSummaryText() && !preview.showItemList()
                ? "Collection Log Progress"
                : "Eligible Collection Log items";
    }
}

