import static com.amtrollin.xtremetasker.ui.style.UiDraw.centeredTextBaseline;
import static com.amtrollin.xtremetasker.ui.style.UiPalette.withAlpha;

public final class TasksTabRenderer {
    private static final int TASKS_CONTROLS_COLUMN_W = 228;
    private static final long TASK_NAME_TOOLTIP_DELAY_MS = 1000L;
    private static final int TASK_NAME_TOOLTIP_CURSOR_OFFSET_X = 4;
    private static final int TASK_NAME_TOOLTIP_CURSOR_OFFSET_Y = 5;
    private static final int DATE_COL_W = 58;
    private static final int SPENT_COL_W = 48;
    private static final int HEADER_COL_GAP = 6;

    private final UiPalette palette;
    private String hoveredTruncatedTaskKey = null;
    private long hoveredTruncatedTaskSinceMs = 0L;

    public TasksTabRenderer(UiPalette palette) {
        this.palette = palette;
    }

    public void render(
            Graphics2D g,
            FontMetrics fm,
            int panelX,
            int cursorYBaseline,
            Rectangle panelBounds,
            TasksTabState state,
            TaskControlsRenderer controlsRenderer,
            TaskRowsRenderer rowsRenderer,
            TaskerService plugin,
            OverlayAnimations animations,
            List<TaskTier> tierTabs,
            TaskTier activeTier,
            Function<TaskTier, List<XtremeTask>> sortedTasksProvider,
            int hoverX,
            int hoverY
    ) {
        if (!plugin.hasTaskPackLoaded()) {
            g.setColor(palette.UI_TEXT_DIM);
            g.drawString("No tasks loaded.", panelX + PANEL_PADDING, cursorYBaseline);
            return;
        }

        final int panelW = panelBounds.width;
        final int innerW = Math.max(0, panelW - 2 * PANEL_PADDING);

        // -----------------------------
        // Tier tabs row
        // -----------------------------
        int tierTabH = ROW_HEIGHT + 6;
        int tierTabW = (innerW - (tierTabs.size() - 1) * 4) / tierTabs.size();

        int tierTabY = cursorYBaseline - fm.getAscent();
        int x = panelX + PANEL_PADDING;

        synchronized (state.tierTabBounds()) {
            state.tierTabBounds().clear();
        }
        for (TaskTier t : tierTabs) {
            Rectangle r = new Rectangle(x, tierTabY, tierTabW, tierTabH);
            synchronized (state.tierTabBounds()) {
                state.tierTabBounds().put(t, r);
            }

            int pctVal = plugin.getTierPercent(t);
            String pct = pctVal + "%";

            drawTierTabWithPercent(g, r, TaskLabelFormatter.tierLabel(t), pct, pctVal, t == activeTier);

            x += tierTabW + 4;
        }

        cursorYBaseline += tierTabH + 12;

            final int contentTopBaseline = cursorYBaseline;
            final int columnsGap = 8;
            final int controlsColumnW = Math.min(TASKS_CONTROLS_COLUMN_W, Math.max(224, innerW - columnsGap - 280));
            final int controlsColumnX = panelX;
            final int listColumnX = controlsColumnX + controlsColumnW + Math.max(2, columnsGap - 4);
            final int listColumnW = Math.max(220, panelBounds.x + panelBounds.width - PANEL_PADDING - listColumnX);

            controlsRenderer.render(
                g,
                fm,
                controlsColumnX,
                contentTopBaseline,
                state.controlsLayout(),
                state.taskQuery(),
                TaskLabelFormatter.tierLabel(activeTier),
                controlsColumnW,
                hoverX,
                hoverY,
                plugin.hasNewTasks()
            );

            int dividerTop = contentTopBaseline - fm.getAscent();
            int dividerBottom = panelBounds.y + panelBounds.height - PANEL_PADDING;
            if (dividerBottom > dividerTop + 10) {
                int controlsContentRight = state.controlsLayout().searchBox.width > 0
                        ? state.controlsLayout().searchBox.x + state.controlsLayout().searchBox.width
                        : controlsColumnX + controlsColumnW;
                int dividerX = controlsContentRight + Math.max(0, (listColumnX - controlsContentRight) / 2);
                g.setColor(withAlpha(palette.UI_GOLD, 45));
                g.drawLine(dividerX, dividerTop, dividerX, dividerBottom);
            }

            int listCursorBaseline = contentTopBaseline;

        // -----------------------------
        // Progress line
        // -----------------------------
        final int progressPadTop = 8;
        final int progressPadBottom = 8;

            listCursorBaseline += progressPadTop;

        Font oldFont = g.getFont();
        g.setFont(FontManager.getRunescapeSmallFont());
        FontMetrics pfm = g.getFontMetrics();

        int pctVal = plugin.getTierPercent(activeTier);
        String progressLabel = plugin.getTierProgressLabel(activeTier);
        String barLabel = TaskLabelFormatter.tierLabel(activeTier) + ": " + progressLabel;

        int barH = Math.max(20, pfm.getHeight() + 8);
        int barY = listCursorBaseline - pfm.getAscent();
        drawRsProgressBar(g, pfm, listColumnX, barY, listColumnW, barH, pctVal, barLabel);

        g.setFont(oldFont);
        fm = g.getFontMetrics();

        listCursorBaseline += barH + progressPadBottom + 6;

        g.setColor(withAlpha(palette.UI_TEXT_DIM, 170));

        drawTaskTableHeader(g, fm, state.controlsLayout(), state.taskQuery(), listColumnX, listCursorBaseline - 5, listColumnW);

        listCursorBaseline += fm.getHeight() - 1;

        // -----------------------------
        // Tasks list
        // -----------------------------
        List<XtremeTask> tasks = sortedTasksProvider.apply(activeTier);

        int listMaxBottom = panelBounds.y + panelBounds.height - PANEL_PADDING;

        Rectangle listPanelBounds = new Rectangle(
                listColumnX - PANEL_PADDING,
                panelBounds.y,
                listColumnW + (PANEL_PADDING * 2),
                Math.max(0, listMaxBottom + PANEL_PADDING - panelBounds.y)
        );

        if (tasks.isEmpty()) {
            int emptyTop = listCursorBaseline - fm.getAscent();
            int emptyH = Math.max(0, listMaxBottom - emptyTop);

            Rectangle emptyViewport = new Rectangle(listColumnX, emptyTop, listColumnW, emptyH);

            state.taskListViewportBounds().setBounds(emptyViewport);
            state.taskScrollbarRailBounds().setBounds(0, 0, 0, 0);
            state.taskScrollbarThumbBounds().setBounds(0, 0, 0, 0);
            synchronized (state.taskRowBounds()) {
                state.taskRowBounds().clear();
            }
            synchronized (state.taskCheckboxBounds()) {
                state.taskCheckboxBounds().clear();
            }

            g.setColor(palette.UI_TEXT_DIM);
            String msg = "No matches.";
            String filterMsg = emptyStateFilterMessage(state.taskQuery(), TaskLabelFormatter.tierLabel(activeTier));
            int textY = emptyViewport.y + Math.max(ROW_HEIGHT, emptyViewport.height / 3);
            g.drawString(TextUtils.truncateToWidth(msg, fm, emptyViewport.width), emptyViewport.x, textY);
            if (filterMsg != null) {
                g.drawString(TextUtils.truncateToWidth(filterMsg, fm, emptyViewport.width), emptyViewport.x, textY + fm.getHeight() + 2);
            }

            return;
        }

        int listTop = listCursorBaseline - fm.getAscent();
        final int LIST_TOP_INSET = 2;
        listTop += LIST_TOP_INSET;

        int viewportH = Math.max(0, listMaxBottom - listTop);
        int rowBlock = rowsRenderer.rowBlock();

        if (rowBlock > 0) {
            viewportH = (viewportH / rowBlock) * rowBlock;
        }

        int visible = state.tasksScroll().visibleRows(viewportH, rowBlock);
        int maxOffset = Math.max(0, tasks.size() - visible);
        if (state.tasksScroll().offsetRows > maxOffset) {
            state.tasksScroll().offsetRows = maxOffset;
        }

        int sel = state.selectionModel().getSelectedIndex();
        if (sel < 0) sel = 0;
        if (sel > tasks.size() - 1) {
            state.selectionModel().setSelectedIndex(tasks.size() - 1);
            sel = tasks.size() - 1;
        }

        boolean useCondensedRows = plugin.condenseRepeatedTasks();

        TaskRowsLayout layout = rowsRenderer.render(
                g,
                fm,
            listColumnX,
            listCursorBaseline,
                listPanelBounds,
                tasks,
                sel,
                state.tasksScroll().offsetRows,
                hoverX,
                hoverY,
                animations::completionProgress,
                plugin::isTaskCompleted,
                plugin::getCompletionInfo,
                plugin::getTaskTimeTicks,
                state.taskQuery(),
                useCondensedRows ? plugin::getTaskGroupProgress : null,
                useCondensedRows ? plugin::isTaskGroupNew : plugin::isNewTask
        );

        state.taskListViewportBounds().setBounds(layout.viewportBounds);
        state.taskScrollbarRailBounds().setBounds(layout.scrollbarRailBounds);
        state.taskScrollbarThumbBounds().setBounds(layout.scrollbarThumbBounds);

        Rectangle v = layout.viewportBounds;
        if (v.width > 0 && v.height > 0) {
            g.setColor(withAlpha(palette.UI_GOLD, 70));
            g.drawLine(v.x - 2, v.y - 2, v.x + v.width + 2, v.y - 2);
            g.drawLine(v.x + v.width + 2, v.y - 2, v.x + v.width + 2, v.y + v.height + 2);
            g.drawLine(v.x - 2, v.y + v.height + 2, v.x + v.width + 2, v.y + v.height + 2);

            g.setColor(withAlpha(palette.UI_EDGE_LIGHT, 55));
            g.drawLine(v.x - 1, v.y - 1, v.x + v.width + 2, v.y - 1);

            g.setColor(withAlpha(palette.UI_EDGE_DARK, 85));
            g.drawLine(v.x + v.width + 2, v.y - 1, v.x + v.width + 2, v.y + v.height + 2);
            g.drawLine(v.x - 1, v.y + v.height + 2, v.x + v.width + 2, v.y + v.height + 2);
        }

        synchronized (state.taskRowBounds()) {
            state.taskRowBounds().clear();
            state.taskRowBounds().putAll(layout.rowBounds);
        }

        synchronized (state.taskCheckboxBounds()) {
            state.taskCheckboxBounds().clear();
            state.taskCheckboxBounds().putAll(layout.checkboxBounds);
        }

        drawTaskNameHoverTooltip(g, fm, panelBounds, layout, hoverX, hoverY);

    }

    private void drawTierTabWithPercent(Graphics2D g, Rectangle bounds, String leftText, String rightText, int pctValue, boolean active) {
        Color bg = active ? new Color(78, 62, 38, 240) : new Color(32, 26, 17, 235);
        drawBevelBox(g, bounds, bg);

        if (active) {
            g.setColor(palette.UI_GOLD);
            g.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
        }

        FontMetrics fm = g.getFontMetrics();

        String pct = TextUtils.truncateToWidth(rightText, fm, 34);

        int pctW = fm.stringWidth(pct);
        int pctX = bounds.x + bounds.width - 4 - pctW;

        int leftMaxW = Math.max(0, (pctX - (bounds.x + 4) - 4));
        String tier = TextUtils.truncateToWidth(leftText, fm, leftMaxW);

        int ty = centeredTextBaseline(bounds, fm);

        g.setColor(active ? palette.UI_TEXT : palette.UI_TEXT_DIM);
        g.drawString(tier, bounds.x + 4, ty);

        boolean complete = pctValue >= 100;
        Color pctColor = complete
                ? new Color(120, 200, 140, active ? 230 : 190)
                : (active ? palette.UI_TEXT_DIM : withAlpha(palette.UI_TEXT_DIM, 180));
        g.setColor(pctColor);
        g.drawString(pct, pctX, ty);
    }

    private void drawBevelBox(Graphics2D g, Rectangle r, Color fill) {
        UiDraw.drawBevelBox(g, r, fill, palette.UI_EDGE_DARK, palette.UI_EDGE_LIGHT);
    }

    private void drawRsProgressBar(Graphics2D g, FontMetrics fm, int x, int y, int w, int h, int pctVal, String label) {
        int clamped = Math.min(100, Math.max(0, pctVal));
        int filled = (int) (w * clamped / 100.0);
        boolean complete = clamped >= 100;

        // Track background — very dark, sunken
        g.setColor(new Color(12, 9, 5, 230));
        g.fillRect(x, y, w, h);

        // Fill — two-tone vertical gradient effect
        if (filled > 0) {
            Color fillTop = complete
                    ? new Color(100, 185, 120, 235)
                    : new Color(190, 148, 50, 235);
            Color fillBot = complete
                    ? new Color(60, 130, 80, 235)
                    : new Color(130, 96, 28, 235);
            int half = h / 2;
            g.setColor(fillTop);
            g.fillRect(x, y, filled, half);
            g.setColor(fillBot);
            g.fillRect(x, y + half, filled, h - half);
        }

        // Bevel: highlight top-left, shadow bottom-right
        g.setColor(new Color(110, 90, 52, 190));
        g.drawLine(x, y, x + w - 1, y);           // top
        g.drawLine(x, y, x, y + h - 1);            // left
        g.setColor(new Color(5, 4, 2, 210));
        g.drawLine(x, y + h - 1, x + w - 1, y + h - 1); // bottom
        g.drawLine(x + w - 1, y, x + w - 1, y + h - 1); // right

        // Centered label with drop shadow
        String text = TextUtils.truncateToWidth(label, fm, w - 4);
        int textW = fm.stringWidth(text);
        int textX = x + (w - textW) / 2;
        int textY = y + ((h - fm.getHeight()) / 2) + fm.getAscent();

        g.setColor(new Color(0, 0, 0, 200));
        g.drawString(text, textX + 1, textY + 1);
        g.setColor(complete ? new Color(255, 215, 100, 255) : palette.UI_TEXT);
        g.drawString(text, textX, textY);
    }

    private void drawTaskTableHeader(
            Graphics2D g,
            FontMetrics fm,
            com.amtrollin.xtremetasker.ui.tasks.models.TaskControlsLayout layout,
            TaskListQuery query,
            int x,
            int baselineY,
            int width
    ) {
        FontMetrics badgeFm = g.getFontMetrics(FontManager.getRunescapeSmallFont());
        int badgeReserveW = badgeHeaderReserveWidth(badgeFm, query);

        g.setColor(withAlpha(palette.UI_TEXT_DIM, 170));
        int taskHeaderW = Math.max(0, width - badgeReserveW);
        g.drawString(TextUtils.truncateToWidth("Task", fm, taskHeaderW), x, baselineY);
        drawBadgeColumnHeaders(g, layout, query, baselineY, x, width);
    }

    private void drawBadgeColumnHeaders(Graphics2D g, com.amtrollin.xtremetasker.ui.tasks.models.TaskControlsLayout layout, TaskListQuery query,
                                        int baselineY, int x, int width) {
        Font oldFont = g.getFont();
        g.setFont(FontManager.getRunescapeSmallFont());
        FontMetrics sfm = g.getFontMetrics();
        int pillPadX = 6;
        int top = baselineY - sfm.getAscent() - 2;
        int h = sfm.getHeight() + 4;
        int nextRight = x + width - 13;

        layout.sortDateCompleted.setBounds(0, 0, 0, 0);
        layout.sortTimeSpent.setBounds(0, 0, 0, 0);

        int srcW = Math.max(
                Math.max(sfm.stringWidth("CA"), Math.max(sfm.stringWidth("CL"), sfm.stringWidth("AD"))) + pillPadX * 2,
                sfm.stringWidth("Src") + 4);
        int srcX = nextRight - srcW;
        drawSmallHeaderLabel(g, sfm, new Rectangle(srcX, top, srcW, h), "Src");
        nextRight = srcX - HEADER_COL_GAP;

        int tierW = Math.max(sfm.stringWidth("Master") + pillPadX * 2, sfm.stringWidth("Tier") + 4);
        int tierX = nextRight - tierW;
        drawSmallHeaderLabel(g, sfm, new Rectangle(tierX, top, tierW, h), "Tier");
        nextRight = tierX - HEADER_COL_GAP;

        if (query != null && query.showTimeSpentColumn)
        {
            int spentX = nextRight - SPENT_COL_W;
            layout.sortTimeSpent.setBounds(spentX, top, SPENT_COL_W, h);
            drawSmallHeaderLabel(g, sfm, layout.sortTimeSpent, sortHeaderLabel("Spent", query, TaskListQuery.SortColumn.SPENT));
            nextRight = spentX - HEADER_COL_GAP;
        }

        if (query != null && query.showDateCompletedColumn)
        {
            int dateX = nextRight - DATE_COL_W;
            layout.sortDateCompleted.setBounds(dateX, top, DATE_COL_W, h);
            drawSmallHeaderLabel(g, sfm, layout.sortDateCompleted, sortHeaderLabel("Date", query, TaskListQuery.SortColumn.DATE));
        }
        g.setFont(oldFont);
    }

    private static String sortHeaderLabel(String label, TaskListQuery query, TaskListQuery.SortColumn column)
    {
        if (query == null || query.sortColumn != column || query.sortDirection == TaskListQuery.SortDirection.OFF)
        {
            return label + " -";
        }
        return label + (query.sortDirection == TaskListQuery.SortDirection.DESC ? " v" : " ^");
    }

    private void drawSmallHeaderLabel(Graphics2D g, FontMetrics fm, Rectangle bounds, String text) {
        if (bounds == null || bounds.width <= 0)
        {
            return;
        }
        g.setColor(withAlpha(palette.UI_TEXT_DIM, 160));
        String draw = TextUtils.truncateToWidth(text, fm, bounds.width);
        g.drawString(draw, bounds.x + Math.max(0, (bounds.width - fm.stringWidth(draw)) / 2),
                bounds.y + ((bounds.height - fm.getHeight()) / 2) + fm.getAscent());
    }

    private static int badgeHeaderReserveWidth(FontMetrics fm, TaskListQuery query)
    {
        int sourceW = Math.max(
                Math.max(fm.stringWidth("CA"), Math.max(fm.stringWidth("CL"), fm.stringWidth("AD"))) + 12,
                fm.stringWidth("Src") + 4);
        int tierW = Math.max(fm.stringWidth("Master") + 12, fm.stringWidth("Tier") + 4);

        int width = 13;
        width = addColumnWidth(width, query != null && query.showDateCompletedColumn ? DATE_COL_W : 0);
        width = addColumnWidth(width, query != null && query.showTimeSpentColumn ? SPENT_COL_W : 0);
        width = addColumnWidth(width, tierW);
        width = addColumnWidth(width, sourceW);
        return width;
    }

    private static int addColumnWidth(int current, int width)
    {
        if (width <= 0)
        {
            return current;
        }
        return current == 0 ? width : current + HEADER_COL_GAP + width;
    }

    private void drawTaskNameHoverTooltip(
            Graphics2D g,
            FontMetrics fm,
            Rectangle panelBounds,
            TaskRowsLayout layout,
            int hoverX,
            int hoverY
    ) {
        if (hoverX < 0 || hoverY < 0 || layout.truncatedNameBounds.isEmpty()) {
            resetTaskNameTooltipHover();
            return;
        }

        XtremeTask hoveredTask = null;
        for (Map.Entry<XtremeTask, Rectangle> entry : layout.truncatedNameBounds.entrySet()) {
            Rectangle bounds = entry.getValue();
            if (bounds != null && bounds.contains(hoverX, hoverY)) {
                hoveredTask = entry.getKey();
                break;
            }
        }

        if (hoveredTask == null) {
            resetTaskNameTooltipHover();
            return;
        }

        String name = hoveredTask.getName();
        if (name == null || name.trim().isEmpty()) {
            resetTaskNameTooltipHover();
            return;
        }

        String taskKey = taskHoverKey(hoveredTask);
        long now = System.currentTimeMillis();
        if (!taskKey.equals(hoveredTruncatedTaskKey)) {
            hoveredTruncatedTaskKey = taskKey;
            hoveredTruncatedTaskSinceMs = now;
            return;
        }

        if (now - hoveredTruncatedTaskSinceMs < TASK_NAME_TOOLTIP_DELAY_MS) {
            return;
        }

        final int pad = 7;
        final int maxW = Math.max(120, panelBounds.width - PANEL_PADDING * 2 - 12);
        List<String> lines = TextUtils.wrapText(name, fm, maxW - pad * 2);
        if (lines.isEmpty()) {
            return;
        }

        int contentW = 0;
        for (String line : lines) {
            contentW = Math.max(contentW, fm.stringWidth(line));
        }

        int tooltipW = Math.min(maxW, contentW + pad * 2);
        int tooltipH = pad * 2 + lines.size() * fm.getHeight();
        int tooltipX = hoverX + TASK_NAME_TOOLTIP_CURSOR_OFFSET_X;
        int rightLimit = panelBounds.x + panelBounds.width - PANEL_PADDING;
        if (tooltipX + tooltipW > rightLimit) {
            tooltipX = hoverX - tooltipW - TASK_NAME_TOOLTIP_CURSOR_OFFSET_X;
        }
        tooltipX = Math.max(panelBounds.x + PANEL_PADDING, tooltipX);

        int tooltipY = hoverY + TASK_NAME_TOOLTIP_CURSOR_OFFSET_Y;
        int bottomLimit = panelBounds.y + panelBounds.height - PANEL_PADDING;
        if (tooltipY + tooltipH > bottomLimit) {
            tooltipY = hoverY - tooltipH - TASK_NAME_TOOLTIP_CURSOR_OFFSET_Y;
        }
        tooltipY = Math.max(panelBounds.y + PANEL_PADDING, tooltipY);

        Rectangle tooltipBounds = new Rectangle(tooltipX, tooltipY, tooltipW, tooltipH);
        drawBevelBox(g, tooltipBounds, new Color(45, 36, 24, 248));

        int textY = tooltipY + pad + fm.getAscent();
        g.setColor(palette.UI_TEXT);
        for (String line : lines) {
            g.drawString(line, tooltipX + pad, textY);
            textY += fm.getHeight();
        }
    }

    private void resetTaskNameTooltipHover()
    {
        hoveredTruncatedTaskKey = null;
        hoveredTruncatedTaskSinceMs = 0L;
    }

    private static String taskHoverKey(XtremeTask task)
    {
        String id = task.getId();
        if (id != null && !id.isEmpty())
        {
            return id;
        }

        String name = task.getName();
        return name == null ? "" : name;
    }

    private static String emptyStateFilterMessage(TaskListQuery q, String activeTierLabel) {
        if (q == null) {
            return null;
        }

        List<String> filters = new ArrayList<>();

        if (q.showNewTasksFilter) {
            filters.add("New tasks");
        }

        if (!q.isSourceAllSelected() && q.sourceCASelected) {
            filters.add("CAs");
        }
        if (!q.isSourceAllSelected() && q.sourceClogsSelected) {
            filters.add("CLOGs");
        }
        if (!q.isSourceAllSelected() && q.sourceDasSelected) {
            filters.add("ADs");
        }

        if (q.statusFilter == TaskListQuery.StatusFilter.COMPLETE) {
            filters.add("Complete");
        } else if (q.statusFilter == TaskListQuery.StatusFilter.INCOMPLETE) {
            filters.add("Incomplete");
        }

        if (q.tierScope == TaskListQuery.TierScope.THIS_TIER && activeTierLabel != null && !activeTierLabel.isEmpty()) {
            filters.add(activeTierLabel + " tier");
        }

        if (filters.isEmpty()) {
            return null;
        }

        return "Applied filter(s): " + String.join(" + ", filters);
    }

}

package com.amtrollin.xtremetasker.ui.tasks;

import com.amtrollin.xtremetasker.tasklist.models.TaskListQuery;
import com.amtrollin.xtremetasker.ui.style.UiDraw;
import com.amtrollin.xtremetasker.ui.tasks.models.TaskControlsLayout;
import com.amtrollin.xtremetasker.ui.text.UiText;
import java.awt.*;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;
import static com.amtrollin.xtremetasker.ui.style.UiDraw.centeredTextBaseline;
import static com.amtrollin.xtremetasker.ui.style.UiPalette.withAlpha;
import static com.amtrollin.xtremetasker.ui.text.TextUtils.truncateToWidth;

/**
 * Goals this version satisfies:
 * - Search + Filters header span full available width.
 * - Filter "chips" fit to text.
 * - Consistent label column width across Source/Status/Tier/Sort (labels NOT stretched).
 * - Visible blank space between chips and between label and first chip (no beveled "mini boxes" in gaps).
 * - No trailing row background behind the chips; row visuals are just a label cell + individual chips.
 * - Tier scope pill dims bracketed tier text.
 */
public class TaskControlsRenderer
{
    private static final BufferedImage QUESTION_ICON = UiDraw.loadImage("/icons/notifications/OSRS_question.png");
    private static final Color NEW_TASKS_BORDER = new Color(0x00, 0x80, 0x80);

    private final int panelPadding;
    private final int rowHeight;

    private final Color uiEdgeLight;
    private final Color uiEdgeDark;
    private final Color uiGold;
    private final Color uiText;
    private final Color uiTextDim;

    private final Color inputBg;
    private final Color inputFocusOutline;
    private final Color pillOnBg;
    private final Color pillOffBg;

    public TaskControlsRenderer(
            int panelPadding,
            int rowHeight,
            Color uiEdgeLight,
            Color uiEdgeDark,
            Color uiGold,
            Color uiText,
            Color uiTextDim,
            Color inputBg,
            Color inputFocusOutline,
            Color pillOnBg,
            Color pillOffBg
    )
    {
        this.panelPadding = panelPadding;
        this.rowHeight = rowHeight;

        this.uiEdgeLight = uiEdgeLight;
        this.uiEdgeDark = uiEdgeDark;
        this.uiGold = uiGold;
        this.uiText = uiText;
        this.uiTextDim = uiTextDim;

        this.inputBg = inputBg;
        this.inputFocusOutline = inputFocusOutline;
        this.pillOnBg = pillOnBg;
        this.pillOffBg = pillOffBg;
    }

    /**
     * Draws the control block and mutates layout bounds.
     * Returns the new cursorY after controls are rendered.
     */
    public int render(
            Graphics2D g,
            FontMetrics fm,
            int panelX,
            int cursorY,
            TaskControlsLayout layout,
            TaskListQuery query,
            String activeTierLabel,
            int panelW,
            int mouseX,
            int mouseY,
            boolean hasNewTasks
    )
    {
        // Shared geometry
        int rowX = panelX + panelPadding;
        int rowW = panelW - 2 * panelPadding;

        final String SOURCE_LABEL = "Source:";
        final String STATUS_LABEL = "Status:";
        final String TIER_LABEL = "Tier:";
        final int leftPad = 8;
        final int rightPad = 8;

        final int chipGap = 6;           // blank space between chips
        final int labelToChipOverlap = 3;
        final int pillPadX = 10;          // inside-pill horizontal padding

        // ================================
        // Row 1: Search (full width)
        // ================================
        cursorY += 5; // small gap above search
        int searchRowTop = cursorY - fm.getAscent();
        int searchRowH = rowHeight + 10;

        layout.searchBox.setBounds(rowX, searchRowTop, rowW, searchRowH);

        drawBevelBox(g, layout.searchBox, inputBg, uiEdgeLight, uiEdgeDark);
        // Gold border when focused or has text; dim grey otherwise
        boolean searchActive = query.searchFocused || (query.searchText != null && !query.searchText.isEmpty());
        g.setColor(searchActive ? inputFocusOutline : withAlpha(uiTextDim, 100));
        g.drawRect(layout.searchBox.x, layout.searchBox.y, layout.searchBox.width, layout.searchBox.height);

        // Magnifying glass icon
        int mgX = layout.searchBox.x + 5;
        int mgY = layout.searchBox.y + (layout.searchBox.height - 9) / 2;
        g.setColor(searchActive ? withAlpha(uiGold, 210) : withAlpha(uiTextDim, 150));
        g.drawOval(mgX, mgY, 7, 7);
        g.drawLine(mgX + 6, mgY + 6, mgX + 9, mgY + 9);

        String placeholder = "Search tasks...";
        boolean empty = (query.searchText == null || query.searchText.isEmpty());
        String shown = (!query.searchFocused && empty) ? placeholder : (empty ? "" : query.searchText);

        g.setColor((!query.searchFocused && empty) ? uiTextDim : uiText);

        int textX = layout.searchBox.x + 18;  // offset for icon
        int baseY = centeredTextBaseline(layout.searchBox, fm);

        // Compute and store per-character pixel positions for mouse selection
        String rawText = (query.searchText != null) ? query.searchText : "";
        int[] charPositions = new int[rawText.length() + 1];
        for (int i = 0; i <= rawText.length(); i++) {
            charPositions[i] = fm.stringWidth(rawText.substring(0, i));
        }
        layout.searchTextX = textX;
        layout.searchCharXPositions = charPositions;

        // Draw selection highlight
        int selStart = query.searchSelStart;
        int selEnd = query.searchSelEnd;
        if (query.searchFocused && selStart >= 0 && selEnd > selStart
                && selStart <= rawText.length() && selEnd <= rawText.length()) {
            int sx = textX + charPositions[selStart];
            int ex = textX + charPositions[selEnd];
            int selTop = layout.searchBox.y + 3;
            int selH = layout.searchBox.height - 6;
            g.setColor(withAlpha(uiGold, 90));
            g.fillRect(sx, selTop, Math.max(1, ex - sx), selH);
        }

        boolean caretOn = query.searchFocused && isCaretVisible();
        String caretText = caretOn ? (shown + "|") : shown;
        g.drawString(truncateToWidth(caretText, fm, layout.searchBox.width - 16), textX, baseY);

        // extra padding below search (you wanted this)
        cursorY += searchRowH + 14;

        // ================================
        // Row 2: "See New Tasks" button (session-only, shown only when new tasks exist)
        // ================================
        if (hasNewTasks) {
            int newRowTop = cursorY - fm.getAscent();
            int newRowH = rowHeight + 6;
            int helpSize = Math.min(16, newRowH - 4);
            int helpGap = 6;
            int newBtnW = Math.min(rowW - helpGap - helpSize, Math.max(150, rowW / 2));
            int groupX = rowX + (rowW - newBtnW) / 2;

            layout.filterNewTasks.setBounds(groupX, newRowTop, newBtnW, newRowH);

            boolean active = query.showNewTasksFilter;
            drawBevelBox(g, layout.filterNewTasks, active ? pillOnBg : pillOffBg, uiEdgeLight, uiEdgeDark);
            g.setColor(NEW_TASKS_BORDER);
            g.drawRect(layout.filterNewTasks.x, layout.filterNewTasks.y, layout.filterNewTasks.width, layout.filterNewTasks.height);

            String btnLabel = active ? "Showing New Tasks" : "See New Tasks";
            g.setColor(active ? uiText : uiGold);
            int bw = fm.stringWidth(btnLabel);
            g.drawString(truncateToWidth(btnLabel, fm, newBtnW - leftPad * 2),
                    layout.filterNewTasks.x + (layout.filterNewTasks.width - Math.min(bw, newBtnW - leftPad * 2)) / 2,
                    centeredTextBaseline(layout.filterNewTasks, fm));

            int helpX = layout.filterNewTasks.x + layout.filterNewTasks.width + helpGap;
            int helpY = newRowTop + (newRowH - helpSize) / 2;
            layout.filterNewTasksHelp.setBounds(helpX, helpY, helpSize, helpSize);
            drawHelpIcon(g, fm, layout.filterNewTasksHelp);
            if (layout.filterNewTasksHelp.contains(mouseX, mouseY))
            {
                drawTooltipAboveRightAligned(g, fm, UiText.get("tasks.new_tasks_help"), layout.filterNewTasks, panelX + panelW + 5);
            }

            // Keep the controls below close to the optional row. Reserving another
            // full font height here pushed the column-display controls off-panel.
            cursorY += newRowH + 6;
        } else {
            layout.filterNewTasks.setBounds(0, 0, 0, 0);
            layout.filterNewTasksHelp.setBounds(0, 0, 0, 0);
        }

        // ================================
        // Row 3: Filters header + applied state
        // ================================
        cursorY += 6;
        FontMetrics bodyFm = fm;
        java.awt.Font savedHeaderFont = g.getFont();
        java.awt.Font sectionHeaderFont = net.runelite.client.ui.FontManager.getRunescapeBoldFont().deriveFont(java.awt.Font.BOLD, 16f);
        g.setFont(sectionHeaderFont);
        FontMetrics headerFm = g.getFontMetrics();
        g.setColor(uiGold);
        g.drawString("Filters", rowX + leftPad, cursorY);
        drawHeaderClearLink(g, headerFm, bodyFm, layout.clearFilters, rowX, rowW, leftPad, cursorY, "Filters", mouseX, mouseY);
        g.setFont(savedHeaderFont);
        fm = bodyFm;

        cursorY += headerFm.getHeight() - 5;

        // ================================
        // Rows 3-5: Filter chips
        // ================================
        int rowH = rowHeight + 6;
        int rowTop = 0;
        rowTop = cursorY - fm.getAscent();

        drawLabelCell(g, fm, rowX, rowTop, rowW, rowH, SOURCE_LABEL, leftPad);
        cursorY += rowH - labelToChipOverlap;
        rowTop = cursorY - fm.getAscent();

        final String SRC_ALL = "All";
        final String SRC_CA = "CAs";
        final String SRC_CL = "CLOGs";
        final String SRC_DA = "ADs";

        int availableSource = rowW - leftPad - rightPad;

        boolean sourceAll = query.isSourceAllSelected();
        drawRightAlignedPillRow(g, fm, rowX, rowW, rowTop, rowH, rightPad, chipGap, pillPadX,
                availableSource,
                new Rectangle[] {layout.filterSourceAll, layout.filterCA, layout.filterCL, layout.filterDA},
                new String[] {SRC_ALL, SRC_CA, SRC_CL, SRC_DA},
                new int[] {42, 42, 52, 42},
                new boolean[] {sourceAll, !sourceAll && query.sourceCASelected,
                        !sourceAll && query.sourceClogsSelected, !sourceAll && query.sourceDasSelected});

        cursorY += rowH + 3;

        // ================================
        // Row 4: Status chips
        // ================================
        rowTop = cursorY - fm.getAscent();
        drawLabelCell(g, fm, rowX, rowTop, rowW, rowH, STATUS_LABEL, leftPad);
        cursorY += rowH - labelToChipOverlap;
        rowTop = cursorY - fm.getAscent();

        final String ST_ALL = "All";
        final String ST_INC = "Incomplete";
        final String ST_COMP = "Complete";

        int availableStatus = rowW - leftPad - rightPad;

        drawRightAlignedPillRow(g, fm, rowX, rowW, rowTop, rowH, rightPad, chipGap, pillPadX,
                availableStatus,
                new Rectangle[] {layout.filterStatusAll, layout.filterIncomplete, layout.filterComplete},
                new String[] {ST_ALL, ST_INC, ST_COMP},
                new int[] {42, 70, 70},
                new boolean[] {query.statusFilter == TaskListQuery.StatusFilter.ALL,
                        query.statusFilter == TaskListQuery.StatusFilter.INCOMPLETE,
                        query.statusFilter == TaskListQuery.StatusFilter.COMPLETE});

        cursorY += rowH + 3;

        // ================================
        // Row 5: Tier scope chips
        // ================================
        rowTop = cursorY - fm.getAscent();
        drawLabelCell(g, fm, rowX, rowTop, rowW, rowH, TIER_LABEL, leftPad);
        cursorY += rowH - labelToChipOverlap;
        rowTop = cursorY - fm.getAscent();

        final String T_THIS = "This Tier [" + activeTierLabel + "]";
        final String T_ALL = "All Tiers";

        int availableTier = rowW - leftPad - rightPad;

        int wAllT = pillWidth(fm, T_ALL, pillPadX, 70, availableTier);
        int wThis = Math.max(70, availableTier - chipGap - wAllT);

        int tx = rowX + leftPad;
        layout.filterTierThis.setBounds(tx, rowTop, wThis, rowH);
        tx += wThis + chipGap;

        layout.filterTierAll.setBounds(tx, rowTop, wAllT, rowH);

        drawTierScopePill(g, fm, layout.filterTierThis, T_THIS, query.tierScope == TaskListQuery.TierScope.THIS_TIER);
        drawPill(g, fm, layout.filterTierAll, T_ALL, query.tierScope == TaskListQuery.TierScope.ALL_TIERS);

        cursorY += rowH + 28;

        g.setFont(sectionHeaderFont);
        headerFm = g.getFontMetrics();
        g.setColor(uiGold);
        g.drawString("Column displays", rowX + leftPad, cursorY);
        drawHeaderRule(g, rowX + leftPad + headerFm.stringWidth("Column displays") + 10,
                cursorY - headerFm.getAscent() + headerFm.getHeight() / 2,
                rowX + rowW - rightPad);
        g.setFont(savedHeaderFont);
        fm = bodyFm;
        cursorY += headerFm.getHeight() + 4;

        rowTop = cursorY - fm.getAscent();
        int displayAvailableW = rowW - leftPad - rightPad;
        drawTwoColumnPillGrid(
                g,
                fm,
                rowX + leftPad,
                rowTop,
                rowH,
                displayAvailableW,
                chipGap,
                new Rectangle[] {
                        layout.displayDateCompleted,
                        layout.displayTimeSpent
                },
                new String[] {
                        "Date completed",
                        "Time spent"
                },
                new boolean[] {
                        query.showDateCompletedColumn,
                        query.showTimeSpentColumn
                });

        cursorY += rowH + 20;

        return cursorY;

    }

    // ================================
    // Helpers
    // ================================
    private void drawLabelCell(Graphics2D g, FontMetrics fm, int rowX, int rowTop, int labelColW, int rowH, String label, int leftPad)
    {
        // Plain label — no box, no bevel, just subdued text
        int baseline = rowTop + ((rowH - fm.getHeight()) / 2) + fm.getAscent();
        g.setColor(withAlpha(uiTextDim, 170));
        g.drawString(label, rowX + leftPad, baseline);
    }

    private void drawPill(Graphics2D g, FontMetrics fm, Rectangle bounds, String text, boolean on)
    {
        Color bg = on ? pillOnBg : pillOffBg;

        drawBevelBox(g, bounds, bg, uiEdgeLight, uiEdgeDark);

        int outlineAlpha = on ? 200 : 60;
        g.setColor(withAlpha(uiGold, outlineAlpha));
        g.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);

        g.setColor(on ? uiText : uiTextDim);

        String drawText = truncateToWidth(text, fm, bounds.width - 10);
        int tw = fm.stringWidth(drawText);
        int tx = bounds.x + (bounds.width - tw) / 2;
        int ty = centeredTextBaseline(bounds, fm);

        g.drawString(drawText, tx, ty);
    }


    private void drawBevelBox(Graphics2D g, Rectangle r, Color fill, Color light, Color dark)
    {
        UiDraw.drawBevelBox(g, r, fill, dark, light);
    }

    // Blink timing: 500ms on, 500ms off
    private static final long CARET_BLINK_MS = 500L;

    private boolean isCaretVisible()
    {
        return (System.currentTimeMillis() / CARET_BLINK_MS) % 2 == 0;
    }

    private int pillWidth(FontMetrics fm, String text, int pillPadX, int minW, int maxW)
    {
        int w = fm.stringWidth(text) + (pillPadX * 2);
        w = Math.max(minW, w);
        w = Math.min(maxW, w);
        return w;
    }

    private int rightAlignedX(int rowX, int rowW, int rightPad, int chipGap, int... widths)
    {
        int total = 0;
        for (int i = 0; i < widths.length; i++)
        {
            total += widths[i];
            if (i > 0)
            {
                total += chipGap;
            }
        }
        return Math.max(rowX, rowX + rowW - rightPad - total);
    }

    private void drawRightAlignedPillRow(
            Graphics2D g,
            FontMetrics fm,
            int rowX,
            int rowW,
            int rowTop,
            int rowH,
            int rightPad,
            int chipGap,
            int pillPadX,
            int availableW,
            Rectangle[] bounds,
            String[] labels,
            int[] minWidths,
            boolean[] selected)
    {
        int[] widths = new int[labels.length];
        for (int i = 0; i < labels.length; i++)
        {
            widths[i] = pillWidth(fm, labels[i], pillPadX, minWidths[i], availableW);
        }

        int x = rightAlignedX(rowX, rowW, rightPad, chipGap, widths);
        for (int i = 0; i < labels.length; i++)
        {
            bounds[i].setBounds(x, rowTop, widths[i], rowH);
            drawPill(g, fm, bounds[i], labels[i], selected[i]);
            x += widths[i] + chipGap;
        }
    }

    private void drawTwoColumnPillGrid(
            Graphics2D g,
            FontMetrics fm,
            int x,
            int rowTop,
            int rowH,
            int availableW,
            int chipGap,
            Rectangle[] bounds,
            String[] labels,
            boolean[] selected)
    {
        int w = Math.max(48, (availableW - chipGap) / 2);
        for (int i = 0; i < labels.length; i++)
        {
            int col = i % 2;
            int row = i / 2;
            bounds[i].setBounds(x + col * (w + chipGap), rowTop + row * (rowH + chipGap), w, rowH);
            drawPill(g, fm, bounds[i], labels[i], selected[i]);
        }
    }

    private void drawTierScopePill(Graphics2D g, FontMetrics fm, Rectangle bounds, String fullText, boolean on)
    {
        int bracketIdx = fullText.indexOf('[');
        if (bracketIdx < 0)
        {
            drawPill(g, fm, bounds, fullText, on);
            return;
        }

        String main = fullText.substring(0, bracketIdx);
        String meta = fullText.substring(bracketIdx);

        Color bg = on ? pillOnBg : pillOffBg;
        drawBevelBox(g, bounds, bg, uiEdgeLight, uiEdgeDark);

        g.setColor(on ? withAlpha(uiGold, 200) : withAlpha(uiGold, 60));
        g.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);

        int mainW = fm.stringWidth(main);
        int metaW = fm.stringWidth(meta);
        int totalW = mainW + metaW;
        int maxTextW = Math.max(0, bounds.width - 8);
        if (totalW > maxTextW)
        {
            String drawText = truncateToWidth(fullText, fm, maxTextW);
            g.setColor(on ? uiText : uiTextDim);
            g.drawString(drawText, bounds.x + Math.max(0, (bounds.width - fm.stringWidth(drawText)) / 2),
                    centeredTextBaseline(bounds, fm));
            return;
        }

        int tx = bounds.x + (bounds.width - totalW) / 2;
        int ty = centeredTextBaseline(bounds, fm);

        g.setColor(on ? uiText : uiTextDim);
        g.drawString(main, tx, ty);

        Color metaColor = on ? withAlpha(uiText, 150) : withAlpha(uiTextDim, 160);
        g.setColor(metaColor);
        g.drawString(meta, tx + mainW, ty);
    }

    private void drawTooltipAboveRightAligned(Graphics2D g, FontMetrics fm, String text, Rectangle anchor, int textRightX)
    {
        int padX = 8;
        int padY = 3;

        int tw = fm.stringWidth(text);
        int th = fm.getHeight();
        int w = tw + padX * 2;
        int h = th + padY * 2;
        int x = textRightX - padX - tw - 10;
        int y = anchor.y - h + 3;

        Rectangle r = new Rectangle(x, y, w, h);

        g.setColor(uiTextDim);
        int baseline = centeredTextBaseline(r, fm);
        g.drawString(text, r.x + padX, baseline);
    }

    private void drawHeaderRule(Graphics2D g, int x1, int y, int x2)
    {
        if (x2 <= x1)
        {
            return;
        }

        g.setColor(withAlpha(uiGold, 55));
        g.drawLine(x1, y, x2, y);
    }

    private void drawHeaderClearLink(
            Graphics2D g,
            FontMetrics headerFm,
            FontMetrics clearFm,
            Rectangle clearBounds,
            int rowX,
            int rowW,
            int leftPad,
            int baselineY,
            String title,
            int mouseX,
            int mouseY
    )
    {
        final String clearLabel = "[clear]";
        int clearW = clearFm.stringWidth(clearLabel) + 10;
        int clearX = rowX + rowW - clearW;
        int clearBaselineY = baselineY - headerFm.getAscent() + ((headerFm.getHeight() - clearFm.getHeight()) / 2) + clearFm.getAscent();
        int clearTop = clearBaselineY - clearFm.getAscent() - 1;
        clearBounds.setBounds(clearX, clearTop, clearW, clearFm.getHeight() + 2);

        int ruleX1 = rowX + leftPad + headerFm.stringWidth(title) + 10;
        int ruleX2 = clearX - 8;
        drawHeaderRule(g, ruleX1, baselineY - headerFm.getAscent() + headerFm.getHeight() / 2, ruleX2);

        boolean hovered = clearBounds.contains(mouseX, mouseY);
        g.setColor(withAlpha(uiTextDim, hovered ? 230 : 180));
        if (rowW > clearW)
        {
            Font savedFont = g.getFont();
            g.setFont(FontManager.getRunescapeFont());
            g.drawString(clearLabel, clearX + 5, clearBaselineY);
            g.setFont(savedFont);
        }
    }

    private void drawHelpIcon(Graphics2D g, FontMetrics fm, Rectangle bounds)
    {
        if (QUESTION_ICON != null)
        {
            g.drawImage(QUESTION_ICON, bounds.x, bounds.y, bounds.width, bounds.height, null);
            return;
        }

        g.setColor(withAlpha(uiTextDim, 180));
        g.drawOval(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
        String mark = "?";
        int tx = bounds.x + (bounds.width - fm.stringWidth(mark)) / 2;
        int ty = centeredTextBaseline(bounds, fm);
        g.drawString(mark, tx, ty);
    }

    private static void clearBounds(Rectangle... bounds)
    {
        for (Rectangle bound : bounds)
        {
            bound.setBounds(0, 0, 0, 0);
        }
    }

}

