package com.amtrollin.xtremetasker.ui.tasklist;

public final class TaskListScrollController
{
    private final int scrollRowsPerNotch;

    public int offsetRows = 0;
    public double wheelRemainderRows = 0.0;
    private int suppressEnsureTicks = 0;


    public TaskListScrollController(int scrollRowsPerNotch)
    {
        this.scrollRowsPerNotch = Math.max(1, scrollRowsPerNotch);
    }

    public int visibleRows(int viewportH, int rowBlock)
    {
        if (rowBlock <= 0 || viewportH <= 0)
        {
            return 0;
        }
        return Math.max(0, viewportH / rowBlock);
    }

    /**
     * Apply wheel scroll in "rows". Keeps remainder for smooth trackpads.
     * Returns the new offset.
     */
    public int onWheel(double preciseWheelRotation, int viewportH, int rowBlock, int totalRows, SelectionModel selection)
    {
        if (preciseWheelRotation == 0.0 || viewportH <= 0 || rowBlock <= 0 || totalRows <= 0)
        {
            return offsetRows;
        }

        int visible = visibleRows(viewportH, rowBlock);
        int maxOffset = Math.max(0, totalRows - visible);

        double rows = (preciseWheelRotation * scrollRowsPerNotch) + wheelRemainderRows;
        int deltaRows = (rows > 0) ? (int) Math.floor(rows) : (int) Math.ceil(rows);
        wheelRemainderRows = rows - deltaRows;

        if (deltaRows == 0)
        {
            return offsetRows;
        }

        offsetRows = clamp(offsetRows + deltaRows, maxOffset);
        // suppress ensureSelectionVisible for a few frames/ticks so scroll doesn't snap back
        suppressEnsureTicks = 6; // tune: 4-10 is fine
        return offsetRows;
    }

    /**
     * Ensures selected index is within visible window; updates offsetRows if needed.
     */
    public void ensureSelectionVisible(int totalRows, int viewportH, int rowBlock, SelectionModel selection)
    {
        if (suppressEnsureTicks > 0)
        {
            suppressEnsureTicks--;
            return;
        }

        if (selection == null || totalRows <= 0)
        {
            return;
        }

        int visible = visibleRows(viewportH, rowBlock);
        if (visible <= 0)
        {
            return;
        }

        int maxOffset = Math.max(0, totalRows - visible);

        int sel = clamp(selection.getSelectedIndex(), totalRows - 1);
        selection.setSelectedIndex(sel);

        if (sel < offsetRows)
        {
            offsetRows = sel;
        }
        else if (sel >= offsetRows + visible)
        {
            offsetRows = sel - visible + 1;
        }

        offsetRows = clamp(offsetRows, maxOffset);
    }

    public int setOffsetRows(int nextOffsetRows, int viewportH, int rowBlock, int totalRows)
    {
        int visible = visibleRows(viewportH, rowBlock);
        int maxOffset = Math.max(0, totalRows - visible);
        offsetRows = clamp(nextOffsetRows, maxOffset);
        wheelRemainderRows = 0.0;
        suppressEnsureTicks = 6;
        return offsetRows;
    }



    public void reset()
    {
        offsetRows = 0;
        wheelRemainderRows = 0.0;
    }

    private static int clamp(int v, int max)
    {
        return Math.max(0, Math.min(max, v));
    }
}

package com.amtrollin.xtremetasker.ui;

import com.amtrollin.xtremetasker.models.PrerequisiteStatus.MarkerIcon;
import com.amtrollin.xtremetasker.models.PrerequisiteStatus;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import net.runelite.api.Skill;

public final class PrerequisiteIconRenderer
{
    private static final int ICON_SIZE = 17;
    private static final int ICON_GAP = 2;
    private static final int TEXT_GAP = 5;
    private static final Map<BufferedImage, BufferedImage> SIZED_ICON_CACHE =
            Collections.synchronizedMap(new IdentityHashMap<>());
    private static final BufferedImage BULLET_ICON = createBulletIconImage();

    private PrerequisiteIconRenderer()
    {
    }

    public static int markerWidth(
            FontMetrics fm,
            PrerequisiteStatus status,
            Function<Skill, BufferedImage> imageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider)
    {
        List<Skill> skills = status == null ? List.of() : status.getSkillIcons();
        List<MarkerIcon> markerIcons = status == null ? List.of() : status.getMarkerIcons();
        if ((markerIcons == null || markerIcons.isEmpty()) && (skills == null || skills.isEmpty() || imageProvider == null))
        {
            return fm.stringWidth("- ");
        }

        if (firstIconImage(markerIcons, skills, imageProvider, markerImageProvider) == null)
        {
            return fm.stringWidth("- ");
        }

        return ICON_SIZE + TEXT_GAP;
    }

    public static int markerWidth(FontMetrics fm, BufferedImage markerImage)
    {
        return markerImage == null ? fm.stringWidth("- ") : ICON_SIZE + TEXT_GAP;
    }

    public static int lineHeight(int defaultLineHeight, PrerequisiteStatus status)
    {
        boolean hasIcons = status != null
                && ((status.getMarkerIcons() != null && !status.getMarkerIcons().isEmpty())
                || (status.getSkillIcons() != null && !status.getSkillIcons().isEmpty()));
        return hasIcons ? Math.max(defaultLineHeight, ICON_SIZE + 2) : defaultLineHeight;
    }

    public static int textWidth(
            FontMetrics fm,
            int maxWidth,
            PrerequisiteStatus status,
            Function<Skill, BufferedImage> imageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider)
    {
        return Math.max(0, maxWidth - markerWidth(fm, status, imageProvider, markerImageProvider));
    }

    public static int textWidth(FontMetrics fm, int maxWidth, BufferedImage markerImage)
    {
        return Math.max(0, maxWidth - markerWidth(fm, markerImage));
    }

    public static int textX(
            FontMetrics fm,
            int x,
            PrerequisiteStatus status,
            Function<Skill, BufferedImage> imageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider)
    {
        return x + markerWidth(fm, status, imageProvider, markerImageProvider);
    }

    public static int textX(FontMetrics fm, int x, BufferedImage markerImage)
    {
        return x + markerWidth(fm, markerImage);
    }

    public static BufferedImage resolveMarkerImage(
            PrerequisiteStatus status,
            Function<Skill, BufferedImage> imageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider)
    {
        List<Skill> skills = status == null ? List.of() : status.getSkillIcons();
        List<MarkerIcon> markerIcons = status == null ? List.of() : status.getMarkerIcons();
        if ((markerIcons == null || markerIcons.isEmpty()) && (skills == null || skills.isEmpty() || imageProvider == null))
        {
            return null;
        }

        return firstIconImage(markerIcons, skills, imageProvider, markerImageProvider);
    }

    public static void drawMarker(
            Graphics2D g,
            FontMetrics fm,
            PrerequisiteStatus status,
            Function<Skill, BufferedImage> imageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider,
            int x,
            int baselineY
    )
    {
        List<Skill> skills = status == null ? List.of() : status.getSkillIcons();
        List<MarkerIcon> markerIcons = status == null ? List.of() : status.getMarkerIcons();
        if ((markerIcons == null || markerIcons.isEmpty()) && (skills == null || skills.isEmpty() || imageProvider == null))
        {
            g.drawString("-", x, baselineY);
            return;
        }

        BufferedImage image = firstIconImage(markerIcons, skills, imageProvider, markerImageProvider);
        if (image == null)
        {
            g.drawString("-", x, baselineY);
            return;
        }

        int iconY = baselineY - fm.getAscent() + (fm.getHeight() - ICON_SIZE) / 2;
        g.drawImage(sizedIcon(image), x, iconY, null);
    }

    public static void drawMarker(
            Graphics2D g,
            FontMetrics fm,
            BufferedImage markerImage,
            int x,
            int baselineY
    )
    {
        if (markerImage == null)
        {
            g.drawString("-", x, baselineY);
            return;
        }

        int iconY = baselineY - fm.getAscent() + (fm.getHeight() - ICON_SIZE) / 2;
        g.drawImage(sizedIcon(markerImage), x, iconY, null);
    }

    private static BufferedImage firstIconImage(
            List<MarkerIcon> markerIcons,
            List<Skill> skills,
            Function<Skill, BufferedImage> imageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider)
    {
        if (markerIcons != null)
        {
            for (MarkerIcon markerIcon : markerIcons)
            {
                BufferedImage markerImage = markerImage(markerIcon, markerImageProvider);
                if (markerImage != null)
                {
                    return markerImage;
                }
            }
        }

        if (skills != null && imageProvider != null)
        {
            for (Skill skill : skills)
            {
                if (skill == null)
                {
                    continue;
                }

                BufferedImage image = imageProvider.apply(skill);
                if (image != null)
                {
                    return image;
                }
            }
        }

        return null;
    }

    private static BufferedImage markerImage(MarkerIcon markerIcon, Function<MarkerIcon, BufferedImage> markerImageProvider)
    {
        if (markerIcon == MarkerIcon.BULLET)
        {
            return BULLET_ICON;
        }
        return markerIcon == null || markerImageProvider == null ? null : markerImageProvider.apply(markerIcon);
    }

    private static BufferedImage sizedIcon(BufferedImage image)
    {
        if (image == null)
        {
            return null;
        }
        if (image.getWidth() == ICON_SIZE && image.getHeight() == ICON_SIZE)
        {
            return image;
        }

        BufferedImage cached = SIZED_ICON_CACHE.get(image);
        if (cached != null)
        {
            return cached;
        }

        BufferedImage sized = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = sized.createGraphics();
        Object oldInterpolation = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(image, 0, 0, ICON_SIZE, ICON_SIZE, null);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation != null ? oldInterpolation : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.dispose();

        SIZED_ICON_CACHE.put(image, sized);
        return sized;
    }

    private static BufferedImage createBulletIconImage()
    {
        BufferedImage image = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        Object oldAA = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(0, 0, 0, 125));
        g.fillOval(5, 6, 8, 8);
        g.setColor(new Color(224, 209, 155));
        g.fillOval(4, 5, 8, 8);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAA != null ? oldAA : RenderingHints.VALUE_ANTIALIAS_DEFAULT);
        g.dispose();
        return image;
    }
}

package com.amtrollin.xtremetasker.ui;

import com.amtrollin.xtremetasker.models.PrerequisiteStatus;
import com.amtrollin.xtremetasker.models.PrerequisiteStatus.MarkerIcon;
import com.amtrollin.xtremetasker.ui.style.UiPalette;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.Function;
import net.runelite.api.Skill;
import static com.amtrollin.xtremetasker.ui.style.UiPalette.withAlpha;
import static com.amtrollin.xtremetasker.ui.text.TextUtils.*;

public final class PrerequisiteSectionRenderer
{
    private final int rowHeight;
    private final Color uiText;
    private final Color uiTextDim;

    public PrerequisiteSectionRenderer(int rowHeight, Color uiText, Color uiTextDim)
    {
        this.rowHeight = rowHeight;
        this.uiText = uiText;
        this.uiTextDim = uiTextDim;
    }

    public int measureTip(String tip, FontMetrics fm, int maxWidth, int maxLines)
    {
        return rowHeight * Math.min(wrapText("Tip: " + safe(tip), fm, Math.max(maxWidth, 40)).size(), maxLines);
    }

    public int drawTip(Graphics2D g, FontMetrics fm, String tip, int x, int y, int maxWidth, int maxLines)
    {
        List<String> lines = wrapText("Tip: " + safe(tip), fm, Math.max(maxWidth, 40));
        g.setColor(uiTextDim);
        for (int i = 0; i < Math.min(lines.size(), maxLines); i++)
        {
            g.drawString(truncateToWidth(lines.get(i), fm, maxWidth), x, y);
            y += rowHeight;
        }
        return y;
    }

    public int measure(
            String prereqs,
            List<PrerequisiteStatus> statuses,
            FontMetrics fm,
            int maxWidth,
            Function<Skill, BufferedImage> skillImageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider)
    {
        if (statuses != null && !statuses.isEmpty())
        {
            int total = 0;
            for (PrerequisiteStatus status : statuses)
            {
                BufferedImage markerImage = PrerequisiteIconRenderer.resolveMarkerImage(status, skillImageProvider, markerImageProvider);
                int lineHeight = PrerequisiteIconRenderer.lineHeight(rowHeight, status);
                total += lineHeight * wrapText(status.getText(), fm,
                        PrerequisiteIconRenderer.textWidth(fm, maxWidth, markerImage)).size();
            }
            return total;
        }

        String formatted = formatText(prereqs);
        if (formatted.isEmpty())
        {
            return rowHeight;
        }

        int total = 0;
        for (String para : formatted.split("\n"))
        {
            String p = para.trim();
            if (!p.isEmpty())
            {
                total += rowHeight * wrapText(p, fm, maxWidth).size();
            }
        }
        return total;
    }

    public int render(
            Graphics2D g,
            FontMetrics fm,
            int x,
            int y,
            int maxWidth,
            String prereqs,
            List<PrerequisiteStatus> statuses,
            Function<Skill, BufferedImage> skillImageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider,
            Color rawTextColor)
    {
        if (statuses != null && !statuses.isEmpty())
        {
            return drawStatuses(g, fm, x, y, maxWidth, statuses, skillImageProvider, markerImageProvider);
        }

        String formatted = formatText(prereqs);
        if (formatted.isEmpty())
        {
            g.setColor(uiTextDim);
            g.drawString("None", x, y);
            return y + rowHeight;
        }

        g.setColor(rawTextColor);
        for (String para : formatted.split("\n"))
        {
            String p = para.trim();
            if (p.isEmpty())
            {
                continue;
            }

            for (String line : wrapText(p, fm, maxWidth))
            {
                g.drawString(truncateToWidth(line, fm, maxWidth), x, y);
                y += rowHeight;
            }
        }
        return y;
    }

    public static String normalizeText(String prereqs)
    {
        String normalized = safe(prereqs).replace("\r", "").trim();
        return normalized.isEmpty() || normalized.equalsIgnoreCase("none") || normalized.equalsIgnoreCase("n/a") || normalized.equals("-")
                ? ""
                : normalized;
    }

    private static String formatText(String prereqs)
    {
        return safe(prereqs).replace("\r", "").replaceAll("\\s*;\\s*", "\n").replaceAll("\n{2,}", "\n").trim();
    }

    private int drawStatuses(
            Graphics2D g,
            FontMetrics fm,
            int x,
            int y,
            int maxWidth,
            List<PrerequisiteStatus> statuses,
            Function<Skill, BufferedImage> skillImageProvider,
            Function<MarkerIcon, BufferedImage> markerImageProvider)
    {
        for (PrerequisiteStatus status : statuses)
        {
            BufferedImage markerImage = PrerequisiteIconRenderer.resolveMarkerImage(status, skillImageProvider, markerImageProvider);
            int textX = PrerequisiteIconRenderer.textX(fm, x, markerImage);
            int textWidth = PrerequisiteIconRenderer.textWidth(fm, maxWidth, markerImage);
            int lineHeight = PrerequisiteIconRenderer.lineHeight(rowHeight, status);
            boolean firstLine = true;
            for (String line : wrapText(status.getText(), fm, textWidth))
            {
                if (firstLine)
                {
                    PrerequisiteIconRenderer.drawMarker(g, fm, markerImage, x, y);
                }
                drawStatusLine(g, fm, status, truncateToWidth(line, fm, textWidth), textX, y);
                y += lineHeight;
                firstLine = false;
            }
        }
        return y;
    }

    private void drawStatusLine(Graphics2D g, FontMetrics fm, PrerequisiteStatus status, String line, int x, int y)
    {
        boolean hasCheckSpans = status.getCheckSpans() != null && !status.getCheckSpans().isEmpty();
        Color textColor = !hasCheckSpans && status.isCompleted() ? uiTextDim : uiText;
        if (isStartQuestLine(status, line))
        {
            String startText = "Start";
            g.setColor(UiPalette.TIER_COMPLETE_GLOW);
            g.drawString(startText, x, y);
            g.setColor(textColor);
            g.drawString(line.substring(startText.length()), x + fm.stringWidth(startText), y);
        }
        else
        {
            g.setColor(textColor);
            g.drawString(line, x, y);
        }

        if (!hasCheckSpans)
        {
            if (status.isCompleted())
            {
                drawStrikeThrough(g, fm, line, x, y);
            }
            return;
        }

        for (PrerequisiteStatus.CheckSpan span : status.getCheckSpans())
        {
            if (!span.isCompleted() || span.getStart() < 0 || span.getEnd() > status.getText().length() || span.getStart() >= span.getEnd())
            {
                continue;
            }

            String spanText = status.getText().substring(span.getStart(), span.getEnd());
            int lineIndex = line.indexOf(spanText);
            if (lineIndex < 0)
            {
                continue;
            }

            int spanX = x + fm.stringWidth(line.substring(0, lineIndex));
            g.setColor(uiTextDim);
            g.drawString(spanText, spanX, y);
            drawStrikeThrough(g, fm, spanText, spanX, y);
        }
    }

    private static boolean isStartQuestLine(PrerequisiteStatus status, String line)
    {
        return status.getMarkerIcons() != null
                && status.getMarkerIcons().contains(MarkerIcon.START_QUEST)
                && line != null
                && line.startsWith("Start");
    }

    private void drawStrikeThrough(Graphics2D g, FontMetrics fm, String text, int x, int y)
    {
        int strikeY = y - (fm.getAscent() * 3 / 5);
        g.setColor(withAlpha(uiTextDim, 170));
        g.drawLine(x, strikeY, x + fm.stringWidth(text), strikeY);
    }
}

