package com.amtrollin.xtremetasker.ui.text;

import java.awt.FontMetrics;
import java.util.*;

public final class TextUtils
{
    private static final int TRUNCATE_CACHE_LIMIT = 2048;
    private static final int WRAP_CACHE_LIMIT = 1024;
    private static final Map<String, String> TRUNCATE_CACHE = Collections.synchronizedMap(
            new LinkedHashMap<String, String>(TRUNCATE_CACHE_LIMIT + 1, 0.75f, true)
            {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, String> eldest)
                {
                    return size() > TRUNCATE_CACHE_LIMIT;
                }
            });
    private static final Map<String, List<String>> WRAP_CACHE = Collections.synchronizedMap(
            new LinkedHashMap<String, List<String>>(WRAP_CACHE_LIMIT + 1, 0.75f, true)
            {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, List<String>> eldest)
                {
                    return size() > WRAP_CACHE_LIMIT;
                }
            });

    private TextUtils() {}

    public static String safe(String text)
    {
        return text == null ? "" : text;
    }

    public static String titleCase(String value)
    {
        if (value == null || value.trim().isEmpty())
        {
            return null;
        }

        String trimmed = value.trim().replace('-', ' ').replace('_', ' ');
        StringBuilder out = new StringBuilder(trimmed.length());
        boolean capitalize = true;
        for (int i = 0; i < trimmed.length(); i++)
        {
            char ch = trimmed.charAt(i);
            if (Character.isWhitespace(ch))
            {
                out.append(ch);
                capitalize = true;
            }
            else
            {
                out.append(capitalize ? Character.toUpperCase(ch) : Character.toLowerCase(ch));
                capitalize = false;
            }
        }
        return out.toString();
    }

    public static String truncateToWidth(String text, FontMetrics fm, int maxWidth)
    {
        if (text == null)
        {
            return "";
        }

        if (fm.stringWidth(text) <= maxWidth)
        {
            return text;
        }

        String cacheKey = textCacheKey(text, fm, maxWidth);
        String cached = TRUNCATE_CACHE.get(cacheKey);
        if (cached != null)
        {
            return cached;
        }

        String ellipsis = "...";
        int ellipsisWidth = fm.stringWidth(ellipsis);

        StringBuilder sb = new StringBuilder();
        for (char c : text.toCharArray())
        {
            if (fm.stringWidth(sb.toString() + c) + ellipsisWidth > maxWidth)
            {
                break;
            }
            sb.append(c);
        }
        sb.append(ellipsis);
        String truncated = sb.toString();
        TRUNCATE_CACHE.put(cacheKey, truncated);
        return truncated;
    }

    public static List<String> wrapText(String text, FontMetrics fm, int maxWidth)
    {
        if (text == null)
        {
            return Collections.emptyList();
        }

        String cleaned = text.trim().replace("\r", "");
        if (cleaned.isEmpty())
        {
            return Collections.emptyList();
        }

        String cacheKey = textCacheKey(cleaned, fm, maxWidth);
        List<String> cached = WRAP_CACHE.get(cacheKey);
        if (cached != null)
        {
            return cached;
        }

        List<String> lines = new ArrayList<>();
        for (String paragraph : cleaned.split("\n"))
        {
            String p = paragraph.trim();
            if (p.isEmpty())
            {
                lines.add("");
                continue;
            }

            List<String> words = wrappingTokens(p);
            StringBuilder line = new StringBuilder();

            for (String w : words)
            {
                String candidate = (line.length() == 0) ? w : (line + " " + w);
                if (fm.stringWidth(candidate) <= maxWidth)
                {
                    line.setLength(0);
                    line.append(candidate);
                }
                else
                {
                    if (line.length() > 0)
                    {
                        lines.add(line.toString());
                        line.setLength(0);
                        line.append(w);
                    }
                    else
                    {
                        lines.add(truncateToWidth(w, fm, maxWidth));
                    }
                }
            }

            if (line.length() > 0)
            {
                lines.add(line.toString());
            }
        }

        List<String> wrapped = Collections.unmodifiableList(new ArrayList<>(lines));
        WRAP_CACHE.put(cacheKey, wrapped);
        return wrapped;
    }

    private static List<String> wrappingTokens(String text)
    {
        List<String> tokens = new ArrayList<>();
        StringBuilder word = new StringBuilder();

        for (int i = 0; i < text.length(); i++)
        {
            char c = text.charAt(i);
            if (Character.isWhitespace(c))
            {
                flushToken(tokens, word);
                continue;
            }

            if (c == '(')
            {
                int close = findMatchingParen(text, i);
                if (close > i)
                {
                    flushToken(tokens, word);
                    tokens.add(text.substring(i, close + 1).trim());
                    i = close;
                    continue;
                }
            }

            word.append(c);
        }

        flushToken(tokens, word);
        return tokens;
    }

    private static int findMatchingParen(String text, int openIndex)
    {
        int depth = 0;
        for (int i = openIndex; i < text.length(); i++)
        {
            char c = text.charAt(i);
            if (c == '(')
            {
                depth++;
            }
            else if (c == ')')
            {
                depth--;
                if (depth == 0)
                {
                    return i;
                }
            }
        }

        return -1;
    }

    private static void flushToken(List<String> tokens, StringBuilder word)
    {
        if (word.length() == 0)
        {
            return;
        }

        tokens.add(word.toString());
        word.setLength(0);
    }

    private static String textCacheKey(String text, FontMetrics fm, int maxWidth)
    {
        String fontKey = fm == null || fm.getFont() == null
                ? ""
                : fm.getFont().getFontName() + "|" + fm.getFont().getStyle() + "|" + fm.getFont().getSize2D();
        return fontKey + "|" + maxWidth + "|" + text;
    }
}

package com.amtrollin.xtremetasker.ui.widgets;

import com.amtrollin.xtremetasker.ui.style.*;
import com.amtrollin.xtremetasker.ui.text.TextUtils;
import java.awt.*;
import static com.amtrollin.xtremetasker.ui.style.UiDraw.centeredTextBaseline;
import static com.amtrollin.xtremetasker.ui.style.UiPalette.withAlpha;

public final class ButtonRenderer
{
    private final UiPalette palette;

    public ButtonRenderer(UiPalette palette)
    {
        this.palette = palette;
    }

    public void drawTab(Graphics2D g, Rectangle bounds, String text, boolean active)
    {
        Color bg = active ? palette.TAB_ACTIVE_BG : palette.TAB_INACTIVE_BG;
        drawBevelBox(g, bounds, bg);

        if (active)
        {
            g.setColor(palette.UI_GOLD);
            g.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
        }

        g.setColor(active ? palette.UI_TEXT : palette.UI_TEXT_DIM);

        drawCenteredText(g, bounds, text, 8);
    }

    /** Primary action button — used for Roll task / Mark complete. Brighter bg, solid gold border. */
    public void drawPrimaryButton(Graphics2D g, Rectangle bounds, String text)
    {
        drawPrimaryButton(g, bounds, text, null);
    }

    public void drawPrimaryButton(Graphics2D g, Rectangle bounds, String text, Color borderAccent)
    {
        if (bounds.width <= 0 || bounds.height <= 0) return;

        // Dark, slightly warm fill — not golden
        Color bg = new Color(55, 44, 28, 245);
        UiDraw.drawBevelBox(g, bounds, bg, palette.UI_EDGE_DARK, palette.UI_EDGE_LIGHT);

        // Outer dark edge
        g.setColor(palette.UI_EDGE_DARK);
        g.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
        // Inner gold accent at 130 alpha for a subtle decorative border
        Color accent = borderAccent == null ? palette.UI_GOLD : borderAccent;
        g.setColor(withAlpha(accent, borderAccent == null ? 130 : 230));
        g.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);

        // White/light text instead of gold
        g.setColor(palette.UI_TEXT);

        drawCenteredText(g, bounds, text, 10);
    }

    public void drawButton(Graphics2D g, Rectangle bounds, String text, boolean enabled)
    {
        if (bounds.width <= 0 || bounds.height <= 0)
        {
            return;
        }

        Color bg = enabled ? palette.BTN_ENABLED_BG : palette.BTN_DISABLED_BG;
        drawBevelBox(g, bounds, bg);

        if (enabled)
        {
            g.setColor(palette.UI_GOLD);
            g.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
        }

        g.setColor(enabled ? palette.UI_TEXT : withAlpha(palette.UI_TEXT_DIM, 130));

        drawCenteredText(g, bounds, text, 10);
    }

    /** Like drawButton but no gold border and dim-gray text — used for help-tab buttons. */
    public void drawPlainButton(Graphics2D g, Rectangle bounds, String text)
    {
        drawPlainButton(g, bounds, text, palette.BTN_ENABLED_BG);
    }

    public void drawPlainButton(Graphics2D g, Rectangle bounds, String text, Color bg)
    {
        drawPlainButton(g, bounds, text, bg, palette.UI_TEXT, null);
    }

    public void drawPlainButton(Graphics2D g, Rectangle bounds, String text, Color bg, Color textColor, Color outline)
    {
        if (bounds.width <= 0 || bounds.height <= 0)
        {
            return;
        }

        drawBevelBox(g, bounds, bg);

        if (outline != null)
        {
            g.setColor(outline);
            g.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);
        }

        g.setColor(textColor);

        drawCenteredText(g, bounds, text, 10);
    }

    public void drawBevelBox(Graphics2D g, Rectangle r, Color fill)
    {
        UiDraw.drawBevelBox(g, r, fill, palette.UI_EDGE_DARK, palette.UI_EDGE_LIGHT);
    }

    private void drawCenteredText(Graphics2D g, Rectangle bounds, String text, int pad)
    {
        FontMetrics fm = g.getFontMetrics();
        String drawText = TextUtils.truncateToWidth(text, fm, bounds.width - pad);
        g.drawString(drawText, bounds.x + (bounds.width - fm.stringWidth(drawText)) / 2, centeredTextBaseline(bounds, fm));
    }
}

package com.amtrollin.xtremetasker.verification;
import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.widgets.*;
import net.runelite.client.eventbus.*;

/**
 * Captures obtained collection log item IDs by listening to script 4100, which fires
 * once per item slot whenever a collection log page is rendered. args[1] = item ID,
 * args[2] = quantity (0 means not yet obtained).
 */
@Slf4j
@Singleton
public class CollectionLogWidgetMonitor
{
    // Script fired for each item slot in the collection log. args[1]=itemId, args[2]=quantity.
    private static final int CLOG_ITEM_DRAW_SCRIPT = 4100;
    // Script fired when the collection log interface is set up / a page is loaded.
    private static final int CLOG_SETUP_SCRIPT = 7797;
    // Legacy script that refreshes CLOG item slots beyond the visible page.
    private static final int CLOG_AUTO_SCAN_SCRIPT = 2240;
    private static final int CLOG_SEARCH_COMPONENT = 40697932;

    @Inject
    private Client client;

    @Inject
    private EventBus eventBus;

    @Inject
    private CollectionLogService collectionLogService;

    private int tickClogScriptFired = -1;
    private boolean isAutoScanInProgress = false;
    private int openSetupCacheBatches = 0;
    private int setupCacheBatchOpenedTick = -1;
    private int loggedItemDrawCount = 0;
    private int capturedSeenThisSession = 0;
    private int capturedObtainedThisSession = 0;

    public void startUp()
    {
        eventBus.register(this);
        reset();
    }

    public void shutDown()
    {
        eventBus.unregister(this);
        forceCloseSetupCacheBatches();
        reset();
    }

    private void reset()
    {
        tickClogScriptFired = -1;
        isAutoScanInProgress = false;
        openSetupCacheBatches = 0;
        setupCacheBatchOpenedTick = -1;
        loggedItemDrawCount = 0;
        capturedSeenThisSession = 0;
        capturedObtainedThisSession = 0;
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        int currentTick = client.getTickCount();
        if (openSetupCacheBatches > 0 && setupCacheBatchOpenedTick + 2 < currentTick)
        {
            forceCloseSetupCacheBatches();
        }

        if (tickClogScriptFired != -1 && tickClogScriptFired + 2 < currentTick)
        {
            tickClogScriptFired = -1;
            isAutoScanInProgress = false;
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST)
        {
            log.debug("XtremeTasker CLOG sync debug: collection draw-list script {} post-fired; scanning visible widget page",
                    ScriptID.COLLECTION_DRAW_LIST);
            scanCollectionLogEntryItemsWidget();
            return;
        }

        if (event.getScriptId() != CLOG_SETUP_SCRIPT)
        {
            return;
        }

        log.debug("XtremeTasker CLOG sync debug: setup script {} post-fired; open batches before end={}",
                CLOG_SETUP_SCRIPT, openSetupCacheBatches);
        endSetupCacheBatch();

        if (isAutoScanInProgress)
        {
            log.debug("XtremeTasker CLOG sync debug: auto scan already in progress");
            return;
        }

        // Script 2240 relies on the collection-log setup/render context. Deferring it
        // to a later game tick can leave only the currently visible item batch
        // available, which undercounts oversized entries such as clue rewards.
        runCollectionLogAutoScan();
    }

    private void runCollectionLogAutoScan()
    {
        isAutoScanInProgress = true;
        tickClogScriptFired = client.getTickCount();
        int seenBefore = collectionLogService.getSeenItemCount();
        int obtainedBefore = collectionLogService.getCapturedItemCount();
        collectionLogService.beginCacheChangeBatch();
        try
        {
            log.debug("XtremeTasker CLOG sync debug: firing collection log search action component={} before full auto scan",
                    CLOG_SEARCH_COMPONENT);
            client.menuAction(-1, CLOG_SEARCH_COMPONENT, MenuAction.CC_OP, 1, -1, "Search", null);
            client.runScript(CLOG_AUTO_SCAN_SCRIPT);
            scanCollectionLogEntryItemsWidget();
            collectionLogService.markFullSyncSeen();
        }
        finally
        {
            collectionLogService.endCacheChangeBatch();
            log.debug("XtremeTasker CLOG sync debug: finished full auto scan; seen {}->{} obtained {}->{} slotDraws={} seenCaptures={} obtainedCaptures={}",
                    seenBefore,
                    collectionLogService.getSeenItemCount(),
                    obtainedBefore,
                    collectionLogService.getCapturedItemCount(),
                    loggedItemDrawCount,
                    capturedSeenThisSession,
                    capturedObtainedThisSession);
        }
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired event)
    {
        if (event.getScriptId() == CLOG_SETUP_SCRIPT)
        {
            log.debug("XtremeTasker CLOG sync debug: setup script {} pre-fired at tick {}",
                    CLOG_SETUP_SCRIPT, client.getTickCount());
            beginSetupCacheBatch();
            return;
        }

        if (event.getScriptId() != CLOG_ITEM_DRAW_SCRIPT)
        {
            return;
        }

        tickClogScriptFired = client.getTickCount();

        Object[] args = event.getScriptEvent().getArguments();
        if (args == null || args.length < 3)
        {
            log.debug("XtremeTasker CLOG sync debug: item draw script {} fired with missing args length={}",
                    CLOG_ITEM_DRAW_SCRIPT, args == null ? -1 : args.length);
            return;
        }

        Integer itemId = scriptIntArg(args, 1);
        Integer quantity = scriptIntArg(args, 2);
        if (itemId == null || quantity == null)
        {
            log.debug("XtremeTasker CLOG sync debug: item draw script {} fired with nonnumeric item/quantity args length={} arg1={} arg2={}",
                    CLOG_ITEM_DRAW_SCRIPT, args.length, argSummary(args, 1), argSummary(args, 2));
            return;
        }

        if (loggedItemDrawCount < 60)
        {
            loggedItemDrawCount++;
            log.debug("XtremeTasker CLOG sync debug: item draw slot itemId={} quantity={} tick={} argsLength={}",
                    itemId, quantity, tickClogScriptFired, args.length);
        }

        if (itemId > 0)
        {
            collectionLogService.storeSeenItem(itemId);
            capturedSeenThisSession++;
        }

        // quantity > 0 means the item has been obtained at least once.
        if (quantity > 0)
        {
            collectionLogService.storeItem(itemId);
            capturedObtainedThisSession++;
        }
    }

    private void scanCollectionLogEntryItemsWidget()
    {
        Widget items = client == null ? null : client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
        if (items == null || items.isHidden())
        {
            log.debug("XtremeTasker CLOG sync debug: entry items widget unavailable after draw-list scan");
            return;
        }

        WidgetScanCount count = new WidgetScanCount();
        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        scanCollectionLogItemWidget(items, visited, count);
        log.debug("XtremeTasker CLOG sync debug: widget fallback scan found itemWidgets={} seenCaptured={} obtainedCaptured={}",
                count.itemWidgets, count.seenCaptured, count.obtainedCaptured);
    }

    private void scanCollectionLogItemWidget(Widget widget, Set<Widget> visited, WidgetScanCount count)
    {
        if (widget == null || !visited.add(widget))
        {
            return;
        }

        int itemId = widget.getItemId();
        if (itemId > 0)
        {
            count.itemWidgets++;
            collectionLogService.storeSeenItem(itemId);
            capturedSeenThisSession++;
            count.seenCaptured++;
        }

        scanCollectionLogItemWidgets(widget.getChildren(), visited, count);
        scanCollectionLogItemWidgets(widget.getDynamicChildren(), visited, count);
        scanCollectionLogItemWidgets(widget.getStaticChildren(), visited, count);
        scanCollectionLogItemWidgets(widget.getNestedChildren(), visited, count);
    }

    private void scanCollectionLogItemWidgets(Widget[] widgets, Set<Widget> visited, WidgetScanCount count)
    {
        if (widgets == null || widgets.length == 0)
        {
            return;
        }

        for (Widget widget : widgets)
        {
            scanCollectionLogItemWidget(widget, visited, count);
        }
    }

    private static final class WidgetScanCount
    {
        private int itemWidgets;
        private int seenCaptured;
        private int obtainedCaptured;
    }

    private static Object argSummary(Object[] args, int index)
    {
        if (args == null || index < 0 || index >= args.length)
        {
            return "<missing>";
        }
        Object arg = args[index];
        return arg == null ? "<null>" : arg + " (" + arg.getClass().getSimpleName() + ")";
    }

    private static Integer scriptIntArg(Object[] args, int index)
    {
        if (args == null || index < 0 || index >= args.length || !(args[index] instanceof Number))
        {
            return null;
        }

        return ((Number) args[index]).intValue();
    }

    private void beginSetupCacheBatch()
    {
        if (openSetupCacheBatches == 0)
        {
            setupCacheBatchOpenedTick = client.getTickCount();
        }

        openSetupCacheBatches++;
        collectionLogService.beginCacheChangeBatch();
    }

    private void endSetupCacheBatch()
    {
        if (openSetupCacheBatches <= 0)
        {
            openSetupCacheBatches = 0;
            setupCacheBatchOpenedTick = -1;
            return;
        }

        openSetupCacheBatches--;
        collectionLogService.endCacheChangeBatch();
        if (openSetupCacheBatches == 0)
        {
            setupCacheBatchOpenedTick = -1;
        }
    }

    private void forceCloseSetupCacheBatches()
    {
        while (openSetupCacheBatches > 0)
        {
            openSetupCacheBatches--;
            collectionLogService.endCacheChangeBatch();
        }
        setupCacheBatchOpenedTick = -1;
    }
}

package com.amtrollin.xtremetasker.verification;

import java.util.*;
import java.util.regex.*;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.widgets.*;
import net.runelite.client.eventbus.*;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

@Slf4j
@Singleton
public class CollectionLogService
{
    private static final String ANCIENT_PAGE_ITEM_NAME = "Ancient page";
    private static final String MEDALLION_FRAGMENT_ITEM_NAME = "Medallion fragment";

    // Matches the local player unlock notification, e.g. "New collection log item: Mark of grace."
    private static final Pattern CLOG_NEW_ITEM_PATTERN = Pattern.compile(
            "^\\s*New collection log item:\\s*(.+?)\\s*\\.?\\s*$",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern CLOG_REGIONAL_BROADCAST_PATTERN = Pattern.compile(
            "^\\s*\\[[^\\]]+\\]\\s+(.+?)\\s+received\\s+a\\s+new\\s+collection\\s+log\\s+item:\\s*(.+?)\\s*\\.?\\s*$",
            Pattern.CASE_INSENSITIVE
    );

    private static final Map<Integer, Integer> COLLECTION_LOG_ITEM_ALIASES = Map.ofEntries(
            Map.entry(24656, 20851), // Olmlet - Enraged Tektiny -> Olmlet
            Map.entry(24658, 20851), // Olmlet - Flying Vespina -> Olmlet
            Map.entry(22376, 20851), // Olmlet - Puppadile -> Olmlet
            Map.entry(22378, 20851), // Olmlet - Tektiny -> Olmlet
            Map.entry(22380, 20851), // Olmlet - Vanguard -> Olmlet
            Map.entry(22382, 20851), // Olmlet - Vasa minirio -> Olmlet
            Map.entry(22384, 20851), // Olmlet - Vespina -> Olmlet

            Map.entry(25749, 22473), // Lil' zik - Lil' Bloat -> Lil' zik
            Map.entry(25748, 22473), // Lil' zik - Lil' Maiden -> Lil' zik
            Map.entry(25750, 22473), // Lil' zik - Lil' Nylo -> Lil' zik
            Map.entry(25751, 22473), // Lil' zik - Lil' Sot -> Lil' zik
            Map.entry(25752, 22473), // Lil' zik - Lil' Xarp -> Lil' zik

            Map.entry(22481, 22323), // Sanguinesti staff (charged) -> Sanguinesti staff
            Map.entry(22486, 22325), // Scythe of vitur (charged) -> Scythe of vitur
            Map.entry(28549, 28547), // Tumeken's shadow (charged) -> Tumeken's shadow

            Map.entry(27382, 27352), // Tumeken's guardian - Akkhito -> Tumeken's guardian
            Map.entry(27383, 27352), // Tumeken's guardian - Babi -> Tumeken's guardian
            Map.entry(27387, 27352), // Tumeken's guardian - Elidinis' Damaged Guardian -> Tumeken's guardian
            Map.entry(27354, 27352), // Tumeken's guardian - Elidinis' Guardian -> Tumeken's guardian
            Map.entry(27384, 27352), // Tumeken's guardian - Kephriti -> Tumeken's guardian
            Map.entry(27386, 27352), // Tumeken's guardian - Tumeken's Damaged Guardian -> Tumeken's guardian
            Map.entry(27385, 27352), // Tumeken's guardian - Zebo -> Tumeken's guardian

            Map.entry(10860, 10859), // Tea flask animation item -> Tea flask
            Map.entry(10861, 10859), // Tea flask animation item -> Tea flask
            Map.entry(25617, 10859), // Tea flask interface item -> Tea flask

            Map.entry(25618, 10877), // Plain satchel interface item -> Plain satchel
            Map.entry(25619, 10878), // Green satchel interface item -> Green satchel
            Map.entry(25620, 10879), // Red satchel interface item -> Red satchel
            Map.entry(25621, 10880), // Black satchel interface item -> Black satchel
            Map.entry(25622, 10881), // Gold satchel interface item -> Gold satchel
            Map.entry(25623, 10882), // Rune satchel interface item -> Rune satchel

            Map.entry(27693, 27019), // Ore pack shop/interface item -> Ore pack collection log item
            Map.entry(27031, 27029)  // Smiths gloves (i) -> Smiths gloves
    );

    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private CollectionLogWidgetMonitor widgetMonitor;

    @Inject
    private ItemManager itemManager;

    private final Set<Integer> obtainedItems = new HashSet<>();
    private final Set<Integer> seenItems = new HashSet<>();
    private final Map<Integer, Long> obtainedItemOrder = new HashMap<>();
    private long nextObtainedItemOrder = 1L;
    private int pendingAncientPageDropCountSinceLastSync = 0;
    private int pendingMedallionFragmentDropCountSinceLastSync = 0;
    private Runnable cacheChangeListener;
    private int cacheChangeBatchDepth = 0;
    private boolean cacheChangePending = false;
    private boolean fullSyncSeen = false;
    private long lastSyncSeenAtMillis = 0L;
    private final Map<String, Integer> resolvedChatItemIdsByName = new HashMap<>();

    public void setCacheChangeListener(Runnable cacheChangeListener)
    {
        this.cacheChangeListener = cacheChangeListener;
    }

    public void startUp()
    {
        eventBus.register(this);
        widgetMonitor.startUp();
        reset();
    }

    public void shutDown()
    {
        eventBus.unregister(this);
        widgetMonitor.shutDown();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        // Capture newly obtained collection log items from the in-game notification.
        // This fires even when the Collection Log interface is closed.
        ChatMessageType type = event.getType();
        if (type != ChatMessageType.GAMEMESSAGE
                && type != ChatMessageType.SPAM
                && type != ChatMessageType.BROADCAST)
        {
            return;
        }

        String raw = event.getMessage();
        if (raw == null)
        {
            return;
        }

        // Strip any HTML colour tags RuneLite may inject.
        String clean = raw.replaceAll("<[^>]+>", "").trim();

        Matcher m = CLOG_NEW_ITEM_PATTERN.matcher(clean);
        if (type != ChatMessageType.BROADCAST && m.matches())
        {
            String itemName = m.group(1).trim();
            resolveAndStoreByName(itemName);
            return;
        }

        Matcher regionalBroadcastMatcher = CLOG_REGIONAL_BROADCAST_PATTERN.matcher(clean);
        if (type == ChatMessageType.BROADCAST
                && regionalBroadcastMatcher.matches()
                && isLocalPlayerName(regionalBroadcastMatcher.group(1)))
        {
            String itemName = regionalBroadcastMatcher.group(2).trim();
            resolveAndStoreByName(itemName);
        }
    }

    private boolean isLocalPlayerName(String playerName)
    {
        String localName;
        try
        {
            localName = client == null || client.getLocalPlayer() == null
                    ? null
                    : client.getLocalPlayer().getName();
        }
        catch (RuntimeException e)
        {
            return false;
        }

        String normalizedLocal = normalizePlayerName(localName);
        return !normalizedLocal.isEmpty() && normalizedLocal.equals(normalizePlayerName(playerName));
    }

    private static String normalizePlayerName(String value)
    {
        if (value == null)
        {
            return "";
        }

        return value
                .replaceAll("<[^>]+>", "")
                .replace('\u00A0', ' ')
                .trim()
                .replaceAll("\\s+", " ")
                .toLowerCase(Locale.ROOT);
    }

    private void resolveAndStoreByName(String itemName)
    {
        String cacheKey = chatItemNameCacheKey(itemName);
        Integer cachedItemId = resolvedChatItemIdsByName.get(cacheKey);
        if (cachedItemId != null)
        {
            storeItem(cachedItemId);
            return;
        }

        if (ANCIENT_PAGE_ITEM_NAME.equalsIgnoreCase(itemName))
        {
            pendingAncientPageDropCountSinceLastSync++;
            notifyCacheChanged();
            log.debug("Collection log chat capture deferred ambiguous Ancient page drop until CLOG sync");
            return;
        }

        if (MEDALLION_FRAGMENT_ITEM_NAME.equalsIgnoreCase(itemName))
        {
            pendingMedallionFragmentDropCountSinceLastSync++;
            notifyCacheChanged();
            log.debug("Collection log chat capture deferred ambiguous Medallion fragment drop until CLOG sync");
            return;
        }

        List<ItemPrice> results = itemManager.search(itemName);
        if (results == null || results.isEmpty())
        {
            log.debug("Collection log chat capture could not resolve item ID for '{}'", itemName);
            return;
        }

        for (ItemPrice result : results)
        {
            if (itemName.equalsIgnoreCase(result.getName()))
            {
                log.debug("Collection log chat capture: '{}' -> item ID {}", itemName, result.getId());
                resolvedChatItemIdsByName.put(cacheKey, result.getId());
                storeItem(result.getId());
                return;
            }
        }

        String normalizedTarget = normalizeItemName(itemName);
        List<ItemPrice> normalizedMatches = new ArrayList<>();
        for (ItemPrice result : results)
        {
            if (normalizedTarget.equals(normalizeItemName(result.getName())))
            {
                normalizedMatches.add(result);
            }
        }

        if (normalizedMatches.size() == 1)
        {
            ItemPrice resolved = normalizedMatches.get(0);
            log.debug("Collection log chat capture (normalized): '{}' -> item ID {}", itemName, resolved.getId());
            resolvedChatItemIdsByName.put(cacheKey, resolved.getId());
            storeItem(resolved.getId());
            return;
        }

        log.debug("Collection log chat capture ignored ambiguous match for '{}' ({} candidates)", itemName, results.size());
    }

    private static String chatItemNameCacheKey(String value)
    {
        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
    }

    private static String normalizeItemName(String value)
    {
        if (value == null)
        {
            return "";
        }

        return value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
    }

    public boolean isItemObtained(int itemId)
    {
        return obtainedItems.contains(itemId)
                || obtainedItems.contains(canonicalCollectionLogItemId(itemId));
    }

    public boolean hasSeenItem(int itemId)
    {
        return seenItems.contains(itemId)
                || seenItems.contains(canonicalCollectionLogItemId(itemId));
    }

    public void storeItem(int itemId)
    {
        if (itemId > 0)
        {
            int canonicalItemId = canonicalCollectionLogItemId(itemId);
            if (markObtainedItem(itemId, null))
            {
                log.debug("XtremeTasker CLOG sync debug: cached obtained itemId={} canonical={} obtainedCount={} seenCount={}",
                        itemId, canonicalItemId, obtainedItems.size(), seenItems.size());
                notifyCacheChanged();
            }
        }
    }

    public void storeSeenItem(int itemId)
    {
        if (itemId > 0)
        {
            int canonicalItemId = canonicalCollectionLogItemId(itemId);
            boolean changed = seenItems.add(itemId);
            changed |= seenItems.add(canonicalItemId);
            if (changed)
            {
                log.debug("XtremeTasker CLOG sync debug: cached seen itemId={} canonical={} obtainedCount={} seenCount={}",
                        itemId, canonicalItemId, obtainedItems.size(), seenItems.size());
                notifyCacheChanged();
            }
        }
    }

    public void beginCacheChangeBatch()
    {
        cacheChangeBatchDepth++;
    }

    public void endCacheChangeBatch()
    {
        if (cacheChangeBatchDepth <= 0)
        {
            cacheChangeBatchDepth = 0;
            return;
        }

        cacheChangeBatchDepth--;
        if (cacheChangeBatchDepth == 0 && cacheChangePending)
        {
            cacheChangePending = false;
            notifyCacheChanged();
        }
    }

    public boolean hasSeenAll(int[] itemIds)
    {
        if (itemIds == null || itemIds.length == 0)
        {
            return false;
        }

        Set<Integer> requiredCanonicalItemIds = new HashSet<>();
        for (int itemId : itemIds)
        {
            if (itemId > 0)
            {
                requiredCanonicalItemIds.add(canonicalCollectionLogItemId(itemId));
            }
        }

        if (requiredCanonicalItemIds.isEmpty())
        {
            return false;
        }

        for (int itemId : requiredCanonicalItemIds)
        {
            if (!hasSeenItem(itemId))
            {
                return false;
            }
        }

        return true;
    }

    public long countObtained(int[] itemIds)
    {
        if (itemIds == null || itemIds.length == 0)
        {
            return 0;
        }

        Set<Integer> countedCanonicalItemIds = new HashSet<>();
        long count = 0;
        for (int itemId : itemIds)
        {
            int canonicalItemId = canonicalCollectionLogItemId(itemId);
            if (canonicalItemId > 0
                    && countedCanonicalItemIds.add(canonicalItemId)
                    && isItemObtained(canonicalItemId))
            {
                count++;
            }
        }
        return count;
    }

    public int getCapturedItemCount()
    {
        return obtainedItems.size();
    }

    public int getSeenItemCount()
    {
        return seenItems.size();
    }

    public boolean hasFullSyncSeen()
    {
        return fullSyncSeen;
    }

    public long getLastSyncSeenAtMillis()
    {
        return lastSyncSeenAtMillis;
    }

    public void markSyncSeen()
    {
        lastSyncSeenAtMillis = System.currentTimeMillis();
        notifyCacheChanged();
    }

    public void markFullSyncSeen()
    {
        long now = System.currentTimeMillis();
        boolean changed = !fullSyncSeen || lastSyncSeenAtMillis != now;
        fullSyncSeen = true;
        lastSyncSeenAtMillis = now;
        if (pendingAncientPageDropCountSinceLastSync > 0)
        {
            pendingAncientPageDropCountSinceLastSync = 0;
            changed = true;
        }
        if (pendingMedallionFragmentDropCountSinceLastSync > 0)
        {
            pendingMedallionFragmentDropCountSinceLastSync = 0;
            changed = true;
        }
        if (changed)
        {
            notifyCacheChanged();
        }
    }

    public void restoreSyncEvidence(boolean fullSyncSeen, long lastSyncSeenAtMillis)
    {
        this.fullSyncSeen = fullSyncSeen;
        this.lastSyncSeenAtMillis = Math.max(0L, lastSyncSeenAtMillis);
    }

    public void restorePendingDropCounts(int pendingAncientPageDrops, int pendingMedallionFragmentDrops)
    {
        pendingAncientPageDropCountSinceLastSync = Math.max(0, pendingAncientPageDrops);
        pendingMedallionFragmentDropCountSinceLastSync = Math.max(0, pendingMedallionFragmentDrops);
    }

    public Set<Integer> getCachedItemIds()
    {
        return java.util.Collections.unmodifiableSet(obtainedItems);
    }

    public Map<Integer, Long> getCachedItemOrder()
    {
        return java.util.Collections.unmodifiableMap(obtainedItemOrder);
    }

    public int getPendingAncientPageDropCountSinceLastSync()
    {
        return Math.max(0, pendingAncientPageDropCountSinceLastSync);
    }

    public int getPendingMedallionFragmentDropCountSinceLastSync()
    {
        return Math.max(0, pendingMedallionFragmentDropCountSinceLastSync);
    }

    public void restoreCachedItemIds(Set<Integer> itemIds)
    {
        restoreCachedItemState(itemIds, null);
    }

    public void restoreCachedItemState(Set<Integer> itemIds, Map<Integer, Long> itemOrder)
    {
        if (itemIds == null || itemIds.isEmpty())
        {
            return;
        }

        for (Integer itemId : itemIds)
        {
            if (itemId != null && itemId > 0)
            {
                Long restoredOrder = itemOrder == null ? null : itemOrder.get(itemId);
                if (restoredOrder == null && itemOrder != null)
                {
                    restoredOrder = itemOrder.get(canonicalCollectionLogItemId(itemId));
                }
                markObtainedItem(itemId, restoredOrder);
                seenItems.add(itemId);
                seenItems.add(canonicalCollectionLogItemId(itemId));
            }
        }
    }

    public void resetCachedItemIds()
    {
        reset();
    }

    private void reset()
    {
        obtainedItems.clear();
        seenItems.clear();
        obtainedItemOrder.clear();
        nextObtainedItemOrder = 1L;
        pendingAncientPageDropCountSinceLastSync = 0;
        pendingMedallionFragmentDropCountSinceLastSync = 0;
        cacheChangeBatchDepth = 0;
        cacheChangePending = false;
        resolvedChatItemIdsByName.clear();
        fullSyncSeen = false;
        lastSyncSeenAtMillis = 0L;
    }

    public long getObtainedItemOrder(int itemId)
    {
        Long order = obtainedItemOrder.get(itemId);
        if (order != null)
        {
            return order;
        }
        order = obtainedItemOrder.get(canonicalCollectionLogItemId(itemId));
        return order == null ? Long.MAX_VALUE : order;
    }

    private boolean markObtainedItem(int itemId, Long restoredOrder)
    {
        int canonicalItemId = canonicalCollectionLogItemId(itemId);
        boolean changed = obtainedItems.add(itemId);
        changed |= obtainedItems.add(canonicalItemId);
        changed |= seenItems.add(itemId);
        changed |= seenItems.add(canonicalItemId);

        Long order = restoredOrder != null && restoredOrder > 0 ? restoredOrder : existingOrder(itemId, canonicalItemId);
        if (order == null)
        {
            order = nextObtainedItemOrder++;
            changed = true;
        }

        changed |= obtainedItemOrder.putIfAbsent(itemId, order) == null;
        changed |= obtainedItemOrder.putIfAbsent(canonicalItemId, order) == null;
        nextObtainedItemOrder = Math.max(nextObtainedItemOrder, order + 1);
        return changed;
    }

    private Long existingOrder(int itemId, int canonicalItemId)
    {
        Long order = obtainedItemOrder.get(itemId);
        if (order != null)
        {
            return order;
        }
        return obtainedItemOrder.get(canonicalItemId);
    }

    private int canonicalCollectionLogItemId(int itemId)
    {
        return COLLECTION_LOG_ITEM_ALIASES.getOrDefault(itemId, itemId);
    }

    public int canonicalItemId(int itemId)
    {
        return canonicalCollectionLogItemId(itemId);
    }

    private void notifyCacheChanged()
    {
        if (cacheChangeBatchDepth > 0)
        {
            cacheChangePending = true;
            log.debug("XtremeTasker CLOG sync debug: cache change batched depth={} obtainedCount={} seenCount={} fullSync={} lastSyncSeenAt={}",
                    cacheChangeBatchDepth, obtainedItems.size(), seenItems.size(), fullSyncSeen, lastSyncSeenAtMillis);
            return;
        }

        if (cacheChangeListener != null)
        {
            log.debug("XtremeTasker CLOG sync debug: notifying plugin cache listener obtainedCount={} seenCount={} fullSync={} lastSyncSeenAt={}",
                    obtainedItems.size(), seenItems.size(), fullSyncSeen, lastSyncSeenAtMillis);
            cacheChangeListener.run();
        }
        else
        {
            log.debug("XtremeTasker CLOG sync debug: cache changed but no listener is attached obtainedCount={} seenCount={} fullSync={} lastSyncSeenAt={}",
                    obtainedItems.size(), seenItems.size(), fullSyncSeen, lastSyncSeenAtMillis);
        }
    }
}

package com.amtrollin.xtremetasker.verification;

import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

@Slf4j
@Singleton
public class CombatAchievementService
{
    private static final int TASKS_PER_VARPLAYER = 32;

    // Varplayer IDs for CA task completion bits, in sort-order groups of 32.
    // Source: osrs-reldo/task-json-store task-types.json taskVarps field.
    // Tasks are not stored in a contiguous varplayer range; new CAs added over time
    // allocated new, non-sequential varplayer slots.
    private static final int[] CA_TASK_VARPS = {
        3116, 3117, 3118, 3119, 3120, 3121, 3122, 3123,
        3124, 3125, 3126, 3127, 3128, 3387, 3718, 3773,
        3774, 4204, 4496, 4721
    };

    @Inject
    private Client client;

    public boolean isTaskComplete(int sortId)
    {
        int varPlayerIndex = sortId / TASKS_PER_VARPLAYER;
        int bitPosition = sortId % TASKS_PER_VARPLAYER;

        if (varPlayerIndex < 0 || varPlayerIndex >= CA_TASK_VARPS.length)
        {
            log.debug("Invalid combat achievement task ID: {}", sortId);
            return false;
        }

        int varPlayerId = CA_TASK_VARPS[varPlayerIndex];
        int varPlayerValue = client.getVarpValue(varPlayerId);
        return (varPlayerValue & (1 << bitPosition)) != 0;
    }
}

package com.amtrollin.xtremetasker.verification;

import com.amtrollin.xtremetasker.models.PrerequisiteStatus.MarkerIcon;
import com.amtrollin.xtremetasker.models.PrerequisiteStatus;
import java.util.*;
import java.util.function.*;
import java.util.regex.*;
import javax.inject.*;
import lombok.NonNull;
import net.runelite.api.*;
import net.runelite.api.gameval.VarbitID;

@Singleton
public class PrerequisiteTrackerService
{
    private static final Pattern SKILL_PREREQ_PATTERN = Pattern.compile("^(\\d+)\\s+([A-Za-z][A-Za-z\\- ]+)$");
    private static final Pattern SKILL_PREREQ_PLUS_PATTERN = Pattern.compile("^(\\d+)\\+\\s+([A-Za-z][A-Za-z\\- ]+)$");
    private static final Pattern QUEST_PREREQ_PATTERN = Pattern.compile("^(.+?)\\s+quest$", Pattern.CASE_INSENSITIVE);
    private static final Pattern START_QUEST_PREREQ_PATTERN = Pattern.compile("^start\\s+(.+)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern SUBQUEST_PREREQ_PATTERN = Pattern.compile("^(.+?)\\s+subquest$", Pattern.CASE_INSENSITIVE);
    private static final Pattern MINIQUEST_PREREQ_PATTERN = Pattern.compile("^(.+?)\\s+miniquest$", Pattern.CASE_INSENSITIVE);
    private static final Pattern BARBARIAN_FIREMAKING_PART_1_PATTERN = Pattern.compile(
        "^part\\s+1\\s+of\\s+barbarian\\s+firemaking$",
        Pattern.CASE_INSENSITIVE
    );
    private static final Pattern QUEST_POINTS_PATTERN = Pattern.compile("^(\\d+)\\s+quest\\s+points?$", Pattern.CASE_INSENSITIVE);
    private static final Pattern COMBAT_LEVEL_PATTERN = Pattern.compile("^(\\d+)\\s+combat(?:\\s+level)?$", Pattern.CASE_INSENSITIVE);
    private static final Pattern TOTAL_LEVEL_PATTERN = Pattern.compile("^(\\d+)\\s+total\\s+level$", Pattern.CASE_INSENSITIVE);
    private static final Pattern FAVOR_PERCENT_PATTERN = Pattern.compile("^(?:reach\\s+)?(\\d+)%\\s+(.+?)\\s+favou?r$", Pattern.CASE_INSENSITIVE);
    private static final Pattern FAVOR_PREREQ_PATTERN = Pattern.compile("^(?:reach\\s+)?(.+?)\\s+favou?r$", Pattern.CASE_INSENSITIVE);
    private static final Pattern COINS_PATTERN = Pattern.compile("^([0-9][0-9,]*(?:\\.[0-9]+)?)\\s*([kmb]?)\\s*(?:coins?|gp)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern POINTS_PATTERN = Pattern.compile("^([0-9][0-9,]*(?:\\.[0-9]+)?)([kmb]?)\\s+(.+?)\\s+points?$", Pattern.CASE_INSENSITIVE);
    private static final Pattern DIARY_PREREQ_PATTERN = Pattern.compile(
        "^(?:complete\\s+the\\s+)?(.+?)\\s+(easy|medium|hard|elite)\\s+diary$",
        Pattern.CASE_INSENSITIVE
    );
    private static final Pattern COMBINED_LEVEL_PATTERN = Pattern.compile(
        "^(?:a\\s+)?combined\\s+([A-Za-z][A-Za-z\\- ]+?)\\s+and\\s+([A-Za-z][A-Za-z\\- ]+?)\\s+level\\s+of\\s+(?:at\\s+least\\s+)?(\\d+)(?:\\s*[,\\(]?\\s*or\\s+(?:level\\s+)?(\\d+)\\s+in\\s+(?:either(?:\\s+skill)?|one)\\)?)?",
        Pattern.CASE_INSENSITIVE
    );
    private static final Pattern TRACKABLE_SKILL_SPAN_PATTERN = Pattern.compile(
        "\\b(\\d+)\\+?\\s+([A-Za-z][A-Za-z\\- ]*?)(?=\\s*(?:\\(|\\bor\\b|\\band\\b|,|;|$))",
        Pattern.CASE_INSENSITIVE
    );

    private final Map<String, Skill> skillsByName = new HashMap<>();
    private final Map<String, Quest> questsByName = new HashMap<>();
    private final Map<String, Integer> varbitsByName = new HashMap<>();
    private final IntUnaryOperator varbitReader;
    private final ToIntFunction<Skill> skillLevelReader;
    private static final int VARBIT_TAI_BWO_WANNAI_CLEANUP = 4600;

    @Inject
    private Client client;

    public PrerequisiteTrackerService()
    {
        this(null, null);
    }

    PrerequisiteTrackerService(IntUnaryOperator varbitReader)
    {
        this(varbitReader, null);
    }

    PrerequisiteTrackerService(IntUnaryOperator varbitReader, ToIntFunction<Skill> skillLevelReader)
    {
        registerSkills();
        registerQuests();
        registerVarbits();
        this.varbitReader = varbitReader;
        this.skillLevelReader = skillLevelReader;
    }

    public List<PrerequisiteStatus> evaluate(@NonNull String prereqs)
    {
        List<PrerequisiteStatus> out = new ArrayList<>();
        for (String token : splitPrereqs(prereqs))
        {
            String text = token.trim();
            if (text.isEmpty())
            {
                continue;
            }

            out.add(new PrerequisiteStatus(text, isSatisfied(text), checkSpans(text), skillIcons(text), markerIcons(text)));
        }
        return out;
    }

    /**
     * Checks whether an achievement diary has been completed using the region slug
     * (e.g. "ardougne", "kourend-and-kebos") and difficulty (e.g. "easy", "hard", "elite")
     * as stored in the verification block of tasks.json.
     */
    public boolean isDiaryComplete(String region, String difficulty)
    {
        if (region == null || difficulty == null)
        {
            return false;
        }
        String regionKey = toDiaryRegionKey(region);
        if (regionKey == null)
        {
            return false;
        }
        String difficultyKey = difficulty.toUpperCase(Locale.ROOT);
        Integer varbitId = varbitsByName.get("DIARY_" + regionKey + "_" + difficultyKey);
        if (varbitId == null)
        {
            return false;
        }

        int value = getVarbitValue(varbitId);
        Integer requiredValue = diaryCompletionThreshold(regionKey, difficultyKey);
        return requiredValue == null ? value > 0 : value >= requiredValue;
    }

    private Integer diaryCompletionThreshold(String regionKey, String difficultyKey)
    {
        if (!"KARAMJA".equals(regionKey))
        {
            return null;
        }

        switch (difficultyKey)
        {
            case "EASY":
                return 10;
            case "MEDIUM":
                return 19;
            case "HARD":
                return 10;
            case "ELITE":
                return 5;
            default:
                return null;
        }
    }

    /**
     * Counts how many skills from the given set of skill names are at level 99.
     * Skill names are as used in tasks.json experience maps (e.g. "attack", "runecraft", "sailing").
     * Unknown skills (e.g. Sailing before RuneLite support) are silently skipped.
     */
    public int countSkillsAt99(java.util.Set<String> skillNames)
    {
        int count = 0;
        for (String name : skillNames)
        {
            Skill skill = findSkill(name);
            if (skill != null && realSkillLevel(skill) >= 99)
            {
                count++;
            }
        }
        return count;
    }

    private List<String> splitPrereqs(String prereqs)
    {
        String normalized = prereqs.replace("\r", "")
                .replaceAll("\\s*;\\s*", "\n")
                .replaceAll("\n{2,}", "\n")
                .trim();

        if (normalized.isEmpty() || "none".equalsIgnoreCase(normalized))
        {
            return List.of();
        }

        String[] pieces = normalized.split("\\n");
        List<String> out = new ArrayList<>(pieces.length);
        for (String piece : pieces)
        {
            String p = piece.trim();
            if (!p.isEmpty())
            {
                out.add(p);
            }
        }
        return out;
    }

    private boolean isSatisfied(String prerequisite)
    {
        String normalizedPrereq = stripLeadingLabel(cleanupToken(prerequisite)).replaceFirst("(?i)^either\\s+", "");

        Matcher combinedMatcher = COMBINED_LEVEL_PATTERN.matcher(normalizedPrereq);
        if (combinedMatcher.matches())
        {
            Skill firstSkill = findSkill(combinedMatcher.group(1));
            Skill secondSkill = findSkill(combinedMatcher.group(2));
            if (firstSkill == null || secondSkill == null)
            {
                return false;
            }

            int requiredCombined = Integer.parseInt(combinedMatcher.group(3));
            int firstLevel = realSkillLevel(firstSkill);
            int secondLevel = realSkillLevel(secondSkill);
            if ((firstLevel + secondLevel) >= requiredCombined)
            {
                return true;
            }

            String eitherThreshold = combinedMatcher.group(4);
            return eitherThreshold != null
                    && (firstLevel >= Integer.parseInt(eitherThreshold)
                    || secondLevel >= Integer.parseInt(eitherThreshold));
        }

        Matcher diaryMatcher = DIARY_PREREQ_PATTERN.matcher(normalizedPrereq);
        if (diaryMatcher.matches())
        {
            return isDiaryComplete(diaryMatcher.group(1), diaryMatcher.group(2));
        }

        String[] disjunctions = normalizedPrereq.split("(?i)\\s+or\\s+");
        if (disjunctions.length > 1)
        {
            for (String option : disjunctions)
            {
                if (isSatisfiedAtomic(option))
                {
                    return true;
                }
            }
            return false;
        }

        return isSatisfiedAtomic(normalizedPrereq);
    }

    private boolean isSatisfiedAtomic(String prerequisite)
    {
        String normalized = stripLeadingLabel(cleanupToken(prerequisite)).replaceFirst("(?i)^either\\s+", "");

        if (BARBARIAN_FIREMAKING_PART_1_PATTERN.matcher(normalized).matches())
        {
            return isBarbarianFiremakingPart1Complete();
        }

        String skillCandidate = stripTrailingParenthetical(normalized);
        Matcher skillMatcher = SKILL_PREREQ_PATTERN.matcher(skillCandidate);
        if (skillMatcher.matches())
        {
            int requiredLevel = Integer.parseInt(skillMatcher.group(1));
            Skill skill = findSkill(skillMatcher.group(2));
            return skill != null && realSkillLevel(skill) >= requiredLevel;
        }

        Matcher skillPlusMatcher = SKILL_PREREQ_PLUS_PATTERN.matcher(skillCandidate);
        if (skillPlusMatcher.matches())
        {
            int requiredLevel = Integer.parseInt(skillPlusMatcher.group(1));
            Skill skill = findSkill(skillPlusMatcher.group(2));
            return skill != null && realSkillLevel(skill) >= requiredLevel;
        }

        Matcher questPointsMatcher = QUEST_POINTS_PATTERN.matcher(normalized);
        if (questPointsMatcher.matches())
        {
            int requiredPoints = Integer.parseInt(questPointsMatcher.group(1));
            return client != null && client.getVarpValue(VarPlayer.QUEST_POINTS) >= requiredPoints;
        }

        Matcher favorMatcher = FAVOR_PERCENT_PATTERN.matcher(normalized);
        if (favorMatcher.matches() && isTaiBwoFavorLabel(favorMatcher.group(2)))
        {
            int requiredFavor = Integer.parseInt(favorMatcher.group(1));
            return getVarbitValue(VARBIT_TAI_BWO_WANNAI_CLEANUP) >= requiredFavor;
        }

        Matcher bareFavorMatcher = FAVOR_PREREQ_PATTERN.matcher(normalized);
        if (bareFavorMatcher.matches() && isTaiBwoFavorLabel(bareFavorMatcher.group(1)))
        {
            return getVarbitValue(VARBIT_TAI_BWO_WANNAI_CLEANUP) >= 100;
        }

        Matcher coinsMatcher = COINS_PATTERN.matcher(normalized);
        if (coinsMatcher.matches())
        {
            long requiredCoins = parseScaledNumber(coinsMatcher.group(1), coinsMatcher.group(2));
            if (requiredCoins <= 0)
            {
                return false;
            }

            return getKnownCoins() >= requiredCoins;
        }

        Matcher pointsMatcher = POINTS_PATTERN.matcher(normalized);
        if (pointsMatcher.matches())
        {
            long requiredPoints = parseScaledNumber(pointsMatcher.group(1), pointsMatcher.group(2));
            if (requiredPoints <= 0)
            {
                return false;
            }

            Integer currentPoints = getPointsFor(pointsMatcher.group(3));
            return currentPoints != null && currentPoints >= requiredPoints;
        }

        Matcher combatMatcher = COMBAT_LEVEL_PATTERN.matcher(normalized);
        if (combatMatcher.matches())
        {
            int requiredCombat = Integer.parseInt(combatMatcher.group(1));
            return client != null && client.getLocalPlayer() != null && client.getLocalPlayer().getCombatLevel() >= requiredCombat;
        }

        Matcher totalLevelMatcher = TOTAL_LEVEL_PATTERN.matcher(normalized);
        if (totalLevelMatcher.matches())
        {
            int requiredTotal = Integer.parseInt(totalLevelMatcher.group(1));
            return client != null && client.getTotalLevel() >= requiredTotal;
        }

        Matcher startQuestMatcher = START_QUEST_PREREQ_PATTERN.matcher(normalized);
        if (startQuestMatcher.matches())
        {
            if (client == null)
            {
                return false;
            }

            Quest quest = findQuestWithOptionalQuestSuffix(startQuestMatcher.group(1));
            if (quest == null)
            {
                return false;
            }

            QuestState state = quest.getState(client);
            return state == QuestState.IN_PROGRESS || state == QuestState.FINISHED;
        }

        Matcher questMatcher = QUEST_PREREQ_PATTERN.matcher(normalized);
        if (questMatcher.matches())
        {
            if (client == null)
            {
                return false;
            }

            Quest quest = findQuestWithOptionalQuestSuffix(normalized);
            return quest != null && quest.getState(client) == QuestState.FINISHED;
        }

        return false;
    }

