public class TaskListQuery
{
    public String searchText = "";
    public boolean searchFocused = false;
    // Search selection (indices into searchText; -1 = no selection)
    public int searchSelStart = -1;
    public int searchSelEnd = -1;

    // =========================
    // Source filters
    // =========================
    public enum SourceFilter
    {
        ALL,
        CA,
        CLOGS,
        DAS
    }

    public enum StatusFilter
    {
        ALL,
        INCOMPLETE,
        COMPLETE
    }

    public enum SortColumn
    {
        DATE,
        SPENT
    }

    public enum SortDirection
    {
        OFF,
        ASC,
        DESC
    }

    public boolean sourceCASelected = true;
    public boolean sourceClogsSelected = true;
    public boolean sourceDasSelected = true;
    public StatusFilter statusFilter = StatusFilter.ALL;
    public SortColumn sortColumn = SortColumn.DATE;
    public SortDirection sortDirection = SortDirection.OFF;
    public boolean showDateCompletedColumn = true;
    public boolean showTimeSpentColumn = true;

    public boolean isFilterCA()
    {
        return isSourceAllSelected() || sourceCASelected;
    }

    public boolean isFilterCL()
    {
        return isSourceAllSelected() || sourceClogsSelected;
    }

    public boolean isFilterDA()
    {
        return isSourceAllSelected() || sourceDasSelected;
    }

    public boolean isSourceAllSelected()
    {
        return sourceCASelected && sourceClogsSelected && sourceDasSelected;
    }

    public void selectAllSources()
    {
        sourceCASelected = true;
        sourceClogsSelected = true;
        sourceDasSelected = true;
    }

    public void setOnlySource(SourceFilter source)
    {
        if (source == null || source == SourceFilter.ALL)
        {
            selectAllSources();
            return;
        }

        sourceCASelected = source == SourceFilter.CA;
        sourceClogsSelected = source == SourceFilter.CLOGS;
        sourceDasSelected = source == SourceFilter.DAS;
    }

    public void setCollectionLogAndDiarySources()
    {
        sourceCASelected = false;
        sourceClogsSelected = true;
        sourceDasSelected = true;
    }

    public boolean toggleSort(SortColumn column)
    {
        if (column == null)
        {
            return false;
        }

        if (sortColumn == column)
        {
            switch (sortDirection)
            {
                case OFF:
                    sortDirection = SortDirection.ASC;
                    break;
                case ASC:
                    sortDirection = SortDirection.DESC;
                    break;
                case DESC:
                default:
                    sortDirection = SortDirection.OFF;
                    break;
            }
            return true;
        }

        sortColumn = column;
        sortDirection = SortDirection.ASC;
        return true;
    }

    public boolean isColumnVisible(SortColumn column)
    {
        if (column == null)
        {
            return false;
        }
        switch (column)
        {
            case DATE:
                return showDateCompletedColumn;
            case SPENT:
                return showTimeSpentColumn;
            default:
                return true;
        }
    }

    public boolean toggleSource(SourceFilter source)
    {
        if (source == null)
        {
            return false;
        }

        boolean beforeCA = sourceCASelected;
        boolean beforeClogs = sourceClogsSelected;
        boolean beforeDas = sourceDasSelected;

        if (source == SourceFilter.ALL)
        {
            selectAllSources();
            return beforeCA != sourceCASelected || beforeClogs != sourceClogsSelected || beforeDas != sourceDasSelected;
        }

        if (isSourceAllSelected())
        {
            setOnlySource(source);
            return true;
        }

        switch (source)
        {
            case CA:
                sourceCASelected = !sourceCASelected;
                break;
            case CLOGS:
                sourceClogsSelected = !sourceClogsSelected;
                break;
            case DAS:
                sourceDasSelected = !sourceDasSelected;
                break;
            default:
                break;
        }

        if (!sourceCASelected && !sourceClogsSelected && !sourceDasSelected)
        {
            selectAllSources();
        }
        return beforeCA != sourceCASelected || beforeClogs != sourceClogsSelected || beforeDas != sourceDasSelected;
    }

    public boolean isFilterIncomplete()
    {
        return statusFilter == StatusFilter.ALL || statusFilter == StatusFilter.INCOMPLETE;
    }

    public boolean isFilterComplete()
    {
        return statusFilter == StatusFilter.ALL || statusFilter == StatusFilter.COMPLETE;
    }

    public enum TierScope
    {
        THIS_TIER,
        ALL_TIERS
    }

    public TierScope tierScope = TierScope.THIS_TIER;

    // Session-only: show only new tasks. Cleared when newTaskIds is cleared (logout).
    public boolean showNewTasksFilter = false;
}

package com.amtrollin.xtremetasker.tasklist;

import com.amtrollin.xtremetasker.models.XtremeTask;
import com.amtrollin.xtremetasker.models.verification.TaskVerification;
import java.util.*;

public final class TaskGroupUtils
{
    private TaskGroupUtils()
    {
    }

    public static List<XtremeTask> collapsePreservingOrder(List<XtremeTask> tasks)
    {
        if (tasks == null || tasks.isEmpty())
        {
            return new ArrayList<>();
        }

        Map<String, XtremeTask> firstByKey = new LinkedHashMap<>();
        for (XtremeTask task : tasks)
        {
            if (task != null)
            {
                firstByKey.putIfAbsent(key(task), task);
            }
        }
        return new ArrayList<>(firstByKey.values());
    }

    public static List<XtremeTask> groupFor(List<XtremeTask> allTasks, XtremeTask target)
    {
        List<XtremeTask> out = new ArrayList<>();
        if (allTasks == null || target == null)
        {
            return out;
        }

        String targetKey = key(target);
        for (XtremeTask task : allTasks)
        {
            if (task != null && targetKey.equals(key(task)))
            {
                out.add(task);
            }
        }
        return out;
    }

    public static String key(XtremeTask task)
    {
        if (task == null)
        {
            return "";
        }

        String countedCollectionLogKey = countedCollectionLogKey(task);
        if (countedCollectionLogKey != null)
        {
            return countedCollectionLogKey;
        }

        return normalize(task.getName())
                + "|source=" + Objects.toString(task.getSource(), "")
                + "|tier=" + Objects.toString(task.getTier(), "");
    }

    private static String countedCollectionLogKey(XtremeTask task)
    {
        TaskVerification verification = task.getVerification();
        if (verification == null
                || verification.getType() != TaskVerification.VerificationType.COLLECTION_LOG
                || verification.getCount() == null)
        {
            return null;
        }

        int[] itemIds = verification.getItemIds();
        if (itemIds == null || itemIds.length == 0)
        {
            return null;
        }

        int[] sortedItemIds = Arrays.stream(itemIds)
                .filter(itemId -> itemId > 0)
                .distinct()
                .sorted()
                .toArray();
        String items = Arrays.stream(sortedItemIds)
                .mapToObj(String::valueOf)
                .reduce((a, b) -> a + "," + b)
                .orElse("");
        if (items.isEmpty())
        {
            return null;
        }

        return "counted-cl|source=" + Objects.toString(task.getSource(), "")
                + "|tier=" + Objects.toString(task.getTier(), "")
                + "|items=" + items;
    }

    private static String normalize(String value)
    {
        if (value == null)
        {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package com.amtrollin.xtremetasker.tasklist;

import com.amtrollin.xtremetasker.models.XtremeTask;
import com.amtrollin.xtremetasker.tasklist.models.TaskListQuery;
import java.util.function.Predicate;

public final class TaskListFilter
{
    private TaskListFilter() {}

    public interface CompletionLookup
    {
        boolean isCompleted(XtremeTask task);
    }

    public interface NewTaskLookup
    {
        boolean isNew(XtremeTask task);
    }

    public static Predicate<XtremeTask> build(TaskListQuery query, CompletionLookup completed)
    {
        return build(query, completed, null);
    }

    public static Predicate<XtremeTask> build(TaskListQuery query, CompletionLookup completed, NewTaskLookup isNew)
    {
        if (query == null)
        {
            query = new TaskListQuery();
        }

        final boolean includeCA = query.isFilterCA();
        final boolean includeClogs = query.isFilterCL();
        final boolean includeDas = query.isFilterDA();
        final boolean sourceAll = query.isSourceAllSelected();
        final TaskListQuery.StatusFilter statusFilter = query.statusFilter;
        final boolean filterNew = query.showNewTasksFilter && isNew != null;

        return t ->
        {
            if (t == null)
            {
                return false;
            }

            // -------------------------
            // 0) New tasks filter (session-only)
            // -------------------------
            if (filterNew && !isNew.isNew(t))
            {
                return false;
            }

            // -------------------------
            // 1) Source filter
            // -------------------------
            if (!sourceAll)
            {
                boolean ok = (includeCA && isCombatAchievementTask(t))
                        || (includeClogs && isCollectionLogTask(t))
                        || (includeDas && isDiaryAchievementTask(t));

                if (!ok)
                {
                    return false;
                }
            }

            // -------------------------
            // 2) Status filter
            // -------------------------
            if (statusFilter != null && statusFilter != TaskListQuery.StatusFilter.ALL)
            {
                boolean isDone = completed != null && completed.isCompleted(t);

                boolean ok;
                switch (statusFilter)
                {
                    case INCOMPLETE:
                        ok = !isDone;
                        break;
                    case COMPLETE:
                        ok = isDone;
                        break;
                    default:
                        ok = true;
                        break;
                }

                return ok;
            }

            return true;
        };
    }

    // =========================================================
    // SOURCE DETECTION
    // Update these two methods to match your actual XtremeTask model.
    // =========================================================

    private static boolean isCombatAchievementTask(XtremeTask t)
    {

        String src = safeLower(String.valueOf(t.getSource()));
        if (!src.isEmpty())
        {
            return src.contains("combat");
        }

        return false;
    }

    private static boolean isCollectionLogTask(XtremeTask t)
    {

        String src = safeLower(String.valueOf(t.getSource()));
        if (!src.isEmpty())
        {
            return src.contains("collection");
        }

        return false;
    }

    private static boolean isDiaryAchievementTask(XtremeTask t)
    {

        String src = safeLower(String.valueOf(t.getSource()));
        if (!src.isEmpty())
        {
            return src.contains("diary");
        }

        return false;
    }

    private static String safeLower(String s)
    {
        return s == null ? "" : s.toLowerCase();
    }
}

package com.amtrollin.xtremetasker.tasklist;

import com.amtrollin.xtremetasker.enums.*;
import com.amtrollin.xtremetasker.models.*;
import com.amtrollin.xtremetasker.models.verification.TaskVerification;
import com.amtrollin.xtremetasker.tasklist.models.TaskListQuery;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

public final class TaskListSorter
{
    private TaskListSorter() {}

    public static Comparator<XtremeTask> comparator(TaskListQuery q, TaskListFilter.CompletionLookup completed)
    {
        return comparator(q, completed, null, null);
    }

    public static Comparator<XtremeTask> comparator(
            TaskListQuery q,
            TaskListFilter.CompletionLookup completed,
            Function<XtremeTask, CompletionInfo> completionInfoProvider,
            Function<XtremeTask, Long> taskTicksProvider)
    {
        TaskListQuery.SortColumn sortColumn = q == null || q.sortColumn == null
                ? TaskListQuery.SortColumn.DATE
                : q.sortColumn;
        TaskListQuery.SortDirection sortDirection = q == null || q.sortDirection == null
                ? TaskListQuery.SortDirection.OFF
                : q.sortDirection;

        return (a, b) ->
        {
            int cmp;
            boolean directionApplied = false;
            if (sortDirection == TaskListQuery.SortDirection.OFF)
            {
                cmp = compareTaskName(a, b, true);
            }
            else switch (sortColumn)
            {
                case DATE:
                    cmp = compareDateCompleted(a, b, completionInfoProvider, sortDirection);
                    directionApplied = true;
                    break;
                case SPENT:
                    cmp = compareTimeSpent(a, b, taskTicksProvider, sortDirection);
                    directionApplied = true;
                    break;
                default:
                    cmp = compareTaskName(a, b, true);
                    break;
            }

            if (!directionApplied && sortDirection == TaskListQuery.SortDirection.DESC)
            {
                cmp = -cmp;
            }

            return cmp;
        };
    }

    private static int compareTaskName(XtremeTask a, XtremeTask b, boolean preserveCountedSequence)
    {
        if (preserveCountedSequence)
        {
            int sequenceCmp = compareCountedCollectionLogSequence(a, b);
            if (sequenceCmp != 0) return sequenceCmp;
        }

        int nameCmp = safeName(a).compareToIgnoreCase(safeName(b));
        if (nameCmp != 0) return nameCmp;

        int sourceCmp = Integer.compare(sourceRank(a == null ? null : a.getSource()), sourceRank(b == null ? null : b.getSource()));
        if (sourceCmp != 0) return sourceCmp;

        int tierCmp = Integer.compare(tierRank(a == null ? null : a.getTier()), tierRank(b == null ? null : b.getTier()));
        if (tierCmp != 0) return tierCmp;

        return safeId(a).compareToIgnoreCase(safeId(b));
    }

    private static int compareDateCompleted(
            XtremeTask a,
            XtremeTask b,
            Function<XtremeTask, CompletionInfo> completionInfoProvider,
            TaskListQuery.SortDirection sortDirection)
    {
        long at = completionTimestamp(a, completionInfoProvider);
        long bt = completionTimestamp(b, completionInfoProvider);
        int missingCmp = Boolean.compare(at == Long.MAX_VALUE, bt == Long.MAX_VALUE);
        if (missingCmp != 0) return missingCmp;

        int dateCmp = Long.compare(at, bt);
        if (sortDirection == TaskListQuery.SortDirection.DESC)
        {
            dateCmp = -dateCmp;
        }
        if (dateCmp != 0) return dateCmp;
        return compareTaskName(a, b, false);
    }

    private static int compareTimeSpent(
            XtremeTask a,
            XtremeTask b,
            Function<XtremeTask, Long> taskTicksProvider,
            TaskListQuery.SortDirection sortDirection)
    {
        long at = taskTicks(a, taskTicksProvider);
        long bt = taskTicks(b, taskTicksProvider);
        int missingCmp = Boolean.compare(at == Long.MAX_VALUE, bt == Long.MAX_VALUE);
        if (missingCmp != 0) return missingCmp;

        int timeCmp = Long.compare(at, bt);
        if (sortDirection == TaskListQuery.SortDirection.DESC)
        {
            timeCmp = -timeCmp;
        }
        if (timeCmp != 0) return timeCmp;
        return compareTaskName(a, b, false);
    }

    private static long completionTimestamp(XtremeTask task, Function<XtremeTask, CompletionInfo> completionInfoProvider)
    {
        CompletionInfo info = completionInfoProvider == null || task == null ? null : completionInfoProvider.apply(task);
        return info != null && info.timestamp > 0 ? info.timestamp : Long.MAX_VALUE;
    }

    private static long taskTicks(XtremeTask task, Function<XtremeTask, Long> taskTicksProvider)
    {
        Long ticks = taskTicksProvider == null || task == null ? null : taskTicksProvider.apply(task);
        return ticks != null && ticks > 0 ? ticks : Long.MAX_VALUE;
    }

    private static String safeName(XtremeTask task)
    {
        return task == null || task.getName() == null ? "" : task.getName();
    }

    private static String safeId(XtremeTask task)
    {
        return task == null || task.getId() == null ? "" : task.getId();
    }

    private static int tierRank(TaskTier tier)
    {
        if (tier == null)
        {
            return Integer.MAX_VALUE;
        }
        switch (tier)
        {
            case EASY:
                return 0;
            case MEDIUM:
                return 1;
            case HARD:
                return 2;
            case ELITE:
                return 3;
            case MASTER:
                return 4;
            case GRANDMASTER:
                return 5;
            default:
                return Integer.MAX_VALUE;
        }
    }

    private static int sourceRank(TaskSource source)
    {
        if (source == null)
        {
            return Integer.MAX_VALUE;
        }
        switch (source)
        {
            case COMBAT_ACHIEVEMENT:
                return 0;
            case COLLECTION_LOG:
                return 1;
            case DIARY_ACHIEVEMENT:
                return 2;
            default:
                return Integer.MAX_VALUE;
        }
    }

    private static int compareCountedCollectionLogSequence(XtremeTask a, XtremeTask b)
    {
        TaskVerification av = a == null ? null : a.getVerification();
        TaskVerification bv = b == null ? null : b.getVerification();
        if (!isCountedCollectionLog(av) || !isCountedCollectionLog(bv))
        {
            return 0;
        }

        if (a.getSource() != b.getSource() || a.getTier() != b.getTier())
        {
            return 0;
        }

        String aItems = canonicalItems(av.getItemIds());
        String bItems = canonicalItems(bv.getItemIds());
        if (aItems.isEmpty() || !Objects.equals(aItems, bItems))
        {
            return 0;
        }

        int aCount = av.getCount() == null ? 1 : av.getCount();
        int bCount = bv.getCount() == null ? 1 : bv.getCount();
        return Integer.compare(aCount, bCount);
    }

    private static boolean isCountedCollectionLog(TaskVerification verification)
    {
        return verification != null
                && verification.getType() == TaskVerification.VerificationType.COLLECTION_LOG
                && verification.getCount() != null;
    }

    private static String canonicalItems(int[] itemIds)
    {
        if (itemIds == null || itemIds.length == 0)
        {
            return "";
        }

        return Arrays.stream(itemIds)
                .filter(itemId -> itemId > 0)
                .distinct()
                .sorted()
                .mapToObj(String::valueOf)
                .collect(Collectors.joining(","));
    }

}

